"use strict";(self.webpackChunkkilimanjaro=self.webpackChunkkilimanjaro||[]).push([[182],{7833:n=>{n.exports=JSON.parse('{"archive":{"blogPosts":[{"id":"\u5b66\u4f1a\u65e0\u804a","metadata":{"permalink":"/kilimanjaro/\u5b66\u4f1a\u65e0\u804a","editUrl":"https://github.com/jing-gu/kilimanjaro/blog/2024-9-28-\u5b66\u4f1a\u65e0\u804a.md","source":"@site/blog/2024-9-28-\u5b66\u4f1a\u65e0\u804a.md","title":"\u5b66\u4f1a\u65e0\u804a","description":"\u4e5d\u697c","date":"2024-08-28T00:00:00.000Z","tags":[{"inline":false,"label":"\u80b2\u513f","permalink":"/kilimanjaro/tags/\u80b2\u513f","description":"\u80b2\u513f tag description"},{"inline":false,"label":"\u968f\u611f","permalink":"/kilimanjaro/tags/\u968f\u611f","description":"\u968f\u611f tag description"}],"readingTime":10.85,"hasTruncateMarker":false,"authors":[],"frontMatter":{"slug":"\u5b66\u4f1a\u65e0\u804a","title":"\u5b66\u4f1a\u65e0\u804a","tags":["\u80b2\u513f","\u968f\u611f"],"image":"https://i.imgur.com/mErPwqL.png","date":"2024-08-28T00:00:00.000Z"},"unlisted":false,"nextItem":{"title":"\u70f9\u8336\u81ea\u6c72\u6c34\uff0c\u4f55\u4e8b\u4e0d\u6e05\u5e7d","permalink":"/kilimanjaro/\u70f9\u8336\u81ea\u6c72\u6c34\u4f55\u4e8b\u4e0d\u6e05\u5e7d"}},"content":"![\u4e5d\u697c](./img/xuehuiwuliao1.jpg)\\n\u4e5d\u697c\uff0c\u662f\u6240\u6709\u6295\u884c\u540c\u4e8b\u6700\u7231\u6765\u7684\u5730\u65b9\uff0c\u8fd9\u91cc\u6709\u6211\u4eec\u81ea\u5df1\u7684\u5496\u5561\u5e08\uff0c\u5e26\u4e00\u4e2a\u676f\u5b50\u4e0a\u6765\u4ec0\u4e48\u90fd\u53ef\u4ee5\u70b9\u4e86\u559d\u3002\u672c\u6765\u5c31\u662f\u4e3a\u4e86\u4fc3\u8fdb\u4ea4\u6d41\u624d\u6709\u8fd9\u4e2a\u798f\u5229\u7684\uff0c\u7cbe\u82f1\u4eec\u5728\u8fd9\u91cc\u8c08\u9879\u76ee\uff0c\u804astrategy\uff0c\u548c\u7cbe\u82f1\u4eec\u6df7\u4e45\u4e86\u4f3c\u4e4e\u89c9\u5f97\u81ea\u5df1\u4e5f\u662f\u7cbe\u82f1\uff0c\u53ef\u6211\u603b\u662f\u628a\u8bdd\u9898\u804a\u6210\u4e86\u5b69\u5b50\u3002\\n\\n\u5468\u672b\u53bb\u4e86\u54ea\u91cc\uff0c\u5e72\u4e86\u4ec0\u4e48\uff0c\u90fd\u662f\u6211\u4eec\u4e00\u5bb6\u5e26\u4e24\u5c81\u7684\u5973\u513f\u5916\u51fa\uff0c\u53bb\u519c\u573a\u770b\u732a\u9a6c\u725b\u7f8a\uff0c\u53bb\u6cb3\u8fb9\u770b\u9e2d\u5b50\uff0c\u590f\u5929\u6458\u84dd\u8393\uff0c\u524d\u51e0\u5468\u6458\u82f9\u679c\uff0c\u6458\u7389\u7c73\uff0c\u9a6c\u4e0a\u79cb\u5929\u53c8\u8981\u53bb\u6458\u5357\u74dc\u4e86\u3002\\n\\n\u5f00\u5fc3\u7684\u540c\u65f6\u4e5f\u5f88\u7d2f\uff0c\u5c31\u662f\u90a3\u79cd\u600e\u4e48\u5468\u672b\u6bd4\u4e0a\u73ed\u8fd8\u7d2f\u7684\u611f\u89c9\u3002\u5e26\u5a03\u7684\u5973\u540c\u4e8b\u4eec\u4e5f\u7eb7\u7eb7\u8868\u793a\u5c31\u662f\u8fd9\u6837\uff0c\u8fd9\u5f88\u6b63\u5e38\u3002\u4f3c\u4e4e\u4e0d\u7ed9\u5b69\u5b50\u5b89\u6392\u5a31\u4e50\u5c31\u4e0d\u884c\u3002\\n\\n\u773c\u524d\u7684\u8fd9\u4e2a\u6cd5\u56fd\u7236\u4eb2\u662f\u6211\u7684\u4e00\u4e2a\u65b0\u540c\u4e8b\uff0c\u4ed6\u8bf4\u5728\u6cd5\u56fd\u5bf9\u5b69\u5b50\u6709\u8fd9\u4e48\u4e00\u4e2a\u8981\u6c42\uff1aIl faut apprendre \xe0 s\'ennuyer.\\n\\n\u8981\u8ba9\u5b69\u5b50\u5b66\u4f1a\u65e0\u804a\u3002\\n\\n\u6211\u4eec\u4ece\u5c0f\u90fd\u88ab\u8981\u6c42\u5b66\u4f1a\u5f88\u591a\uff0c\u8981\u5b66\u77e5\u8bc6\uff0c\u5b66\u793c\u8c8c\uff0c\u957f\u5927\u540e\u8981\u5b66\u6280\u80fd\uff0c\u5b66\u5de5\u4f5c\u3002\u4e0d\u5f00\u5fc3\u65f6\u5b66\u4e50\u89c2\u5f00\u6717\uff0c\u592a\u5f00\u5fc3\u65f6\u5b66\u6c89\u7740\u51b7\u9759\u3002\u5b66\u8868\u8fbe\uff0c\u5b66\u6536\u655b\uff0c\u5b66\u4f18\u96c5\uff0c\u5b66\u505a\u4eba\u3002\\n\\n\u4f46\u6ca1\u6709\u4eba\u8bf4\u8981\u5b66\u4f1a\u65e0\u804a\uff0c\u5c31\u662f\u5b66\u4f1a\u5728\u65e0\u4e8b\u53ef\u505a\u7684\u72b6\u6001\u4e0b\uff0c\u63a5\u53d7\u90a3\u4e2a\u72b6\u6001\uff0c\u5e76\u6109\u5feb\u7684\u5ea6\u8fc7\u90a3\u4e2a\u65f6\u95f4\u3002\\n\\n\u6211\u53d1\u73b0\u6cd5\u56fd\u4eba\u662f\u771f\u7684\u5f88\u61c2\u65e0\u804a\uff0c\u90a3\u4e9b\u7ecf\u5178\u7535\u5f71\u4e00\u60f3\u4e5f\u662f\u8fd9\u4e2a\u9053\u7406\u3002\u5929\u4f7f\u7231\u7f8e\u4e3d\u91cc\u7684\u65e0\u804a\uff0c\u523a\u732c\u7684\u5e7d\u96c5\u91cc\u7684\u65e0\u804a\uff0c\u4e24\u5c0f\u65e0\u731c\u4e5f\u662f\u3002\u5929\u4f7f\u7231\u7f8e\u4e3d\u662f\u771f\u7684\u65e0\u804a\uff0c\u770b\u7740\u770b\u7740\u4e5f\u89c9\u5f97\u6211\u81ea\u5df1\u5f88\u65e0\u804a\uff0c\u600e\u4e48\u4ed6\u4eec\u7684\u7535\u5f71\u603b\u662f\u8fd9\u6837\uff0c\u60f3\u60f3\u653e\u725b\u73ed\u7684\u6625\u5929\u597d\u50cf\u4e5f\u6709\u7c7b\u4f3c\u8bf4\u4e0d\u51fa\u7684\u65e0\u804a\u3002\u4f46\u8fd9\u51e0\u90e8\u7535\u5f71\u6211\u90fd\u5f88\u559c\u6b22\uff0c\u6bcf\u4e00\u90e8\u91cc\u90fd\u6709\u65e0\u804a\u7684\u5c0f\u5b69\u3002\\n\\n\u5f00\u7bc7\u5c31\u662f\u827e\u7c73\u8389\u7684\u4e00\u4e32\u65e0\u804a\u884c\u4e3a\uff0c\u8f6c\u624b\u6307\uff0c\u628a\u8138\u6324\u5728\u73bb\u7483\u7a97\u4e0a\u505a\u9b3c\u8138\uff0c\u628a\u6a31\u6843\u6302\u5728\u8033\u6735\u4e0a\u5f53\u8033\u73af\uff0c\u8f6c\u786c\u5e01\uff0c\u5439\u6811\u53f6\uff0c\u5439\u7eb8\u7247\uff0c\u628a\u6811\u8393\u5957\u5728\u5341\u4e2a\u624b\u6307\u4e0a\u518d\u4e00\u4e2a\u4e2a\u7684\u5403\u8fc7\u53bb\u3002\\n![Amelie](./img/xuehuiwuliao2.jpg)\\n\\n\u4ed6\u4eec\u7684\u5b69\u5b50\u5c31\u662f\u8fd9\u4e48\u957f\u5927\u7684\u4e48\uff1f\u8fd9\u4e0d\u662f\u73a9\u7684\u5f88\u5f00\u5fc3\u5f88\u53ef\u7231\u4e48\uff1f\u6ca1\u6709\u4e1c\u897f\u73a9\u4e0d\u4e5f\u662f\u53ef\u4ee5\u81ea\u5df1\u628a\u81ea\u5df1\u73a9\u7684\u5f88\u5f00\u5fc3\u4e48\uff1f\u4ed6\u4eec\u7684\u5b69\u5b50\u5c31\u662f\u8fd9\u4e48\u4ece\u5c0f\u5b66\u4f1a\u65e0\u804a\u3002\\n\\n\u4f46\u522b\u5fd8\u4e86\u5929\u4f7f\u7231\u7f8e\u4e3d\u7684\u6cd5\u8bed\u7247\u540d\u672c\u610f\u662f\uff1a\\"\u827e\u7c73\u8389\u7684\u5947\u5f02\u4e16\u754c\\"\uff0c\u5979\u5728\u65e0\u804a\u91cc\u5b66\u4f1a\u4e86\u521b\u9020\u4e00\u6574\u4e2a\u81ea\u5df1\u7684\u4e16\u754c\u554a\u3002\\n\\n\u8fd9\u6b63\u662f\u6211\u8fd9\u4f4d\u6cd5\u56fd\u540c\u4e8b\u7684\u80b2\u513f\u7406\u5ff5\uff0c\u5b69\u5b50\u5728\u5b66\u4f1a\u65e0\u804a\u7684\u65f6\u5019\u662f\u60f3\u8c61\u529b\u4e0e\u521b\u9020\u529b\u6700\u5f3a\u5927\u7684\u65f6\u5019\u3002\u4e0d\u9700\u8981\u79ef\u6728\uff0c\u62fc\u56fe\uff0c\u667a\u529b\u73a9\u5177\uff0c\u65e9\u6559\u73ed\uff0c\u5f88\u53ef\u80fd\u94b1\u82b1\u4e86\uff0c\u65f6\u95f4\u82b1\u4e86\uff0c\u5b69\u5b50\u8fd8\u662f\u4e0d\u4f1a\u73a9\uff0c\u53ea\u662f\u8fc7\u65e9\u5730\u5b66\u4e60\u4e86\u5927\u4eba\u7684\u6e38\u620f\u89c4\u5219\u3002\\n\\n\u5176\u5b9e\u8fd9\u4e0d\u662f\u6211\u7b2c\u4e00\u6b21\u542c\u8bf4\u6cd5\u56fd\u4eba\u5173\u4e8e\\"\u5b66\u4f1a\u65e0\u804a\\"\u7684\u7406\u8bba\u3002\u6211\u81ea\u5df1\u5728\u4f11\u4ea7\u5047\u65f6\u770b\u8fc7\u4e00\u672c\u80b2\u513f\u4e66\u53ebBring up b\xe9b\xe9\uff0c\u8bb2\u7684\u662f\u4f5c\u8005\u81ea\u5df1\uff0c\u4e00\u4e2a\u7f8e\u56fd\u8bb0\u8005\uff0c\u5728\u5df4\u9ece\u751f\u4e86\u5b69\u5b50\u5e76\u751f\u6d3b\u6240\u7ecf\u5386\u7684\u4e00\u7cfb\u5217\u7f8e\u5f0f\u80b2\u513f\u4e0e\u6cd5\u5f0f\u80b2\u513f\u4e4b\u95f4\u7684\u60ca\u8bb6\u4e0e\u51b2\u7a81\u3002\u5979\u53d1\u73b0\u81ea\u5df1\u603b\u5728\u5b69\u5b50\u5806\u91cc\u5fd9\u91cc\u5fd9\u5916\uff0c\u8eab\u8fb9\u7684\u5404\u79cd\u6cd5\u56fd\u5988\u5988\u5e38\u5e38\u81ea\u5df1\u5750\u90a3\u513f\u559d\u5496\u5561\uff0c\u5b69\u5b50\u5728\u65c1\u8fb9\u81ea\u5df1\u73a9\u3002\u4f60\u4f1a\u89c9\u5f97\u90a3\u4e2a\u5fd9\u91cc\u5fd9\u5916\u7684\u5988\u5988\u4ed8\u51fa\u66f4\u591a\u4e48\uff1f\u4e0d\u80fd\u8fd9\u4e48\u8868\u9762\u5730\u770b\u95ee\u9898\uff0c\u56e0\u4e3a\u5f53\u4f60\u5fd9\u5230\u505c\u4e0d\u4e0b\u6765\u624d\u81ea\u95ee\u5230\u5e95\u51fa\u4e86\u4ec0\u4e48\u95ee\u9898\u65f6\u5c31\u79bb\u5d29\u6e83\u4e0d\u8fdc\u4e86\uff0c\u6cd5\u56fd\u5988\u5988\u662f\u6709\u81ea\u77e5\u4e4b\u660e\u7684\uff0c\u786e\u4fdd\u81ea\u5df1\u6ca1\u6709\u88ab\u5ffd\u89c6\uff0c\u624d\u4f1a\u6709\u66f4\u5f3a\u5927\u7684\u5185\u6838\u53bb\u7167\u987e\u4e00\u4e2a\u66f4\u5c0f\u7684\u751f\u547d\u3002\\n\\n\u6cd5\u56fd\u5988\u5988\u544a\u8bc9\u7f8e\u56fd\u5988\u5988\uff0c\u8981\u8ba9\u4f60\u7684\u5b69\u5b50\u5b66\u4f1a\u65e0\u804a\u3002\u8bfb\u8fd9\u4e2a\u6545\u4e8b\u7684\u6211\u5728\u7b49\u5f85\u81ea\u5df1\u7684\u5c0f\u751f\u547d\uff0c\u4eff\u4f5b\u4e00\u4e2a\u8fdc\u8fdc\u7684\u89c2\u5bdf\u8005\uff0c\u5e76\u4e0d\u77e5\u9053\u4f1a\u53d8\u6210\u54ea\u79cd\u5988\u5988\u3002\u7ec8\u4e8e\u6709\u4e00\u5929\u518d\u6b21\u548c\u4e00\u4e2a\u6cd5\u56fd\u7238\u7238\u804a\u5929\u65f6\u624d\u53d1\u89c9\uff0c\u539f\u6765\u4f60\u4eec\u771f\u7684\u662f\u8fd9\u4e48\u4e2a\u80b2\u513f\u7684\u624b\u6bb5\u554a\uff0c\u5b66\u4f1a\u65e0\u804a\u8fd9\u4e2a\u75d5\u8ff9\u624d\u518d\u6b21\u8fdb\u5165\u5927\u8111\u3002\\n\\n\u9664\u4e86s\'ennuyer \u201c\u65e0\u804a\u201d\u8fd9\u4e2a\u52a8\u8bcd\uff0c\u7b2c\u4e8c\u4e2a\u5e38\u6302\u6cd5\u56fd\u4eba\u5634\u8fb9\u7684\u662f d\xe9couvrir \u201c\u53d1\u73b0\u201d, \u8fd9\u4e2a\u662f\u6211\u53d1\u73b0\u7684\u3002\u4f60\u4e0d\u89c9\u5f97\u65e0\u804a\u548c\u53d1\u73b0\u7684\u5173\u7cfb\u5f88\u5fae\u5999\u4e48\uff1f\u53ea\u6709\u5728\u65e0\u804a\u7684\u65f6\u5019\u624d\u4f1a\u53d1\u73b0\u554a\uff1f\u4e00\u4e2a\u5927\u8111\u5df2\u88ab\u586b\u6ee1\u884c\u7a0b\u4e5f\u88ab\u586b\u6ee1\u7684\u5b69\u5b50\uff0c\u8fd8\u6709\u4ec0\u4e48\u9700\u8981\u53d1\u73b0\u7684\u5462\uff1f\\n\\n\u534e\u4eba\u5708\u7684\u5f88\u591a\u5e26\u5a03\u884c\u4e3a\u591a\u6570\u53d7\u7f8e\u5f0f\u80b2\u513f\u5f71\u54cd\uff0c\u6df1\u5ea6\u966a\u4f34\uff0c\u8fc7\u5ea6\u91cd\u89c6\uff0c\u53ef\u8981\u5230\u591a\u5927\u624d\u4f1a\u660e\u767d\u539f\u6765\u8fd9\u4e2a\u4e16\u754c\u5e76\u4e0d\u662f\u56f4\u7740\u4f60\u8fd9\u4e2a\u5c0f\u4eba\u8f6c\u7684\uff1f\\n\\n\u6cd5\u56fd\u5bb6\u957f\u7684\u89c2\u5ff5\u662f Delayed gratification: \u5ef6\u8fdf\u4eab\u4e50\u3002\u8fd9\u662f\u4e00\u4e2a\u6211\u4eec\u5728\u6210\u5e74\u540e\u624d\u63d0\u51fa\u7684\uff08\u4f9d\u7136\u591a\u6570\u4eba\u505a\u4e0d\u5230\u7684\uff09\u8981\u6c42\uff0c\u6cd5\u56fd\u5b69\u5b50\u5374\u88ab\u4ece\u5c0f\u704c\u8f93\u4e86\u3002\u8fd9\u4e00\u5757\u997c\u5e72\u4f60\u73b0\u5728\u4e0d\u8981\u5403\uff0c\u7b49\u6211\u56de\u6765\u4f60\u518d\u5403\uff0c\u90a3\u4e48\u6211\u4f1a\u518d\u7ed9\u4f60\u4e00\u5757\uff0c\u5982\u679c\u4f60\u73b0\u5728\u5403\u4e86\u5c31\u53ea\u6709\u8fd9\u4e00\u5757\u3002\\n\\n\u6709\u56e2\u961f\u505a\u8fc7\u8fd9\u4e2a\u5b9e\u9a8c\uff0c\u628a\u4e00\u7fa4\u5b69\u5b50\u5206\u522b\u5173\u5728\u4e0d\u540c\u7684\u7a7a\u623f\u95f4\u91cc\uff0c\u53ea\u7ed9\u4e00\u5757\u997c\u5e72\uff0c\u5e76\u8bf4\u53ea\u8981\u4e0d\u5403\u5c31\u80fd\u6700\u540e\u5f97\u5230\u4e24\u5757\uff0c\u65f6\u95f4\u5927\u6982\u4e8c\u5341\u5206\u949f\u3002\u5b69\u5b50\u4eec\u7684\u8868\u73b0\u5343\u59ff\u767e\u6001\uff0c\u4e0d\u660e\u767d\u6216\u4e0d\u5728\u4e4e\u7684\u7acb\u523b\u5c31\u5403\u4e86\uff0c\u5f53\u4e0b\u5f88\u5f00\u5fc3\uff0c\u63a5\u4e0b\u6765\u7684\u4e8c\u5341\u5206\u949f\u5728\u7a7a\u623f\u95f4\u91cc\u6b47\u65af\u5e95\u91cc\u3002\u660e\u767d\u9053\u7406\u7684\u5b69\u5b50\u4e00\u76f4\u76ef\u7740\u997c\u5e72\u770b\uff0c\u544a\u8bc9\u81ea\u5df1\u4e0d\u8981\u5403\uff0c\u626d\u5934\u4e0d\u770b\uff0c\u53c8\u6293\u6293\u997c\u5e72\uff0c\u518d\u653e\u4e0b\uff0c\u4f46\u7ec8\u7a76\u8fd8\u662f\u62b5\u5236\u4e0d\u4f4f\u8bf1\u60d1\uff0c\u628a\u997c\u5e72\u5403\u4e86\u3002\u6cd5\u56fd\u5b69\u5b50\u4f3c\u4e4e\u4ece\u5934\u5230\u5c3e\u5c31\u6ca1\u770b\u5230\u90a3\u4e2a\u997c\u5e72\uff0c\u5728\u7a7a\u7a7a\u7684\u623f\u95f4\u91cc\u8e66\u6765\u8e66\u53bb\uff0c\u5439\u7a7a\u6c14\uff0c\u5531\u6b4c\uff0c\u624b\u821e\u8db3\u8e48\uff0c\u5728\u65e0\u804a\uff0c\u4e8c\u5341\u5206\u949f\u5f88\u5feb\u5c31\u8fc7\u53bb\u4e86\uff0c\u5f97\u5230\u4e24\u5757\u997c\u5e72\u3002\\n\\n\u533a\u522b\u5728\u54ea\u91cc\u5462\uff1f\u8981\u505a\u5230\u5ef6\u8fdf\u4eab\u4e50\u5c31\u8981\u5148\u62b5\u5236\u8bf1\u60d1\uff0c\u8fd9\u8fde\u6210\u4eba\u90fd\u505a\u4e0d\u5230\uff0c\u53c8\u600e\u4e48\u53ef\u80fd\u6307\u671b\u5b69\u5b50\u505a\u5230\uff1f\u4f46\u62b5\u5236\u8bf1\u60d1\u7684\u5173\u952e\u4ece\u6765\u4e0d\u662f\u62b5\u5236\u6216\u610f\u5fd7\u529b\uff0c\u800c\u662f\u5206\u6563\u6ce8\u610f\u529b\u3002\u8d8a\u662f\u62b5\u5236\uff0c\u8d8a\u662f\u76ef\u7740\u90a3\u4e2a\u997c\u5e72\u770b\uff0c\u8d8a\u662f\u65e0\u6cd5\u62b5\u5236\u3002\u4f46\u5206\u6563\u6ce8\u610f\u529b\uff0c\u5374\u662f\u7b80\u5355\u5230\u8fde\u5b69\u5b50\u90fd\u53ef\u4ee5\u505a\u5230\u3002\\n\\n\u5b66\u4f1a\u65e0\u804a\u7684\u5b69\u5b50\u81ea\u5df1\u5b66\u4f1a\u4e86\u8010\u5fc3\u7b49\u5f85\uff0c\u539f\u6765\u6b32\u671b\u4e0d\u9700\u8981\u7acb\u523b\u6ee1\u8db3\uff0c\u539f\u6765\u4e00\u5207\u4e0d\u662f\u4f38\u624b\u5c31\u6765\u3002\\n\\n\u6211\u7684\u90bb\u5c45\u662f\u5f88\u5178\u578b\u7684\u7f8e\u5f0f\u80b2\u513f\uff0c\u5988\u5988\u51b3\u5b9a\u5728\u5bb6\u5168\u804c\u80b2\u513f\u4e94\u5e74\uff0c\u4e0d\u53bb\u65e5\u6258\uff0c\u4e00\u5207\u81ea\u5df1\u6258\uff0c\u63d0\u524d\u4e09\u5e74\u62dc\u8bbf\u5b66\u6821\u4e3a\u4e86\u627e\u5230\u5fc3\u4eea\u7684\u5e7c\u513f\u56ed\uff0c\u5e76\u5df2\u7ecf\u52a0\u5165\u7b49\u5f85\u540d\u5355\u3002\u5f53\u65f6\u542c\u5f97\u6211\u5fc3\u810f\u90fd\u5feb\u7206\u70b8\u4e86\uff0c\u6211\u5bb6\u624d\u4e00\u5c81\u534a\uff0c\u5979\u5bb6\u6bd4\u6211\u5bb6\u8fd8\u5c0f\u516d\u4e2a\u6708\u5462\uff01\u5979\u5df2\u7ecf\u60f3\u597d\u4e86\u53bb\u79c1\u6821\uff0c\u4e0d\u53bb\u516c\u7acb\uff0c\u54ea\u91cc\u54ea\u91cc\uff0c\u8fd9\u8def\u94fa\u7684\u4e00\u671b\u65e0\u9645\u3002\\n\\n\u76f8\u6bd4\u4e4b\u4e0b\u6211\u4ec0\u4e48\u90fd\u6ca1\u8ba1\u5212\uff0c\u6211\u628a\u8fd9\u4e00\u56e2\u7126\u8651\u7edf\u7edf\u8f6c\u8fbe\u7ed9\u5bb6\u5c5e\uff0c\u4ed6\u8bf4\u6ca1\u4e8b\u7684\uff0c\u5b69\u5b50\u4f1a\u957f\u5927\u3002\u6211\u5e38\u5e38\u9700\u8981\u4ed6\u628a\u6211\u90a3\u4e9b\u521d\u9732\u82d7\u5934\u7684\u7126\u8651\u6390\u706d\uff0cIt\'s ok. It\'s ok.\\n\\n\u6211\u95ee\u90a3\u6cd5\u56fd\u7236\u4eb2\uff0c\u4f60\u4f1a\u8ba1\u5212\u4f60\u5b69\u5b50\u4ee5\u540e\u5e72\u4ec0\u4e48\u9009\u4ec0\u4e48\u804c\u4e1a\u4e48\uff1f\u4e0d\u5728\u8ba1\u5212\u5185\u3002\u4f60\u5b69\u5b50\u8981\u662f\u60f3\u505a\u9762\u5305\u5462\uff1f\u90a3\u5c31\u505a\u9762\u5305\u53bb\u5427\u3002\\n\\n\u6211\u5e38\u60f3\u201c\u6cd5\u5f0f\u201d\u5230\u5e95\u662f\u6709\u4ec0\u4e48je ne sais quoi\u9b45\u529b\u5728\u90a3\u91cc\uff0c\u6cd5\u5f0f\u6175\u61d2\uff0c\u6cd5\u5f0f\u6d6a\u6f2b\uff0c\u677e\u5f1b\u611f\u5927\u6982\u4e5f\u5206\u4e09\u516d\u4e5d\u7b49\uff0c\u6cd5\u5f0f\u677e\u5f1b\u611f\uff0c\u4f60\u4ece\u6ca1\u542c\u8fc7\u7f8e\u5f0f\u677e\u5f1b\uff0c\u4ed6\u4eec\u6c38\u8fdc\u4e5f\u677e\u5f1b\u4e0d\u4e86\u3002\u8fd9\u4e00\u5207\u7684\u6e90\u5934\u662f\u4e0d\u662f\u90fd\u6765\u81ea\u4e8e\u6cd5\u5f0f\u65e0\u804a\uff1f\u662f\u4e0d\u662f\u5b66\u4f1a\u65e0\u804a\u4ee5\u540e\uff0c\u54ea\u5929\u6211\u5c31\u81ea\u5e26\u677e\u5f1b\u611f\u4e86\u3002\\n\\n\u7f8e\u56fd\u4eba\u4e5f\u77e5\u9053\u6cd5\u56fd\u4eba\u9aa8\u5b50\u91cc\u90a3\u5957\u65e0\u804a\u3002\u6700\u8fd1\u770b\u5b8cInsideout2 \uff08\u5934\u8111\u7279\u5de5\u961f\uff09\u7b2c\u4e8c\u90e8\u91cc\u65b0\u52a0\u4e86\u51e0\u4e2a\u5fc3\u60c5\u5361\u901a\u4eba\u7269\u3002\u7b2c\u4e00\u90e8\u91cc\u90a3\u4e94\u4e2a\u7ecf\u5178\u7684\u5fc3\u60c5\u662f\uff1a\u5f00\u5fc3Joy\uff0c\u60b2\u4f24Sadness\uff0c\u60e7\u6015Fear\uff0c\u751f\u6c14Anger \uff0c\u538c\u6076Disgust \uff0c\u7b2c\u4e8c\u90e8\u65b0\u52a0\u7684\u662f\uff1a\u7126\u8651Anxiety \uff0c\u5ac9\u5992Envy\uff0c\u5c34\u5c2cEmbarrassment \uff0c\u8fd8\u6709\u65e0\u804aEnnui \u3002\u6ce8\u610f\u5230\u4e86\u6ca1\uff0c\u6240\u4ee5\u4eba\u7269\u7684\u540d\u5b57\u5c31\u662f\u4ed6\u6240\u5bf9\u5e94\u7684\u90a3\u4e2a\u5fc3\u60c5\u7684\u82f1\u8bed\u5355\u8bcd\uff0c\u552f\u72ec\u65e0\u804aEnnui\uff0c\u662f\u4e2a\u6cd5\u8bed\u5355\u8bcd\u3002\u4ed6\u7684\u4eba\u7269\u9020\u578b\u4e5f\u662f\u4e2a\u4e27\u4e27\u7684\u6cd5\u56fd\u8138\uff0c\u65e0\u804a\u5230\u4e0d\u8bf4\u8bdd\uff0c\u4e00\u5f00\u53e3\u5c31\u662foh lala, pardon excusez-moi\uff0c\u552f\u4e00\u4e00\u4e2a\u5728\u82f1\u8bed\u52a8\u753b\u91cc\u8bb2\u6cd5\u8bed\u7684\u5f62\u8c61\uff0c\u56e0\u4e3a\u4ed6\u662f\u65e0\u804a\u3002\\n\\n![Inside-out2](./img/xuehuiwuliao3.jpg)"},{"id":"\u70f9\u8336\u81ea\u6c72\u6c34\u4f55\u4e8b\u4e0d\u6e05\u5e7d","metadata":{"permalink":"/kilimanjaro/\u70f9\u8336\u81ea\u6c72\u6c34\u4f55\u4e8b\u4e0d\u6e05\u5e7d","editUrl":"https://github.com/jing-gu/kilimanjaro/blog/2024-1-15-\u70f9\u8336\u81ea\u6c72\u6c34\u4f55\u4e8b\u4e0d\u6e05\u5e7d.md","source":"@site/blog/2024-1-15-\u70f9\u8336\u81ea\u6c72\u6c34\u4f55\u4e8b\u4e0d\u6e05\u5e7d.md","title":"\u70f9\u8336\u81ea\u6c72\u6c34\uff0c\u4f55\u4e8b\u4e0d\u6e05\u5e7d","description":"\u5bb6\u5c5e\u662f\u4e00\u4e2a\u957f\u7740\u4e9a\u6d32\u8138\u7684\u6d0b\u9b3c\u5b50\uff0c\u5374\u53c8\u6709\u4e00\u4e2a\u6df1\u4e0d\u53ef\u6d4b\u7684\u4e2d\u56fd\u8da3\u5473\uff1a\u7d2b\u7802\u58f6\u3002","date":"2024-01-15T00:00:00.000Z","tags":[{"inline":false,"label":"\u5bb6\u5ead","permalink":"/kilimanjaro/tags/\u5bb6\u5ead","description":"\u5bb6\u5ead tag description"},{"inline":false,"label":"\u968f\u611f","permalink":"/kilimanjaro/tags/\u968f\u611f","description":"\u968f\u611f tag description"}],"readingTime":8.735,"hasTruncateMarker":false,"authors":[],"frontMatter":{"slug":"\u70f9\u8336\u81ea\u6c72\u6c34\u4f55\u4e8b\u4e0d\u6e05\u5e7d","title":"\u70f9\u8336\u81ea\u6c72\u6c34\uff0c\u4f55\u4e8b\u4e0d\u6e05\u5e7d","tags":["\u5bb6\u5ead","\u968f\u611f"],"date":"2024-01-15T00:00:00.000Z"},"unlisted":false,"prevItem":{"title":"\u5b66\u4f1a\u65e0\u804a","permalink":"/kilimanjaro/\u5b66\u4f1a\u65e0\u804a"},"nextItem":{"title":"\u6700\u597d\u4e0d\u8fc7\u91d1\u9f9f\u6362\u9152","permalink":"/kilimanjaro/\u6700\u597d\u4e0d\u8fc7\u91d1\u9f9f\u6362\u9152"}},"content":"\u5bb6\u5c5e\u662f\u4e00\u4e2a\u957f\u7740\u4e9a\u6d32\u8138\u7684\u6d0b\u9b3c\u5b50\uff0c\u5374\u53c8\u6709\u4e00\u4e2a\u6df1\u4e0d\u53ef\u6d4b\u7684\u4e2d\u56fd\u8da3\u5473\uff1a\u7d2b\u7802\u58f6\u3002\\n\\n\u5723\u8bde\u8282\u524d\uff0c\u6211\u4eec\u8ba1\u5212\u4e86\u4e09\u5468\u56de\u56fd\u63a2\u4eb2\u7684\u884c\u7a0b\uff0c\u800c\u4ed6\u70b9\u540d\u8981\u53bb\u7684\u5730\u65b9\u53ea\u6709\u4e00\u4e2a\uff1a\u5b9c\u5174\u3002\\n\\n\u5341\u4e8c\u6708\u672b\u5df2\u662f\u5bd2\u98ce\u51db\u51bd\uff0c\u90a3\u6761\u5b9c\u5174\u7684\u53e4\u5357\u8857\u5e94\u8be5\u4f1a\u5728\u6625\u6696\u82b1\u5f00\u7684\u65f6\u5019\u66f4\u6709\u4eba\u6c14\u3002\u5373\u4fbf\u5982\u6b64\uff0c\u5bb6\u5c5e\u706b\u70ed\u7684\u5fc3\u5df2\u4e00\u5934\u624e\u8fdb\u8336\u58f6\uff0c\u89c6\u7d2b\u7802\u5982\u73cd\u5b9d\uff0c\u51e0\u5bb6\u5e97\u4e0b\u6765\uff0c\u81ea\u6211\u611f\u6000\u8981\u662f\u8fd9\u91cc\u6709\u6696\u6c14\u4fbf\u8981\u4f4f\u5728\u8fd9\u6761\u8857\u4e0a\u3002\u5bb6\u5c5e\u9047\u5230\u4e86\u6731\u6ce5\u7684\u624b\u5de5\u58f6\uff0c\u6700\u7ec8\u5e26\u8d70\u4e24\u628a\u58f6\u56db\u4e2a\u676f\u4e24\u53ea\u8336\u5ba0\uff0c\u53c8\u611f\u6168\uff0c\u4ee5\u540e\u53ea\u8981\u56de\u56fd\u5c31\u6765\u4e00\u8d9f\u5b9c\u5174\u5427\uff0c\u6211\u7acb\u523b\u6253\u6d88\u4e86\u6bcf\u5e74\u56de\u56fd\u7684\u5ff5\u5934\uff0c\u5bb6\u91cc\u7684\u8336\u58f6\u5df2\u662f\u9010\u5e74\u589e\u591a\u554a\u3002\\n\\n\u5728\u5bb6\u7684\u65e5\u5b50\uff0c\u5c31\u662f\u6bcf\u5929\u6ce1\u8336\uff0c\u804a\u5929\u90fd\u5728\u8336\u684c\u4e0a\u5c55\u5f00\uff0c\u7236\u6bcd\u548c\u5bb6\u5c5e\u4e24\u65b9\u7684\u8bed\u8a00\u80fd\u529b\u5728\u77ed\u77ed\u4e09\u5468\u5185\u90fd\u7a81\u98de\u731b\u8fdb\u3002\u5bb6\u6bcd\u9760\u7740\u8e66\u5355\u8bcd\u6765\u8868\u8fbe\u542b\u4e49\uff0c\u5728\u67d0\u65e5\u5bb4\u8bf7\u7684\u996d\u684c\u4e0a\u88ab\u95ee\u82f1\u8bed\u51e0\u7ea7\uff0c\u60f3\u5fc5\u662f\u8bed\u51fa\u60ca\u4eba\uff0c\u5982\u6b64\u53d1\u95ee\u663e\u7136\u5df2\u662f\u83ab\u5927\u7684\u8912\u5956\u3002\u5bb6\u5c5e\u7684\u4e2d\u6587\u6c34\u5e73\u5b9e\u5728\u6709\u9650\uff0c\u5c31\u90a3\u6709\u9650\u7684\u8bcd\u6c47\u91cc\u51e0\u4e4e\u90fd\u662f\u201c\u751f\u666e\u201d,\u201c\u719f\u666e\u201d, \u201c\u517b\u58f6\u201d,\u201c\u6302\u6c34\u201d\u7b49\uff0c\u6216\u662f\u201c\u9971\u4e86\u201d\uff0c\u201c\u591f\u4e86\u201d\u7b49\u63a8\u8131\u4e4b\u8bcd\u3002\u6709\u65f6\u6211\u4e0d\u5728\u573a\uff0c\u8336\u684c\u6216\u996d\u684c\u4e0a\u5c31\u5e38\u6709\u9a74\u5507\u4e0d\u5bf9\u9a6c\u5634\u7684\u5bf9\u8bdd\u3002\\n\\n\u4e00\u65e5\u996d\u540e\u6211\u628a\u5973\u513f\u5b89\u987f\u5348\u7761\uff0c\u5bb6\u5c5e\u8bf4\u521a\u624d\u5988\u5988\u53ef\u80fd\u6ca1\u660e\u767d\u81ea\u5df1\u7684\u610f\u601d\uff0c\u4ed6\u8bf4\u81ea\u5df1\u4e0d\u60f3\u5403\u751f\u9ec4\u74dc\u3002\u8f6c\u8ff0\u540e\uff0c\u5bb6\u6bcd\u604d\u7136\u5927\u609f\uff0c\u662f\u201c\u751f\u201d\u554a\uff0c\u8fd8\u4ee5\u4e3a\u662f\u201c\u5c71\u201d\u5462\uff0c\u7ed3\u679c\u4e00\u9519\u518d\u9519\uff0c\u76f2\u731c\u9ec4\u74dc\u662f\u5c71\u4e0a\u957f\u7684\u6240\u4ee5\u4e0d\u80fd\u5403\u5417\uff1f\u540e\u6765\u7684\u996d\u684c\u4e0a\u5e38\u51fa\u73b0\u4e9b\u8349\u7a3f\u672c\uff0c\u4ece\u4e0a\u9762\u7684\u6c49\u5b57\uff0c\u5355\u8bcd\uff0c\u548c\u6d82\u9e26\uff0c\u6211\u5927\u6982\u5c31\u77e5\u9053\u804a\u4e86\u4ec0\u4e48\uff0c\u6216\u5b66\u4e86\u4ec0\u4e48\u3002\\n\\n\u4ee5\u524d\u5c31\u548c\u5bb6\u5c5e\u8bf4\u8fc7\uff0c\u4e0d\u5b66\u70b9\u4e2d\u6587\u6765\u4e86\u4f1a\u5bf8\u6b65\u96be\u884c\u7684\u3002\u4f46\u5176\u5b9e\u6211\u53d1\u73b0\uff0c\u81ea\u5df1\u4e00\u4e2a\u66fe\u7ecf\u7684\u672c\u5730\u4eba\uff0c\u4f9d\u7136\u5bf8\u6b65\u96be\u884c\u3002\u5728\u624b\u673a\u652f\u4ed8\u65e0\u5b54\u4e0d\u5165\u7684\u571f\u5730\u4e0a\uff0c\u8bed\u8a00\u597d\u50cf\u4e0d\u91cd\u8981\u4e86\uff0c\u81f3\u5c11\u5bf9\u4e8e\u6c9f\u901a\u6ca1\u90a3\u4e48\u5fc5\u8981\uff0c\u56e0\u4e3a\u5f88\u591a\u60c5\u51b5\u4e0b\u6839\u672c\u6ca1\u6709\u6c9f\u901a\u3002\\n\\n\u53bb\u8fd0\u6cb3\u535a\u7269\u9986\u7684\u90a3\u5929\uff0c\u5230\u4e86\u996d\u70b9\uff0c\u5bb6\u7236\u60f3\u5403\u9633\u6625\u9762\uff0c\u5bb6\u5c5e\u60f3\u5403\u80af\u5fb7\u57fa\uff0c\u4fe9\u4eba\u540c\u65f6\u540c\u5730\u601d\u5ff5\u5404\u81ea\u5bb6\u4e61\u7f8e\u98df\u3002\u8f97\u8f6c\u6765\u5230\u80af\u5fb7\u57fa\uff0c\u6211\u548c\u5bb6\u5c5e\u5f88\u81ea\u7136\u5730\u6765\u5230\u67dc\u53f0\u524d\uff0c\u60f3\u70b9\u5355\u5374\u53d1\u73b0\u91cc\u5916\u4e00\u7247\u5fd9\u788c\uff0c\u67dc\u53f0\u540e\u7684\u5458\u5de5\u5fd9\u7684\u65e0\u6687\u987e\u53ca\u5468\u56f4\uff0c\u9891\u9891\u53eb\u53f7\uff0c\u67dc\u53f0\u4e0a\u6446\u6ee1\u4e86\u6258\u76d8\u3002\u6211\u4eff\u4f5b\u96f7\u5288\u4e00\u822c\u987f\u609f\uff0c\u6ca1\u6709\u4eba\u5de5\u70b9\u5355\u7684\uff0c\u6211\u62c9\u7740\u5bb6\u5c5e\u8d76\u7d27\u64a4\u9000\uff0c\u672b\u4e86\u53c8\u662f\u5bb6\u6bcd\u5728\u67d0\u5c0f\u7a0b\u5e8f\u4e0a\u4e00\u987f\u64cd\u4f5c\u624d\u70b9\u5355\u652f\u4ed8\u6210\u529f\u3002\u90a3\u65f6\u90fd\u56de\u5bb6\u4e24\u5468\u591a\u4e86\uff0c\u5bf9\u4e8e\u4ec0\u4e48\u4e8b\u90fd\u7528\u624b\u673a\u4e0b\u5355\u4f9d\u65e7\u96be\u4ee5\u9002\u5e94\u3002\\n\\n\u8fd9\u671f\u95f4\u6211\u6709\u56db\u4e94\u5e74\u6ca1\u56de\u56fd\uff0c\u4ee5\u5f80\u5fae\u4fe1\u652f\u4ed8\u7b49\u626b\u7801\u7684\u6982\u5ff5\u5c31\u5df2\u7ecf\u5f88\u5e38\u89c1\u4e86\uff0c\u4f46\u624b\u673a\u70b9\u5355\u7edd\u5bf9\u6ca1\u8fd9\u4e48\u666e\u53ca\u3002\u73b0\u5728\u89c9\u5f97\u8d8a\u662f\u9ad8\u6863\u7684\u9910\u5385\u8d8a\u662f\u6ca1\u83dc\u5355\uff0c\u4e5f\u6ca1\u4eba\u542c\u4f60\u8bf4\uff0c\u4eba\u5728\u5e97\u91cc\u5374\u8fd8\u6252\u7740\u624b\u673a\uff0c\u5982\u540c\u5728\u5bb6\u70b9\u5916\u5356\u3002\\n\\n\u8fc7\u4e8e\u7535\u5b50\u5316\u7684\u751f\u6d3b\u662f\u597d\u4e8b\u5417\uff1f\u5982\u679c\u7535\u8111\u7684\u9ad8\u6548\u727a\u7272\u4e86\u4eba\u9645\u7684\u6c9f\u901a\uff0c\u6211\u4eec\u53c8\u6210\u4e86\u4ec0\u4e48\u5462\uff1f\\n\\n\u5bb6\u5c5e\u6ca1\u6709\u3001\u4e0d\u9700\u8981\u3001\u4e5f\u4e0d\u88c5\u5fae\u4fe1\uff0c\u6bd4\u6211\u66f4\u4e0d\u9002\u5408\u8fd9\u6837\u7684\u793e\u4f1a\uff0c\u56e0\u4e3a\u4ed6\u662f\u4e2a\u6bd4\u6211\u66f4\u559c\u6b22\u5206\u4eab\u66f4\u559c\u6b22\u6c9f\u901a\u7684\u4eba\u3002\u6211\u7a81\u7136\u60f3\u8d77\u6765\u4e00\u6bb5\u65e9\u671f\u7684\u6545\u4e8b\uff0c\u7ed3\u5a5a\u7b2c\u4e00\u5e74\u65f6\uff0c\u5bb6\u91cc\u6536\u5230\u7535\u8d39\u5355\uff0c\u51e0\u5929\u540e\u4ed6\u8bf4\u6211\u4eec\u53bb\u94f6\u884c\u4ea4\u7535\u8d39\u5427\u3002\u6211\u8bf4\u8fd9\u79cd\u5c0f\u4e8b\u624b\u673a\u94f6\u884c\u76f4\u63a5\u4ea4\u4e86\u5427\uff0c\u5c45\u7136\u8fd8\u4e13\u95e8\u8dd1\u4e00\u8d9f\u94f6\u884c\u3002\u4ed6\u8bf4\u6709\u4e2a\u7406\u7531\u51fa\u95e8\u4e00\u8d9f\u4e0d\u662f\u5f88\u597d\u5417\uff0c\u6211\u4eec\u4e00\u8d77\u8d70\u8d70\u8def\u8bf4\u8bdd\uff0c\u770b\u770b\u5e97\u91cc\u6709\u4ec0\u4e48\u6253\u6298\u7684\uff0c\u5929\u6c14\u597d\u53ef\u4ee5\u5750\u5728\u5496\u5561\u5e97\u9732\u53f0\uff0c\u56de\u6765\u7684\u8def\u4e0a\u518d\u4e70\u4e9b\u8d1d\u679c\u3002\u4ed6\u5b8c\u5168\u6ca1\u63d0\u7f34\u8d39\u8fd9\u4ef6\u4e8b\uff0c\u6211\u5374\u88ab\u8fd9\u6bb5\u63cf\u8ff0\u542c\u7684\u5165\u8ff7\uff0c\u697c\u4e0b\u7684\u8857\u9053\u4f3c\u4e4e\u4ece\u672a\u5982\u6b64\u4f18\u96c5\u3002\\n\\n\u5f88\u5feb\u8d70\u5230\u4ed6\u5e38\u53bb\u7684\u94f6\u884c\uff0c\u5bf9\u4e00\u5207\u4eba\u4e8b\u7269\u90fd\u5f88\u719f\u6089\uff0c\u5c31\u8fd9\u6837\uff0c\u7b80\u5355\u7684\u529e\u4e8b\u52a0\u4e00\u4e9b\u53cb\u597d\u7684\u9898\u5916\u8bdd\u3002\u8fd9\u201c\u65e0\u804a\u7684\u5dee\u4e8b\u201d\u4ed6\u662f\u771f\u7684\u4e50\u5728\u5176\u4e2d\uff0c\u7f34\u8d39\u7eed\u8d39\u90fd\u662f\u6b21\u8981\u7684\uff0c\u4ed6\u5374\u603b\u80fd\u771f\u8bda\u5730\u4e0e\u964c\u751f\u4eba\u804a\u5929\uff0c\u8fd9\u4e00\u70b9\u8ba9\u6211\u5f88\u4f69\u670d\u3002\u6bcf\u6b21\u89c2\u5bdf\u4ed6\u4e0e\u4eba\u5bf9\u8bdd\u7684\u6837\u5b50\uff0c\u6211\u603b\u60f3\u4ed6\u90a3\u6bd4\u6211\u5e74\u957f\u5374\u892a\u4e0d\u53bb\u7684\u5c11\u5e74\u611f\u4ece\u4f55\u800c\u6765\u3002\\n\\n\u51e0\u5e74\u524d\u4e70\u65b0\u623f\u7684\u65f6\u5019\uff0c\u6211\u4eec\u7684\u8d37\u6b3e\u5c31\u662f\u4ece\u8fd9\u5bb6\u94f6\u884c\u529e\u7406\u7684\u3002\u5728\u4ed6\u7406\u8d22\u7ecf\u7406\u7684\u5185\u63a8\u4e0b\u8ba4\u8bc6\u4e86\u623f\u8d37\u7ecf\u7406\u5e76\u4ece\u800c\u62ff\u5230\u4e86\u8d85\u4f4e\u7684\u623f\u8d37\u5229\u7387\uff0c\u53ea\u6709\u767e\u5206\u4e4b\u4e00\u70b9\u4e94\u4e0d\u5230\uff0c\u968f\u540e\u7684\u4e00\u5e74\u5f00\u59cb\u4e86\u75ab\u60c5\u3001\u6218\u4e89\u3001\u7b49\u8fde\u9501\u53cd\u5e94\u4e0b\u7684\u901a\u8d27\u81a8\u80c0\uff0c\u52a0\u62ff\u5927\u592e\u884c\u7684\u57fa\u51c6\u5229\u7387\u5df2\u5feb\u4e0a\u6da8\u5230\u767e\u5206\u4e4b\u4e03\uff0c\u91cd\u8d1f\u503a\u4e0b\u591a\u5c11\u4eba\u88ab\u8feb\u5356\u623f\u3002\u5f53\u65f6\u6211\u4eec\u628a\u8d85\u4f4e\u5229\u7387\u9501\u4e86\u4e94\u5e74\uff0c\u800c\u540e\u6bcf\u6b21\u770b\u5230\u5229\u7387\u4e0a\u6da8\u6c11\u58f0\u6cb8\u817e\u7684\u65f6\u5019\uff0c\u603b\u611f\u89c9\u9003\u8fc7\u4e00\u52ab\u3002\u5f88\u96be\u8bf4\u5bb6\u5c5e\u62ff\u5230\u8d85\u4f4e\u5229\u7387\u7684\u201c\u5e78\u8fd0\u201d\u548c\u4ed6\u957f\u671f\u53bb\u94f6\u884c\u4eba\u5de5\u7f34\u8d39\u4e4b\u95f4\u662f\u5426\u5b58\u5728\u67d0\u79cd\u5076\u7136\u8fd8\u662f\u5fc5\u7136\u7684\u5173\u8054\u3002\u5f88\u53ef\u80fd\u5c31\u662f\u5076\u7136\uff0c\u5bb6\u5c5e\u8bf4\u4ed6\u81ea\u5df1\u53ea\u662f\u523b\u610f\u7ef4\u6301\u4e86\u591a\u5e74\u53bb\u94f6\u884c\u7f34\u8d39\u7684\u4e60\u60ef\uff0c\u4ed6\u8bf4\u5982\u679c\u8fde\u8fd9\u4e2a\u90fd\u6ca1\u6709\u4e86\u7684\u8bdd\uff0c\u5c31\u5f88\u5c11\u518d\u6709\u4e0e\u4ed6\u4eba\uff08\u975e\u5bb6\u4eba\u670b\u53cb\uff09\u6c9f\u901a\u7684\u673a\u4f1a\u4e0e\u5fc5\u8981\u3002\u5173\u7cfb\u662f\u8981\u523b\u610f\u7ef4\u62a4\u7684\uff0c\u6bd4\u601d\u8003\u4e0e\u8c01\u7ef4\u62a4\u66f4\u91cd\u8981\u7684\uff0c\u662f\u8fd9\u4efd\u4e3a\u4e86\u523b\u610f\u800c\u505a\u7684\u52aa\u529b\u3002\u5982\u679c\u662f\u5fc5\u7136\uff0c\u5c31\u66f4\u8bf4\u660e\u8fd9\u4e16\u4e0a\u4e0d\u5b58\u5728\u6d6a\u8d39\u65f6\u95f4\u548c\u65e0\u7528\u529f\u8fd9\u4e9b\u8bf4\u6cd5\u3002\\n\\n\u90a3\u529f\u540d\u5229\u7984\u7b97\u4ec0\u4e48\u5462\uff0c\u80fd\u505a\u65e0\u7528\u529f\u624d\u662f\u81ea\u7531\u7684\u4eba\u751f\u554a\uff0c\u4f46\u56fd\u5185\u8fd9\u6837\u7684\u73af\u5883\u53c8\u600e\u4f1a\u5141\u8bb8\u4e00\u4e2a\u4eba\u5b89\u5fc3\u5feb\u4e50\u5730\u505a\u65e0\u7528\u529f\uff1f\u7ed3\u679c\u662f\u53ea\u505a\u201c\u5927\u4e8b\u201d\u5374\u5fd8\u8bb0\u70b9\u6ef4\u7684\u4eba\u751f\u4f55\u5c1d\u4e0d\u662f\u65e0\u7528\u7684\u3002\\n\\n\u79bb\u5883\u4e0a\u6d77\u7684\u90a3\u4e00\u5929\u662f\u5723\u8bde\u8282\uff0c\u5728\u9996\u5c14\u7684\u4ec1\u5ddd\u673a\u573a\u8f6c\u673a\u65f6\uff0c\u770b\u89c1\u51e0\u4e2a\u5151\u5916\u6c47\u7684\u7a97\u53e3\uff0c\u60f3\u7740\u7ec8\u4e8e\u6446\u8131\u4e86\u624b\u673a\u652f\u4ed8\u7684\u6346\u7ed1\u3002\\n\\n\u5728\u673a\u573a\u7684\u9910\u996e\u533a\u53c8\u770b\u5230\u4e86\u90a3\u4e9b\u5929\u90fd\u672a\u89c1\u7684\u73b0\u8c61\uff1a\u6392\u961f\u7ed3\u8d26\u3002\u7b49\u5f85\u65f6\u56de\u60f3\u8fd9\u4e00\u8def\u626b\u7801\u652f\u4ed8\uff0c\u5374\u5feb\u7684\u6839\u672c\u4e0d\u8bb0\u5f97\u81ea\u5df1\u4e70\u4e86\u4e9b\u4ec0\u4e48\u6216\u82b1\u4e86\u591a\u5c11\u94b1\u3002\\n\\n\u4e5f\u8bb8\u8bb0\u5fc6\u7ec8\u7a76\u9700\u8981\u7269\u8d28\u505a\u5a92\u4ecb\uff0c\u5230\u5bb6\u540e\u94b1\u5305\u91cc\u8fd8\u5269\u4e0b\u672a\u7528\u5b8c\u7684\u97e9\u5143\uff0c\u6700\u540e\u4e00\u5929\u73b0\u91d1\u652f\u4ed8\uff0c\u6211\u8fd8\u8bb0\u5f97\u56db\u4e07\u97e9\u5143\uff0c\u4fe9\u4eba\u4e70\u4e86\u4e00\u4e2a\u8fa3\u725b\u8089\u9505\uff0c\u4e00\u4e2a\u9e21\u817f\u5821\uff0c\u4e00\u74f6\u7389\u7c73\u8336\u3002"},{"id":"\u6700\u597d\u4e0d\u8fc7\u91d1\u9f9f\u6362\u9152","metadata":{"permalink":"/kilimanjaro/\u6700\u597d\u4e0d\u8fc7\u91d1\u9f9f\u6362\u9152","editUrl":"https://github.com/jing-gu/kilimanjaro/blog/2020/2020-01-04-\u6700\u597d\u4e0d\u8fc7\u91d1\u9f9f\u6362\u9152.md","source":"@site/blog/2020/2020-01-04-\u6700\u597d\u4e0d\u8fc7\u91d1\u9f9f\u6362\u9152.md","title":"\u6700\u597d\u4e0d\u8fc7\u91d1\u9f9f\u6362\u9152","description":"\u4e00\u5e74\u8fc7\u8d77\u6765\u5feb\u7684\u60ca\u4eba\uff0c\u6700\u540e\u4e00\u89c1\u8fd8\u662f\u4e00\u5e74\u524d\u7684\u51b2\u7ef3\u673a\u573a\uff0c\u77ed\u88e4\u77ed\u8896\uff0c\u4e09\u5341\u5ea6\u7684\u6c14\u5019\u8bf4\u518d\u89c1\u3002\uff08\u7eed\u524d\u7bc7\u300a\u4e00\u57ce\u4e00\u5473\uff0c\u4e00\u671f\u4e00\u4f1a\u300b\uff09","date":"2020-01-04T00:00:00.000Z","tags":[{"inline":false,"label":"\u53cb\u8c0a","permalink":"/kilimanjaro/tags/\u53cb\u8c0a","description":"\u53cb\u8c0a tag description"},{"inline":false,"label":"\u65c5\u884c","permalink":"/kilimanjaro/tags/\u65c5\u884c","description":"\u65c5\u884c tag description"},{"inline":true,"label":"\u6e29\u54e5\u534e","permalink":"/kilimanjaro/tags/\u6e29\u54e5\u534e"}],"readingTime":15.9,"hasTruncateMarker":false,"authors":[],"frontMatter":{"slug":"\u6700\u597d\u4e0d\u8fc7\u91d1\u9f9f\u6362\u9152","title":"\u6700\u597d\u4e0d\u8fc7\u91d1\u9f9f\u6362\u9152","tags":["\u53cb\u8c0a","\u65c5\u884c","\u6e29\u54e5\u534e"],"date":"2020-01-04T00:00:00.000Z"},"unlisted":false,"prevItem":{"title":"\u70f9\u8336\u81ea\u6c72\u6c34\uff0c\u4f55\u4e8b\u4e0d\u6e05\u5e7d","permalink":"/kilimanjaro/\u70f9\u8336\u81ea\u6c72\u6c34\u4f55\u4e8b\u4e0d\u6e05\u5e7d"},"nextItem":{"title":"\u672a\u89c9\u6c60\u5858\u6625\u8349\u68a6\uff0c\u9636\u524d\u68a7\u53f6\u5df2\u79cb\u58f0","permalink":"/kilimanjaro/\u672a\u89c9\u6c60\u5858\u6625\u8349\u68a6\u9636\u524d\u68a7\u53f6\u5df2\u79cb\u58f0"}},"content":"\u4e00\u5e74\u8fc7\u8d77\u6765\u5feb\u7684\u60ca\u4eba\uff0c\u6700\u540e\u4e00\u89c1\u8fd8\u662f\u4e00\u5e74\u524d\u7684\u51b2\u7ef3\u673a\u573a\uff0c\u77ed\u88e4\u77ed\u8896\uff0c\u4e09\u5341\u5ea6\u7684\u6c14\u5019\u8bf4\u518d\u89c1\u3002\uff08\u7eed\u524d\u7bc7[\u300a\u4e00\u57ce\u4e00\u5473\uff0c\u4e00\u671f\u4e00\u4f1a\u300b](/\u4e00\u57ce\u4e00\u5473\u4e00\u671f\u4e00\u4f1a)\uff09\\n\\n\u6ca1\u60f3\u5230\u518d\u89c1\u53c8\u662f\u673a\u573a\uff0c\u6e29\u54e5\u534e\u7684\u822a\u7ad9\u697c\u4eff\u4f5b\u6709\u78c1\u529b\u4e00\u822c\uff0c\u6211\u4e00\u773c\u5c31\u80fd\u5728\u4eba\u7fa4\u4e2d\u627e\u5230\u6700\u60f3\u89c1\u7684\u4eba\u3002\\n\\n\u201c\u6211\u516d\u5c0f\u65f6\u524d\u5c31\u5230\u4e86\uff0c\u516d\u5c0f\u65f6\u53ef\u4ee5\u53c8\u98de\u4e00\u73ed\u4e86\uff01\u201d 12\u670825\u53f7\u4e0b\u5348\u56db\u70b9\u949f\uff0c\u5723\u8bde\u8282\u8fd9\u4e00\u5929\uff0c\u591a\u4e48\u719f\u6089\u7684\u62e5\u62b1\u548c\u62b1\u6028\u540c\u65f6\u5411\u6211\u88ad\u6765\u3002\\n\\n\u201c\u522b\u62b1\uff0c\u522b\u6324\uff0c\u6211\u8981\u5c3f\u5c3f\u3002\u201d \u4e00\u4e0b\u98de\u673a\u6211\u5c31\u5954\u51fa\u6765\u4e86\uff0c\u5feb\u5f97\u8fde\u5395\u6240\u90fd\u6ca1\u7a7a\u8fdb\u53bb\u3002\\n\\n![Vancouver](./img/jinguihuanjiu1.jpg)\\n\\n\u4e00\u5e74\u4e00\u89c1\u5e76\u4e0d\u5bb9\u6613\uff0c\u82b1\u94b1\u82b1\u529b\u82b1\u65f6\u95f4\u3002\u673a\u7968\u4f4f\u5bbf\u514d\u4e0d\u4e86\uff0c\u5403\u559d\u53c8\u4e0d\u80fd\u542b\u7cca\uff0c\u518d\u52a0\u4e0a\u5404\u79cd\u4e0d\u53ef\u9884\u6d4b\u7684\u6742\u4e03\u6742\u516b\uff0c\u8fd9\u9884\u7b97\u4ece\u534a\u5e74\u524d\u5c31\u88ab\u8ba1\u5212\u51fa\u6765\u4e86\uff0c\u6bcf\u6708\u7701\u70b9\u7c73\u9762\u6cb9\u83dc\u7684\u5b50\u513f\uff08\u5f00\u73a9\u7b11\uff0c\u4e0d\u81f3\u4e8e\u8fd9\u4e48\u62a0\uff09\u3002\u4f46\u7406\u667a\u6d88\u8d39\u3001\u8282\u7701\u5f00\u9500\u662f\u80af\u5b9a\u7684\uff0c\u7adf\u6709\u79cd\u590f\u5929\u5c6f\u7cae\u51ac\u5929\u597d\u8fc7\u51ac\u7684\u611f\u89c9\uff0c\u60f3\u5962\u4f88\u4e00\u628a\u7684\u65f6\u5019\u4e5f\u4e0d\u81f3\u4e8e\u6349\u895f\u89c1\u8098\u3002\\n\\n\u4e00\u5e74\u4e00\u89c1\u503c\u5f97\u671f\u5f85\uff0c\u6211\u73b0\u5728\u624d\u660e\u767d\u300a\u5c0f\u738b\u5b50\u300b\u91cc\u72d0\u72f8\u8bf4\uff1a\u201c\u5982\u679c\u4f60\u8bf4\u4f60\u5728\u4e0b\u5348\u56db\u70b9\u6765\uff0c\u4ece\u4e09\u70b9\u949f\u5f00\u59cb\uff0c\u6211\u5c31\u5f00\u59cb\u611f\u89c9\u5f88\u5feb\u4e50\uff0c\u65f6\u95f4\u8d8a\u4e34\u8fd1\uff0c\u6211\u5c31\u8d8a\u6765\u8d8a\u611f\u5230\u5feb\u4e50\u3002\u5230\u4e86\u56db\u70b9\u949f\u7684\u65f6\u5019\uff0c\u6211\u5c31\u4f1a\u5750\u7acb\u4e0d\u5b89\uff0c\u6211\u53d1\u73b0\u4e86\u5e78\u798f\u7684\u4ef7\u503c\uff0c\u4f46\u662f\u5982\u679c\u4f60\u968f\u4fbf\u4ec0\u4e48\u65f6\u5019\u6765\uff0c\u6211\u5c31\u4e0d\u77e5\u9053\u5728\u4ec0\u4e48\u65f6\u5019\u51c6\u5907\u597d\u8fce\u63a5\u4f60\u7684\u5fc3\u60c5\u4e86\u3002\u201d\\n\\n![Vancouver](./img/jinguihuanjiu2.jpg)\\n\\n\u4e8e\u662f\u4e24\u5f20\u4ece\u4e1c\u4eac\u548c\u8499\u7279\u5229\u5c14\u98de\u5f80\u6e29\u54e5\u534e\u7684\u673a\u7968\u65e9\u5c31\u8ba2\u597d\u4e86\uff0c\u6536\u5230\u63d0\u793a\u822a\u73ed\u4e34\u8fd1\u7684\u7535\u5b50\u90ae\u4ef6\u90fd\u7ed9\u6211\u5e26\u6765\u4e00\u9635\u559c\u60a6\u3002\\n\\n## \u6700\u597d\u6885\u9152\u914d\u9c7c\u751f\\n\\n\u201c\u7b2c\u4e00\u987f\u5403\u4ec0\u4e48\uff1f\u201d \u5173\u4e4e\u4e8e\u5403\uff0c\u6211\u5411\u6765\u4e25\u8c28\u3002\u6e29\u54e5\u534e\u4f5c\u4e3a\u79fb\u6c11\u5927\u57ce\u62e5\u6709\u5404\u56fd\u6b63\u5b97\u800c\u7f8e\u5473\u7684\u98df\u7269\uff0c\u9009\u62e9\u4e0d\u662f\u96be\u4e8b\u3002\\n\\n\u201c\u53bb\u5403\u5bff\u53f8\u548c\u9c7c\u751f\u5427\u3002\u201d\\n\\n\u201c\u4f60\u4e0d\u538c\u561b\uff1f\u201d \u5bf9\u4e00\u4e2a\u521a\u4ece\u4e1c\u4eac\u98de\u6765\u8fd8\u4e0d\u523012\u5c0f\u65f6\u7684\u4eba\uff0c\u6211\u4ea7\u751f\u8d28\u7591\u3002\\n\\n\u201c\u6e29\u54e5\u534e\u7684\u4e09\u6587\u9c7c\u523a\u8eab\u662f\u592a\u5e73\u6d0b\u7684\u91ce\u751f\u9c91\u9c7c\uff0c\u542c\u8bf4\u6bd4\u65e5\u672c\u5883\u5185\u7684\u597d\u5403\u3002\u201d\\n\\n\u4e8e\u662f\u6211\u4eec\u627e\u4e86\u4e00\u5bb6\u65e5\u5f0f\u9910\u5385\uff0c\u5728\u5723\u8bde\u8282\u8fd8\u8425\u4e1a\u7684\u4e0d\u591a\uff0c\u6240\u4ee5\u8fd9\u5bb6\u663e\u5f97\u975e\u5e38\u70ed\u95f9\u3002\\n\\n![Vancouver Sushi](./img/jinguihuanjiu3.jpg)\\n\\n\u9c7c\u751f\u4e00\u4e0a\u684c\u7684\u90a3\u4e00\u523b\u6211\u5c31\u77e5\u9053\u8fd9\u8d9f\u6765\u5bf9\u4e86\uff0c\u8fd9\u4e48\u7ea2\u7684\u4e09\u6587\u9c7c\u8fd8\u662f\u7b2c\u4e00\u6b21\u89c1\u3002\u65e5\u672c\u5883\u5185\u7684\u9ad8\u6863\u523a\u8eab\u5927\u591a\u90fd\u662f\u4ece\u91d1\u67aa\u9c7c\u8eab\u4e0a\u5207\u51fa\u6765\u7684\uff0c\u56e0\u4e3a\u4eba\u4eec\u5bf9\u84dd\u9ccd\u91d1\u67aa\u9c7c\u7684\u8ffd\u6367\u8fdc\u8d85\u5176\u5b83\u9c7c\u7c7b\u3002\u5982\u6b64\u539a\u5207\u7684\u91ce\u751f\u4e09\u6587\u9c7c\u4e5f\u5c31\u6210\u4e86\u96be\u5f97\u4e00\u5c1d\u7684\u7f8e\u5473\u3002\\n\\n\u9c7c\u751f\u914d\u7eff\u8336\u662f\u5bff\u53f8\u5e97\u901a\u4fd7\u7684\u505a\u6cd5\uff0c\u6ca1\u6bdb\u75c5\u5374\u4e0d\u5c3d\u5174\uff0c\u800c\u4e14\u6211\u603b\u5e7b\u89c9\u5403\u4e0b\u53bb\u7684\u751f\u9c7c\u7247\u5728\u809a\u5b50\u91cc\u88ab\u70ed\u996e\u70eb\u719f\u7684\u573a\u666f\uff0c\u767d\u82b1\u4e86\u8fd9\u4ef7\u94b1\u3002\\n\\n\u9c7c\u751f\u914d\u6e05\u9152\u662f\u884c\u5185\u4eba\u7684\u505a\u6cd5\uff0c\u89e3\u817b\u3001\u6740\u83cc\u3001\u5f00\u80c3\uff0c\u4e00\u77f3\u4e09\u9e1f\u3002\u4f46\u95ee\u9898\u662f\u8d8a\u5403\u8d8a\u591a\uff0c\u6709\u4eba\u66fe\u544a\u8bc9\u6211\u6280\u5de7\u5982\u4f55\u5728\u81ea\u52a9\u9910\u5385\u5403\u6389\u6700\u591a\u7684\u751f\u9c7c\u7247\uff1f\u53ea\u8981\u559d\u70b9\u6e05\u9152\uff0c\u53ef\u4ee5\u518d\u5e72\u6389\u4e00\u5927\u76d8\u9c7c\u3002\u53ef\u60dc\u6e05\u9152\u4e0d\u662f\u6211\u6700\u559c\u6b22\u7684\uff0c\u6211\u7231\u6885\u9152\uff0c\u4e24\u76ce\u53f8\u6885\u9152\u4e09\u9897\u51b0\u5757\uff0c\u914d\u9c91\u9c7c\u523a\u8eab\u51e0\u7247\uff0c\u624b\u63e1\u5bff\u53f8\u51e0\u53ea\uff0c\u4e0d\u8d2a\u676f\u4e5f\u4e0d\u591a\u5403\uff0c\u6700\u597d\u4e0d\u8fc7\u6885\u9152\u914d\u9c7c\u751f\u3002\\n\\n## \u6700\u597d\u5c71\u4e2d\u6ce1\u6e29\u6cc9\\n\\n\u8ddd\u79bb\u6e29\u54e5\u534e\u4e24\u5c0f\u65f6\u4e0d\u5230\u7684\u8f66\u7a0b\u4e4b\u5916\u6709\u4e00\u4e2a\u53eb Whistler \u7684\u6ed1\u96ea\u5c0f\u9547\uff0c\u4f4d\u4e8e\u7fa4\u5c71\u4e4b\u95f4\uff0c\u9664\u53bb\u6e38\u5ba2\u4e4b\u5916\u5927\u6982\u53ea\u6709\u4e24\u767e\u591a\u4e2a\u771f\u6b63\u7684\u5c45\u6c11\u3002\u5c71\u91cc\u6709\u4e00\u5904\u53eb Scandinave Spa \u7684\u6e29\u6cc9\uff0c\u63d0\u4f9b\u5317\u6b27\u7597\u6cd5\u7684\u6e29\u6cc9\u4f53\u9a8c\u3002\\n\\n\u7b2c\u4e00\u6b65\u5148\u5728\u70ed\u6c34\u6c60\u6ce115\u5206\u949f\uff1b\u7b2c\u4e8c\u6b65\u8df3\u8fdb\u51b7\u6c34\u6c605\u81f310\u79d2\uff0c\u6211\u8fde\u4e24\u79d2\u90fd\u6ca1\u575a\u6301\u7684\u4f4f\uff0c\u8fdb\u53bb\u534a\u8eab\u5c31\u8dd1\u51fa\u6765\u4e86\uff1b\u7b2c\u4e09\u6b65\u8fdb\u6851\u62ff\u84b8\u5230\u6d51\u8eab\u51fa\u6c57\uff1b\u7b2c\u56db\u6b65\u88f9\u597d\u6d74\u888d\u4e0a\u8eba\u6905\u4f11\u606f\u3002\u4e5f\u8bb8\u662f\u592a\u8212\u670d\u7684\u539f\u56e0\uff0c\u6211\u521a\u95ed\u773c\u51e0\u5206\u949f\uff0c\u8eab\u8fb9\u5c31\u9f3e\u58f0\u56db\u8d77\uff0c\u6709\u4e9b\u8001\u540c\u5fd7\u5c45\u7136\u5c31\u90a3\u4e48\u7761\u8fc7\u53bb\u4e86\uff0c\u58f0\u97f3\u4e0d\u5927\uff0c\u5374\u6b64\u8d77\u5f7c\u4f0f\uff0c\u770b\u6765\u4e0d\u6b62\u4e00\u4eba\u5728\u5927\u767d\u5929\u7761\u5f97\u9999\u751c\u3002\\n\\n![Scandinave Spa](./img/jinguihuanjiu4.jpg)\\n\\n\u8fde\u9f3e\u58f0\u4e5f\u5982\u6b64\u6e05\u6670\u662f\u6709\u539f\u56e0\u7684\uff0c\u56e0\u4e3a\u6574\u4e2a\u6e29\u6cc9\u573a\u5185\u4e0d\u8ba9\u8bb2\u8bdd\u3002\u624b\u673a\u7981\u6b62\uff0c\u8bf4\u8bdd\u7981\u6b62\uff0c\u8fd9\u4e48\u591a\u4eba\u968f\u610f\u8d70\u52a8\u5374\u542c\u4e0d\u89c1\u4efb\u4f55\u5608\u6742\u3002\u773c\u95ed\u7740\uff0c\u5634\u4e5f\u95ed\u7740\uff0c\u624d\u53d1\u73b0\u5fc3\u80fd\u79bb\u5927\u81ea\u7136\u8fd9\u4e48\u8fd1\uff0c\u6211\u542c\u89c1\u9e1f\u9e23\uff0c\u542c\u89c1\u98ce\u58f0\uff0c\u542c\u89c1\u6cc9\u6c34\uff0c\u731b\u7136\u95f4\u610f\u8bc6\u5230\u5b89\u9759\u7684\u4e0d\u50cf\u8bdd\uff0c\u7d20\u8d28\u9ad8\u4e5f\u4e0d\u662f\u8fd9\u4e48\u56de\u4e8b\u554a\u3002\\n\\n\u518d\u4e00\u60f3\u6211\u660e\u767d\u4e86\uff0c\u6ca1\u6709\u513f\u7ae5\uff0c\u4e00\u4e2a\u90fd\u6ca1\u770b\u89c1\uff0c\u539f\u676519\u5c81\u4ee5\u4e0b\u7981\u6b62\u8fdb\u5165\u3002\u8fd9\u624d\u50cf\u8bdd\uff0c\u6ca1\u6709\u5c0f\u5b69\u56db\u5904\u73a9\u6c34\u7684\u6e29\u6cc9\u7b80\u76f4\u8212\u670d\u5230\u4e0a\u5929\uff0c\u4e00\u6c60\u7684\u6210\u5e74\u4eba\u5171\u540c\u575a\u5b88\u7740\u4e0d\u8a00\u4e0d\u8bed\u7684\u6e38\u620f\u89c4\u5219\uff0c\u56db\u76ee\u76f8\u5bf9\uff0c\u61d2\u5f97\u8bb2\u8bdd\uff0c\u8fde\u6211\u90fd\u5feb\u8eba\u7761\u7740\u4e86\u3002\u6700\u597d\u4e0d\u8fc7\u5c71\u4e2d\u6ce1\u6e29\u6cc9\u3002\\n\\n![Scandinave Spa](./img/jinguihuanjiu5.jpg)\\n\\n\u5c06\u4ee5\u4e0a\u6b65\u9aa4\u5faa\u73af\u4e09\u5230\u56db\u6b21\u5c31\u8fbe\u5230\u7597\u6548\u4e86\u3002\u6211\u6ca1\u60f3\u5230\u7597\u6548\u60ca\u4eba\uff0c\u628a\u5927\u59e8\u5988\u90fd\u6ce1\u63d0\u524d\u4e86\uff0c\u6709\u798f\u540c\u4eab\u4e5f\u7f62\u6709\u96be\u540c\u5f53\u4e5f\u597d\uff0c\u73b0\u5728\u8fde\u751f\u7406\u671f\u90fd\u88ab\u649e\u5230\u4e86\u540c\u4e00\u5468\uff0c\u4eba\u751f\u65e0\u5904\u4e0d\u51d1\u5de7\u3002\\n\\n## \u6700\u597d\u8def\u4e0a\u8c08\u7535\u5f71\\n\\n\u4ece\u6e29\u54e5\u534e\u53bb\u7ef4\u591a\u5229\u4e9a\u9700\u8981\u5750\u8f6e\u6e21\uff0c\u6574\u6bb5\u884c\u7a0b\u5927\u6982\u8981\u56db\u5c0f\u65f6\uff0c\u5148\u5728\u6e29\u54e5\u534e\u5e02\u5185\u5750\u8f7b\u8f68\u8f6c\u516c\u4ea4\u62b5\u8fbe\u6e2f\u53e3\u4e00\u5c0f\u65f6\uff0c\u5750\u8239\u4e00\u4e2a\u534a\u5c0f\u65f6\uff0c\u62b5\u8fbe\u7ef4\u591a\u5229\u4e9a\u6e2f\u53e3\u540e\u518d\u5750\u8f66\u8fdb\u5e02\u5185\u4e00\u5c0f\u65f6\u3002\u642d\u8f66\u5750\u8239\u672c\u8eab\u662f\u4ef6\u633a\u65e0\u804a\u7684\u4e8b\uff0c\u4f46\u603b\u6709\u4e9b\u8bdd\u9898\u80fd\u6070\u5982\u5176\u5206\u5730\u5728\u8def\u4e0a\u88ab\u201c\u98a0\u7c38\u201d\u51fa\u6765\uff0c\u7535\u5f71\u7b97\u662f\u6211\u4eec\u7684\u4e00\u4e2a\u5171\u540c\u7231\u597d\uff0c\u800c\u4e92\u6362\u5f71\u5355\u6210\u4e86\u6211\u4eec\u7684\u4e60\u60ef\u3002\\n\\n\u4e00\u5e74\u4e0b\u6765\u6211\u4eec\u90fd\u5404\u81ea\u770b\u4e86\u5927\u51e0\u5341\u90e8\u7535\u5f71\uff0c\u65e2\u5173\u6ce8\u65b0\u7247\uff0c\u4e5f\u91cd\u770b\u7ecf\u5178\uff0c\u4e00\u95ee\u4e00\u7b54\u540e\u53d1\u73b0\u51e0\u4e4e\u4e00\u534a\u5185\u5bb9\u90fd\u662f\u76f8\u540c\u7684\u3002\u5176\u5b9e\u8fd9\u79cd\u5c0f\u4e8b\u6211\u4eec\u5e76\u6ca1\u6709\u4e8b\u5148\u6c9f\u901a\u8fc7\uff0c\u53ea\u662f\u65f6\u95f4\u8d8a\u4e45\uff0c\u5374\u53d1\u73b0\u8fde\u6311\u5f71\u7247\u7684\u773c\u5149\u90fd\u5f00\u59cb\u7c7b\u4f3c\u3002\\n\\n![Victoria](./img/jinguihuanjiu6.jpg)\\n\\n\u6211\u4f9d\u65e7\u8bb0\u5f97\u5b66\u751f\u65f6\u4ee3\u7684\u6211\u4eec\u4e00\u8d77\u770b\u7684\u7b2c\u4e00\u90e8\u7535\u5f71\u662f\u610f\u5927\u5229\u7684\u300aBest Offer\u300b\uff0c\u90a3\u662f\u67d0\u5929\u665a\u996d\u540e\uff0c\u5979\u6367\u4e2a\u7b14\u8bb0\u672c\u7535\u8111\u5230\u6211\u623f\u95f4\uff1a\u201c\u6211\u6709\u90e8\u597d\u7535\u5f71\uff0c\u770b\u4e0d\u770b\uff1f\u201d\\n\\n\u201c\u8fdb\u6765\u5427\u3002\u201d \u6211\u6ca1\u95ee\u662f\u4ec0\u4e48\u7535\u5f71\uff0c\u4e5f\u987e\u4e0d\u4e0a\u5199\u4f5c\u4e1a\u548c\u67e5\u90ae\u4ef6\uff0c\u6211\u4eec\u5c31\u4e00\u8d77\u5750\u5728\u5730\u6bef\u4e0a\u628a\u7535\u5f71\u4e00\u53e3\u6c14\u770b\u5b8c\u4e86\u3002\u90a3\u662f\u4e00\u90e8\u5173\u4e8e\u827a\u672f\u54c1\u62cd\u5356\u5bb6\u548c\u5973\u9a97\u5b50\u7684\u6545\u4e8b\uff0c\u770b\u4e00\u904d\u60ca\u53f9\uff0c\u770b\u4e24\u904d\u6df1\u601d\uff0c\u53cd\u590d\u770b\u53cd\u590d\u60f3\uff0c\u90a3\u4f9d\u7136\u662f\u6211\u6700\u559c\u6b22\u7684\u7535\u5f71\u4e4b\u4e00\u3002\\n\\n\u201c\u8fd9\u4e00\u90e8\u5462\uff1f\u300a\u548c\u838e\u83ab\u7684500\u5929\u300b\uff0c\u867d\u7136\u65f6\u95f4\u633a\u4e45\u4e86\u2026\u201d \u6211\u9010\u6761\u6d4f\u89c8\u81ea\u5df1\u7684\u8bb0\u5f55\uff0c\u7136\u540e\u968f\u610f\u6293\u4e86\u4e00\u4e2a\u7247\u540d\u8bd5\u63a2\u3002\\n\\n\u201c\u770b\u4e86\u5927\u6982\u90fd\u6709\u4e94\u904d\u4e86\uff0c\u611f\u89c9\u6211\u81ea\u5df1\u5c31\u50cf\u5176\u4e2d\u7684\u838e\u83ab\u3002\u201d\\n\\n\u6211\u4e0b\u610f\u8bc6\u5730\u5236\u6b62\u4e86\u8fd8\u5728\u6eda\u9891\u7684\u624b\u6307\uff0c\u8111\u6d77\u91cc\u5f00\u59cb\u8fc5\u901f\u56de\u5fc6\u6574\u90e8\u7535\u5f71\u3002\u90a3\u771f\u7684\u662f\u4e2a\u6d6a\u6f2b\u800c\u53c8\u73b0\u5b9e\u7684\u6545\u4e8b\uff0c\u6211\u559c\u6b22\u5b83\uff0c\u5c31\u56e0\u4e3a\u5b83\u4e0d\u662f\u80a4\u6d45\u7684\u5927\u56e2\u5706\uff0c\u5c31\u56e0\u4e3a\u5b83\u8bb2\u4e86\u4e2a\u771f\u5b9e\u7684\u9053\u7406\uff1a\u522b\u6210\u5929\u505a\u767d\u65e5\u68a6\uff0c\u751f\u6d3b\u603b\u662f\u7ecf\u5386\u5931\u53bb\u540e\u88ab\u8feb\u6210\u957f\uff0c\u518d\u7edd\u5730\u53cd\u51fb\uff0c\u5982\u679c\u4f60\u8fd8\u6709\u672c\u4e8b\u7ad9\u8d77\u6765\u7684\u8bdd\u3002\\n\\n![Victoria](./img/jinguihuanjiu7.jpg)\\n\\n\u201c\u597d\u50cf\u8fd8\u771f\u662f\uff0c\u633a\u50cf\u4f60\u3002\u201d \u6211\u5df2\u4e0d\u7528\u8fc7\u591a\u5206\u6790\uff0c\u6d4f\u89c8\u4e00\u4e2a\u4eba\u7684\u5f71\u5355\u8db3\u8ff9\u53ef\u4ee5\u770b\u51fa\u5f88\u591a\u65e0\u6cd5\u63a9\u76d6\u7684\u4e8b\u5b9e\uff0c\u6bd4\u5982\u6027\u683c\uff0c\u54c1\u5473\uff0c\u601d\u60f3\uff0c\u751a\u81f3\u5fc3\u7406\u3002\u4e5f\u8bb8\u672a\u5fc5\u4eba\u4eba\u90fd\u559c\u6b22\u838e\u83ab\u90a3\u6837\u7684\u5973\u5b69\uff0c\u4f46\u6211\u73cd\u60dc\uff0c\u5c31\u56e0\u4e3a\u4e0d\u5b8c\u7f8e\u5e26\u6765\u7684\u771f\u5b9e\u548c\u53ef\u7231\u662f\u90a3\u4e48\u7684\u89e6\u624b\u53ef\u53ca\u3002\u751f\u6d3b\u4e2d\u5176\u5b9e\u6bcf\u4e2a\u4eba\u8eab\u8fb9\u90fd\u6709\u8fd9\u6837\u7684\u4eba\u7269\u5b58\u5728\uff0c\u7f8e\u4e2d\u4e0d\u8db3\uff0c\u9ed8\u5951\u6709\u4f59\uff0c\u5728\u76f8\u4e92\u7275\u7eca\u4e2d\u5f7c\u6b64\u6210\u957f\u3002\u8fd9\u4eba\u6709\u591a\u597d\uff1f\u7f3a\u70b9\u4e00\u5927\u5806\uff0c\u4f46\u771f\u5b9e\u53ef\u9760\uff0c\u6709\u65f6\u5982\u955c\u5b50\u822c\u53cd\u5c04\u6211\u81ea\u8eab\u7684\u4e0d\u8db3\u3002\\n\\n\u4e00\u8def\u98a0\u7c38\uff0c\u63a5\u4e0b\u6765\u4e00\u5e74\u8be5\u770b\u7684\u7535\u5f71\u4e5f\u5217\u597d\u6e05\u5355\u4e86\uff0c\u5c31\u662f\u90a3\u4e9b\u4f60\u770b\u4e86\u6211\u6ca1\u770b\u7684\uff0c\u548c\u6211\u770b\u4e86\u4f60\u6ca1\u770b\u7684\u3002\u6700\u597d\u4e0d\u8fc7\u8def\u4e0a\u8c08\u7535\u5f71\u3002\\n\\n## \u6700\u597d\u6392\u961f\u5403\u65e9\u9910\\n\\n\u6bd4\u6e29\u54e5\u534e\u66f4\u4ee4\u6211\u5411\u5f80\u7684\u662f\u7ef4\u591a\u5229\u4e9a\uff0c\u6574\u5ea7\u57ce\u5e02\u5145\u6ee1\u82f1\u56fd\u5973\u738b\u65f6\u4ee3\u7684\u9057\u98ce\u3002\u96c4\u4f1f\u9ad8\u5927\u7684\u5efa\u7b51\u5982\u57ce\u5821\u5982\u5bab\u5ef7\uff0c\u4ee4\u4eba\u8d5e\u53f9\uff0c\u65e0\u540d\u65e0\u59d3\u7684\u4f4f\u5b85\u66f4\u662f\u7cbe\u81f4\u5230\u4ee4\u6211\u5fc3\u52a8\uff0c\u5c31\u50cf\u5f7c\u5f97\u5154\u7684\u5bb6\u4e00\u6837\u53ef\u7231\u3002\\n\\n![Victoria](./img/jinguihuanjiu8.jpg)\\n\\n\u7ef4\u591a\u5229\u4e9a\u8fd9\u5ea7\u57ce\u5728\u98df\u7269\u65b9\u9762\u8ba4\u771f\u5730\u6cbf\u88ad\u4e86\u82f1\u4f26\u7684\u5403\u76f8\uff0c\u6bd4\u5982\u9c7c\u548c\u70b8\u85af\u6761\u7684\u65e0\u654c\u7ec4\u5408\uff0c\u518d\u8005\u5c31\u662f\u677e\u997c\u3001\u534e\u592b\u7b49\u751c\u98df\u3002\\n\\n\u65e9\u9910\u8be5\u5403\u751c\u8fd8\u662f\u54b8\uff1f\u8fd9\u4e00\u76f4\u662f\u4e2a\u65e0\u6cd5\u7edf\u4e00\u7684\u7b54\u6848\uff0c\u6700\u597d\u4e00\u4eba\u4e00\u9053\u751c\u4e00\u9053\u54b8\uff0c\u5404\u5403\u4e00\u534a\u6362\u76d8\u5b50\uff0c\u8fd9\u5403\u76f8\u4e11\u7684\u554a\uff0c\u4f46\u5403\u7684\u6ee1\u610f\u5012\u662f\u5b9e\u8bdd\u3002\\n\\n\u7ed3\u679c\u6211\u4eec\u70b9\u4e86\u4e24\u9053\u751c\uff0c\u4e00\u9053\u677e\u997c\u914d\u6811\u8393\u67e0\u6aac\u9171\uff0c\u4e00\u9053\u539a\u5410\u53f8\u914d\u8349\u8393\u9999\u8549\u67ab\u7cd6\u6d46\u3002\u5b9e\u5728\u662f\u88ab\u5f53\u5730\u7279\u8272\u5438\u5f15\uff0c\u4e24\u5929\u65e9\u9910\u90fd\u662f\u751c\uff0c\u4e24\u5929\u65e9\u9910\u90fd\u6392\u961f\uff0c\u4e00\u5929\u53bb\u7684\u65e9\uff0c\u4e00\u5929\u6545\u610f\u53bb\u7684\u665a\uff0c\u8fd8\u662f\u6ca1\u8eb2\u8fc7\u6392\u961f\u7684\u4eba\u6f6e\u3002\u770b\u6765\u7231\u5403\u751c\u7684\u4eba\u771f\u7684\u5f88\u591a\uff0c\u4e5f\u8bb8\u751c\u677e\u997c\u771f\u7684\u5f88\u597d\u5403\u3002\\n\\n\u95e8\u5916\u4e00\u7fa4\u4eba\u6392\u51fa\u4e00\u6761\u957f\u9f99\uff0c\u4f30\u8ba1\u8981\u7b49\u534a\u5c0f\u65f6\u3002\u8fd8\u597d\u7ef4\u591a\u5229\u4e9a\u7684\u51ac\u5929\u4e0d\u7b97\u51b7\uff0c\u80fd\u591f\u5f97\u4e0a\u6392\u961f\u5403\u996d\u7684\u5730\u65b9\u90fd\u662f\u7ecf\u5f97\u8d77\u7fa4\u4f17\u8003\u9a8c\u7684\uff0c\u6211\u7422\u78e8\u7740\uff0c\u4e00\u56de\u5934\u624d\u53d1\u73b0\u8eab\u540e\u5df2\u7ecf\u53c8\u805a\u62e2\u4e86\u51e0\u7c07\u4eba\uff0c\u6211\u7acb\u523b\u9760\u62e2\uff0c\u8d34\u7d27\u5927\u90e8\u961f\u3002\\n\\n\u201c\u770b\uff0c\u8fd9\u4e0a\u4e86\u4e2a\u6bd4\u4f60\u8138\u8fd8\u5927\u7684\u677e\u997c\u3002\u201d \u662f\u7684\uff0c\u6211\u7684\u7b49\u5f85\u6700\u7ec8\u6362\u6765\u4e86\u5356\u76f8\u597d\u3001\u5473\u9053\u597d\uff0c\u4e14\u5b9e\u60e0\u88c5\u7684\u8d85\u5927\u76f4\u5f84\u677e\u997c\u3002\\n\\n![Victoria](./img/jinguihuanjiu9.jpg)\\n\\n\u5176\u5b9e\u8c01\u559c\u6b22\u6392\u961f\u8c01\u559c\u6b22\u7b49\u5462\uff1f\u8fde\u6392\u961f\u4e0a\u4e2a\u5395\u6240\u90fd\u5fc3\u91cc\u4e0d\u723d\u3002\u6bcf\u5929\u6068\u4e0d\u5f97\u4e00\u6b65\u767b\u5929\uff0c\u65e5\u5b50\u8fc7\u8d77\u6765\u4e0d\u7728\u773c\uff0c\u7ed3\u679c\u4ec0\u4e48\u4e5f\u6ca1\u7559\u4e0b\u4ec0\u4e48\u4e5f\u6ca1\u8bb0\u4f4f\uff0c\u81ea\u95ee\u6628\u5929\u5348\u996d\u5403\u4e86\u4ec0\u4e48\uff1f\u672a\u5fc5\u8bf4\u5f97\u51fa\u3002\\n\\n\u867d\u4e0d\u60c5\u613f\uff0c\u53ef\u6211\u5f97\u627f\u8ba4\uff0c\u4f46\u51e1\u7ecf\u5386\u7b49\u5f85\u7684\u4e8b\u60c5\u90fd\u96be\u4ee5\u5fd8\u6000\u3002\u6211\u8bb0\u5f97\u6392\u5728\u6211\u4eec\u524d\u9762\u7684\u662f\u56db\u4eba\u7ec4\uff0c\u7ed3\u679c\u5c0f\u684c\u5148\u7a7a\u51fa\u6765\u4e86\uff0c\u53ea\u6709\u4e24\u4eba\u7684\u6211\u4eec\u5341\u5206\u8363\u5e78\u5730\u5148\u8fdb\u53bb\u4e86\u3002\\n\\n\u6211\u8bb0\u5f97\u5927\u677e\u997c\u5806\u8d77\u6765\u6709\u4e09\u5f20\uff0c\u539a\u5410\u53f8\u6709\u56db\u5757\u3002\u6211\u8bb0\u5f97\u88c5\u9970\u662f\u4e00\u9897\u9ec4\u8272\u7684\u9178\u6d46\u679c\uff0c\u53f6\u5b50\u8fd8\u5728\u3002\\n\\n\u6211\u8bb0\u5f97\u679c\u6c41\u4e24\u676f\uff0c\u4e00\u676f\u662f\u6a59\u6c41\uff0c\u4e00\u676f\u897f\u67da\u6c41\u3002\u6211\u53c8\u8981\u4e86\u4e00\u58f6\u9ed1\u5496\u5561\uff0c\u5728\u4e00\u5806\u751c\u5473\u7684\u886c\u6258\u4e0b\uff0c\u5496\u5561\u5c45\u7136\u65e0\u6bd4\u597d\u559d\u3002\u5496\u5561\u4e00\u58f6\u4e09\u5757\u4e94\u52a0\u5e01\uff0c\u65e0\u9650\u7eed\u3002\\n\\n\u6211\u8bb0\u5f97\u6211\u5b9e\u5728\u5403\u4e0d\u4e0b\u4e86\uff0c\u53bb\u4e86\u8d9f\u5395\u6240\uff0c\u56de\u5934\u53c8\u591a\u5403\u4e86\u4e24\u53e3\u51cf\u5c11\u6d6a\u8d39\u3002\\n\\n\u6211\u751a\u81f3\u8bb0\u5f97\u6211\u5de6\u8fb9\u4e00\u684c\u5750\u7740\u56db\u4e2a\u7537\u4eba\uff0c\u70b9\u4e86\u4e09\u79cd\u677e\u997c\u548c\u4e00\u4e2a\u770b\u4e0d\u6e05\u91cc\u9762\u88c5\u4e86\u4ec0\u4e48\u7684\u5927\u7897\u3002\u6211\u8bb0\u5f97\u53f3\u8fb9\u4e00\u684c\u5750\u7740\u4e24\u7537\u4e24\u5973\uff0c\u6765\u7684\u65e9\u8d70\u5f97\u5feb\uff0c\u540e\u6765\u62c6\u6210\u4e24\u5c0f\u684c\uff0c\u65b0\u6765\u7684\u5ba2\u4eba\u4e00\u80d6\u4e00\u7626\uff0c\u7ec8\u4e8e\u70b9\u4e86\u54b8\u5473\u7684\u4e1c\u897f\uff0c\u4e8e\u662f\u6211\u770b\u5230\u4e86\u9e21\u86cb\u5377\u548c\u9999\u80a0\u3002\\n\\n\u6211\u8bb0\u5f97\u5403\u751c\u7684\u684c\u4e0a\u662f\u67ab\u7cd6\u6d46\u4e00\u74f6\uff0c\u5403\u54b8\u7684\u5ba2\u4eba\u5c31\u6362\u6210\u8fa3\u9171\u4e00\u74f6\u3002\\n\\n![Victoria](./img/jinguihuanjiu10.jpg)\\n\\n\u6211\u8d8a\u56de\u5fc6\u8d8a\u6e05\u6670\uff0c\u7ec6\u8282\u5982\u4fa6\u63a2\u7834\u6848\u7684\u86db\u4e1d\u9a6c\u8ff9\u4e00\u822c\u6d6e\u51fa\u6c34\u9762\u3002\u6211\u5e76\u975e\u5728\u610f\u65c1\u684c\u5403\u4e86\u4ec0\u4e48\uff0c\u4f46\u7b49\u5f85\u672c\u8eab\u4eff\u4f5b\u80fd\u8ba9\u65f6\u95f4\u7684\u6d41\u52a8\u66f4\u52a0\u7f13\u6162\uff0c\u9664\u4e86\u5403\uff0c\u597d\u50cf\u8fd8\u6709\u66f4\u591a\u7684\u4e1c\u897f\u8fdb\u5165\u4e86\u8eab\u4f53\u3002\\n\\n\u6211\u8bb0\u5f97\uff0c\u6211\u600e\u4e48\u4f1a\u5fd8\u8bb0\uff0c\u90a3\u5bb6\u597d\u5403\u7684\u5e97\u53eb Jam Cafe\u3002\u6700\u597d\u4e0d\u8fc7\u6392\u961f\u5403\u65e9\u9910\u3002\\n\\n## \u6700\u597d\u91d1\u9f9f\u6362\u7f8e\u9152\\n\\n\u53e4\u6709\u8c2a\u4ed9\u4eba\uff08\u5373\u674e\u767d\uff09\u7684\u4e00\u9996\u300a\u8700\u9053\u96be\u300b\u4ee4\u8d3a\u77e5\u7ae0\u5927\u4e3a\u8d5e\u8d4f\uff0c\u76f8\u89c1\u6068\u665a\uff0c\u9042\u6210\u83ab\u9006\u3002\u5bf9\u9152\u5171\u996e\u5904\uff0c\u8d3a\u77e5\u7ae0\u6ca1\u5e26\u9152\u94b1\uff0c\u4e8e\u662f\u89e3\u4e0b\u8170\u95f4\u91d1\u9f9f\uff0c\u4f5c\u4e3a\u9152\u94b1\u3002\u8c2a\u4ed9\u4eba\u5927\u547c\uff0c\u7687\u5bb6\u9970\u54c1\u600e\u53ef\u6362\u9152\uff1f\u8d3a\u77e5\u7ae0\u5927\u7b11\uff0c\u4eca\u65e5\u6709\u5e78\u4e0e\u4ed9\u4eba\u559d\u9152\uff0c\u559d\u4e2a\u75db\u5feb\uff0c\u533a\u533a\u91d1\u9f9f\u54ea\u80fd\u59a8\u788d\uff1f\\n\\n![Vancouver airport](./img/jinguihuanjiu11.jpg)\\n\\n\u4e03\u5929\u65c5\u884c\uff0c\u6211\u4eec\u5206\u522b\u57282019\u5e74\u7684\u6700\u540e\u4e00\u5929\uff0c\u5bf9\u660e\u5e74\u7684\u613f\u671b\u5462\uff1f\\n\\n\u201cGet wiser.\\" \uff08\u957f\u70b9\u513f\u8111\u5427\uff0c\u6211\u8bf4\u3002\uff09\\n\\n\\"Get richer.\\" \uff08\u6765\u70b9\u513f\u94b1\u5427\uff0c\u4f60\u8bf4\u3002\uff09\\n\\n\u6211\u4e0d\u77e5\u660e\u5e74\u53c8\u5982\u4f55\uff0c\u5343\u91d1\u9f9f\uff0c\u6362\u7f8e\u9152\uff0c\u503c\u4e4e\u5426\uff1f\\n\\n\u52aa\u529b\u4e00\u5e74\uff0c\u4e5f\u5c31\u76fc\u671b\u51e0\u6b21\u4efb\u6027\uff1b\u594b\u6597\u7ec8\u8eab\uff0c\u7ec8\u7a76\u53ea\u4e3a\u51e0\u573a\u5dc5\u5cf0\u3002\\n\\n\u800c\u4e16\u95f4\u611f\u60c5\uff0c\u6700\u597d\u4e0d\u8fc7\uff0c\u91d1\u9f9f\u6362\u9152\u3002"},{"id":"\u672a\u89c9\u6c60\u5858\u6625\u8349\u68a6\u9636\u524d\u68a7\u53f6\u5df2\u79cb\u58f0","metadata":{"permalink":"/kilimanjaro/\u672a\u89c9\u6c60\u5858\u6625\u8349\u68a6\u9636\u524d\u68a7\u53f6\u5df2\u79cb\u58f0","editUrl":"https://github.com/jing-gu/kilimanjaro/blog/2019/2019-12-10-\u672a\u89c9\u6c60\u5858\u6625\u8349\u68a6\u9636\u524d\u68a7\u53f6\u5df2\u79cb\u58f0.md","source":"@site/blog/2019/2019-12-10-\u672a\u89c9\u6c60\u5858\u6625\u8349\u68a6\u9636\u524d\u68a7\u53f6\u5df2\u79cb\u58f0.md","title":"\u672a\u89c9\u6c60\u5858\u6625\u8349\u68a6\uff0c\u9636\u524d\u68a7\u53f6\u5df2\u79cb\u58f0","description":"\u5e74\u672b\u5927\u626b\u9664\uff0c\u7b2c\u4e00\u6279\u8981\u88ab\u6211\u626b\u5730\u51fa\u95e8\u7684\u5c31\u662f\u5404\u7c7b\u5e9f\u7eb8\uff0c\u6709\u7528\u7684\u76f4\u63a5\u626b\u63cf\uff0c\u6ca1\u7528\u7684\u901a\u901a\u6495\u70c2\u3002","date":"2019-12-10T00:00:00.000Z","tags":[{"inline":false,"label":"\u968f\u611f","permalink":"/kilimanjaro/tags/\u968f\u611f","description":"\u968f\u611f tag description"}],"readingTime":5.325,"hasTruncateMarker":false,"authors":[],"frontMatter":{"slug":"\u672a\u89c9\u6c60\u5858\u6625\u8349\u68a6\u9636\u524d\u68a7\u53f6\u5df2\u79cb\u58f0","title":"\u672a\u89c9\u6c60\u5858\u6625\u8349\u68a6\uff0c\u9636\u524d\u68a7\u53f6\u5df2\u79cb\u58f0","tags":["\u968f\u611f"],"date":"2019-12-10T00:00:00.000Z"},"unlisted":false,"prevItem":{"title":"\u6700\u597d\u4e0d\u8fc7\u91d1\u9f9f\u6362\u9152","permalink":"/kilimanjaro/\u6700\u597d\u4e0d\u8fc7\u91d1\u9f9f\u6362\u9152"},"nextItem":{"title":"\u541b\u5b50\u8d35\u4eba\u8d31\u5df1\uff0c\u5148\u4eba\u800c\u540e\u5df1","permalink":"/kilimanjaro/\u541b\u5b50\u8d35\u4eba\u8d31\u5df1\u5148\u4eba\u800c\u540e\u5df1"}},"content":"\u5e74\u672b\u5927\u626b\u9664\uff0c\u7b2c\u4e00\u6279\u8981\u88ab\u6211\u626b\u5730\u51fa\u95e8\u7684\u5c31\u662f\u5404\u7c7b\u5e9f\u7eb8\uff0c\u6709\u7528\u7684\u76f4\u63a5\u626b\u63cf\uff0c\u6ca1\u7528\u7684\u901a\u901a\u6495\u70c2\u3002\\n\\n\u5404\u79cd\u6d82\u6d82\u5199\u5199\u7684\u7b14\u8bb0\u672c\u5360\u4e86\u534a\u58c1\u6c5f\u5c71\uff0c\u6709\u7684\u51e0\u4e4e\u6ca1\u6709\u5199\uff0c\u6709\u7684\u53ea\u5269\u51e0\u5f20\u7eb8\uff0c\u5408\u8d77\u6765\u5e76\u6ca1\u6709\u591a\u5c11\u7a7a\u767d\uff0c\u5806\u8d77\u6765\u5374\u9ad8\u8038\u7684\u8ddf\u5c0f\u5c71\u5761\u4e00\u6837\u3002\u987a\u5230\u6700\u540e\u54ea\u4e00\u4e2a\u90fd\u5f97\u7559\u7740\uff0c\u65ad\u820d\u79bb\u7684\u751f\u6d3b\u4e60\u60ef\u59cb\u7ec8\u8fd8\u662f\u6ca1\u6cd5\u575a\u6301\u3002\\n\\n\u8bbd\u523a\u7684\u662f\uff0c\u90a3\u672c\u51e0\u4e4e\u6ca1\u5199\u7684\uff0c\u6070\u662f\u6211\u6700\u559c\u6b22\u7684\u4e00\u672c\u3002\u90a3\u672c\u53cd\u590d\u4f7f\u7528\u7684\uff0c\u5219\u662f\u6211\u6700\u4e0d\u559c\u6b22\u7684\u4e00\u672c\u3002\u5bf9\u4eba\u504f\u5fc3\uff0c\u6211\u5bf9\u4e2a\u7b14\u8bb0\u672c\u7adf\u4e5f\u504f\u5fc3\u3002\u4f46\u6b63\u56e0\u5982\u6b64\uff0c\u88ab\u6211\u6367\u5728\u624b\u91cc\u5199\u7684\u96be\u9053\u4e0d\u8be5\u662f\u6211\u6700\u559c\u6b22\u7684\u4e00\u672c\u5417\uff1f\\n\\n\u6709\u4e2a\u55dc\u597d\u6211\u4ece\u5c0f\u5230\u5927\u5c31\u6ca1\u6539\u5f97\u6389\uff0c\u559c\u6b22\u901b\u6587\u5177\u5e97\uff0c\u770b\u5230\u597d\u770b\u7684\u672c\u5b50\u597d\u770b\u7684\u7b14\u5c31\u8981\u4e70\uff0c\u4e00\u4e70\u5c31\u9ad8\u5174\uff0c\u4e70\u5b8c\u53c8\u4e0d\u7528\u3002\\n\\n\u8fd9\u6bdb\u75c5\u5982\u5f71\u968f\u5f62\uff0c\u5bfc\u81f4\u6211\u9047\u5230\u597d\u770b\u7684\u672c\u5b50\u4f9d\u65e7\u4eea\u5f0f\u611f\u9686\u91cd\uff0c\u5230\u624b\u4e86\u53c8\u820d\u4e0d\u5f97\u7528\u3002\u56e0\u4e3a\u73cd\u60dc\u800c\u4e0d\u60f3\u968f\u4fbf\u5199\uff0c\u6bcf\u6b21\u6b63\u53cd\u9762\u629a\u6478\u4e00\u904d\uff0c\u518d\u4e0d\u538c\u5176\u70e6\u5730\u611f\u53d7\u4e00\u4e0b\u9ad8\u6863\u7eb8\u7684\u624b\u611f\uff0c\u5fc3\u60f3\u8fd9\u4e48\u597d\u7684\u672c\u5b50\u8be5\u5199\u70b9\u4ec0\u4e48\uff0c\u7528\u4ec0\u4e48\u7b14\u5199\u624d\u597d\uff0c\u8fd8\u662f\u6253\u4e2a\u8349\u7a3f\u5427\uff0c\u514d\u5f97\u5199\u9519\u53c8\u5fc3\u75bc\u3002\u4e00\u756a\u5fc3\u7406\u6597\u4e89\u4e4b\u540e\uff0c\u6211\u76ee\u9001\u5fc3\u7231\u7684\u672c\u5b50\u7ee7\u7eed\u88ab\u675f\u4e4b\u9ad8\u9601\uff0c\u7136\u540e\uff0c\u987a\u624b\u62ff\u8d77\u684c\u4e0a\u4e0d\u8d77\u773c\u7684\u53e6\u4e00\u672c\u5927\u5199\u7279\u5199\u3002\\n\\n\u770b\u770b\u8fd9\u4e0d\u8d77\u773c\u7684\u672c\u5b50\u4e0a\u90fd\u5199\u4e86\u4ec0\u4e48\uff0c\u968f\u624b\u4e00\u7ffb\u5185\u5bb9\u771f\u662f\u4e94\u82b1\u516b\u95e8\uff0c\u6709\u5404\u79cd\u4e71\u7684\u8ba4\u4e0d\u51fa\u6765\u7684\u8349\u56fe\uff0c\u753b\u4e86\u534a\u9014\u800c\u5e9f\u7684\u7d20\u63cf\uff0c\u624b\u5199\u82b1\u4f53\u5b57\u7684\u7ec3\u4e60\uff0c\u8179\u7a3f\u53d8\u8349\u7a3f\u7684\u53cd\u590d\u8a8a\u6284\uff0c\u52fe\u52fe\u53c9\u53c9\u7684\u8d2d\u7269\u6e05\u5355\uff0c\u67d0\u5e74\u67d0\u6708\u7684\u822a\u73ed\u4fe1\u606f\uff0c\u5fc3\u8840\u6765\u6f6e\u7684\u624b\u6284\u83dc\u8c31\u2026\\n\\n\u8fd9\u662f\u4e00\u672c\u5728\u201c\u7f8e\u5143\u5c0f\u5e97\u201d\u4e70\u7684\u87ba\u65cb\u7c3f\uff0c\u4e00\u5757\u4e94\u52a0\u5e01\uff0c\u571f\u5230\u6389\u6e23\uff0c\u7eb8\u591a\u8fd8\u4fbf\u5b9c\u3002\u4e8e\u662f\u5b83\u5c31\u548c\u4e00\u5806\u5851\u6599\u76c6\u3001\u5237\u5b50\u3001\u80a5\u7682\u3001\u62d6\u628a\u7b49\u6d17\u6d17\u5237\u5237\u7684\u4f19\u4f34\u4eec\u4e00\u8d77\u88ab\u5e26\u56de\u5bb6\u4e86\u3002\\n\\n\u56e0\u4e3a\u4fbf\u5b9c\uff0c\u5b83\u88ab\u4e70\u6765\u5f53\u8349\u7a3f\u7528\uff0c\u5199\u9519\u4e86\u5199\u4e11\u4e86\u4e5f\u4e0d\u8bb2\u7a76\u3002\u4e0b\u7b14\u524d\u4e0d\u7528\u4e09\u601d\uff0c\u4e5f\u4e0d\u9700\u8003\u7a76\u4ec0\u4e48\u989c\u8272\u7684\u7b14\uff0c\u66f4\u4e0d\u5fc5\u5728\u610f\u6392\u7248\u662f\u5426\u7f8e\u89c2\u3002\u7136\u800c\uff0c\u5f53\u624b\u548c\u8111\u90fd\u4e0d\u88ab\u675f\u7f1a\u7684\u65f6\u5019\uff0c\u6700\u597d\u7684\u521b\u610f\u5c31\u4ea7\u751f\u4e86\uff0c\u56e0\u4e3a\u5373\u65f6\u4ea7\u751f\u7684\u7075\u611f\u603b\u80fd\u88ab\u968f\u610f\u800c\u5927\u80c6\u5f97\u8868\u73b0\u51fa\u6765\uff0c\u901a\u901a\u5199\u5728\u90a3\u4e9b\u6d6a\u8d39\u4e86\u4e5f\u4e0d\u53ef\u60dc\u7684\u7834\u7eb8\u4e0a\u3002\\n\\n\u76f8\u6bd4\u4e4b\u4e0b\uff0c\u6211\u7adf\u66ff\u8fd9\u672c\u6f02\u4eae\u7684\u672c\u5b50\u4ea7\u751f\u4e86\u201c\u82f1\u96c4\u65e0\u7528\u6b66\u4e4b\u5730\u201d\u7684\u60b2\u6006\uff0c\u5185\u91cc\u5d2d\u65b0\uff0c\u5916\u8868\u6ca7\u6851\uff0c\u8fd8\u672a\u5927\u5c55\u5b8f\u56fe\uff0c\u5c31\u5df2\u88ab\u65f6\u95f4\u78e8\u53bb\u4e86\u950b\u8292\u3002\u5948\u4f55\u8fd9\u4e00\u672c\u5c31\u662f\u98df\u4e4b\u65e0\u5473\u5f03\u4e4b\u53ef\u60dc\uff0c\u4e22\u4e0d\u6389\u4e5f\u5199\u4e0d\u4e0b\u3002\\n\\n\u4e22\u4e0d\u6389\u7684\u662f\u4ec0\u4e48\uff0c\u662f\u62b1\u8d1f\uff0c\u5199\u4e0d\u4e0b\u7684\u662f\u4ec0\u4e48\uff0c\u6015\u540e\u6094\u3002\u62b1\u8d1f\u548c\u540e\u6094\u7684\u7ea0\u7ed3\u8ba9\u5c81\u6708\u8e49\u8dce\u4e8e\u6bcf\u4e00\u4e2a\u5341\u5b57\u8def\u53e3\u7684\u8e0c\u8e87\u3002\\n\\n\u4e5f\u8bb8\u6bcf\u4e2a\u4eba\u90fd\u51c6\u5907\u4e86\u4e00\u672c\u53eb\u201c\u660e\u5929\u6211\u8981\u597d\u597d\u5199\u201d\u7684\u6f02\u4eae\u7b14\u8bb0\u672c\uff0c\u7ed3\u679c\u4e00\u5e74\u5230\u5934\u4ec0\u4e48\u90fd\u6ca1\u5199\u3002\\n\\n\u65f6\u95f4\u5374\u5982\u7a7a\u6c14\u5728\u6307\u7f1d\u95f4\u6d41\u901d\uff0c\u5b81\u9759\u800c\u771f\u5b9e\uff0c\u7f13\u6162\u800c\u6b8b\u5fcd\u3002\u4eba\u751f\u5c31\u662f\u624b\u4e0a\u7684\u7b7e\u5b57\u7b14\uff0c\u4e0d\u8d77\u773c\u7684\u751f\u547d\u4eff\u4f5b\u7b14\u82af\u91cc\u7684\u90a3\u4e00\u622a\u58a8\u6c34\uff0c\u4f60\u671b\u7740\u5b83\u65f6\u8fd8\u5f88\u591a\uff0c\u5374\u4e0d\u77e5\u54ea\u4e00\u5929\u5c31\u6d88\u8017\u5230\u8fde\u4e00\u4e2a\u5b57\u6bcd\u4e5f\u5199\u4e0d\u51fa\u6765\u4e86\uff0c\u4efb\u51ed\u4f60\u5728\u7eb8\u4e0a\u5212\u4e0b\u4e00\u9053\u9053\u7a7a\u75d5\u3002\\n\\n\u5982\u679c\u6761\u4ef6\u5141\u8bb8\uff0c\u5982\u679c\u673a\u7f18\u5de7\u5408\uff0c\u5982\u679c\u4eba\u751f\u4efb\u4f60\u4e66\u5199\uff0c\u8c01\u4e0d\u613f\u610f\u7528\u88c5\u5e27\u7cbe\u7f8e\u7684\u7b14\u8bb0\u672c\u63cf\u7ed8\u8bd7\u4e00\u822c\u7684\u65e5\u5e38\uff1f\\n\\n\u4f46\u662f\u751f\u6d3b\u4e2d\u54ea\u6709\u90a3\u4e48\u5de7\u7684\u65f6\u523b\uff0c\u53ef\u4ee5\u521a\u597d\u62e5\u6709\u597d\u7eb8\u3001\u597d\u7b14\u3001\u597d\u6545\u4e8b\uff1f\u53ef\u4ee5\u9759\u5fc3\u5750\u4e0b\u5199\u7684\u65e0\u6028\u65e0\u6094\uff1f\u751f\u6d3b\u9700\u8981\u6211\u968f\u673a\u5e94\u53d8\uff0c\u5728\u61d2\u60f0\u4e2d\u594b\u529b\u6323\u624e\uff0c\u51c6\u5907\u7740\u8ba1\u5212\u7740\uff0c\u9700\u8981\u65f6\u4f9d\u65e7\u4e0d\u662f\u6ca1\u7b14\u5c31\u662f\u6ca1\u7eb8\uff0c\u4e0b\u7b14\u4e4b\u5904\u5f80\u5f80\u90fd\u662f\u4e0d\u77e5\u4ece\u54ea\u513f\u6495\u6765\u7684\u534a\u5f20\u5e9f\u7eb8\u7247\u3002\\n\\n\u773c\u524d\u7684\u4e24\u672c\u4eff\u4f5b\u4e24\u79cd\u4eba\u751f\u3002\u524d\u8005\u968f\u610f\u4e66\u5199\uff0c\u6f47\u6d12\u5c3d\u5174\uff0c\u540e\u8005\u7aef\u5e84\u6574\u9f50\uff0c\u5374\u4e00\u7247\u7a7a\u767d\u3002"},{"id":"\u541b\u5b50\u8d35\u4eba\u8d31\u5df1\u5148\u4eba\u800c\u540e\u5df1","metadata":{"permalink":"/kilimanjaro/\u541b\u5b50\u8d35\u4eba\u8d31\u5df1\u5148\u4eba\u800c\u540e\u5df1","editUrl":"https://github.com/jing-gu/kilimanjaro/blog/2019/2019-07-11-\u541b\u5b50\u8d35\u4eba\u8d31\u5df1\u5148\u4eba\u800c\u540e\u5df1.md","source":"@site/blog/2019/2019-07-11-\u541b\u5b50\u8d35\u4eba\u8d31\u5df1\u5148\u4eba\u800c\u540e\u5df1.md","title":"\u541b\u5b50\u8d35\u4eba\u8d31\u5df1\uff0c\u5148\u4eba\u800c\u540e\u5df1","description":"mtl metro","date":"2019-07-11T00:00:00.000Z","tags":[{"inline":false,"label":"\u968f\u611f","permalink":"/kilimanjaro/tags/\u968f\u611f","description":"\u968f\u611f tag description"},{"inline":true,"label":"\u8499\u7279\u5229\u5c14","permalink":"/kilimanjaro/tags/\u8499\u7279\u5229\u5c14"}],"readingTime":5.925,"hasTruncateMarker":false,"authors":[],"frontMatter":{"slug":"\u541b\u5b50\u8d35\u4eba\u8d31\u5df1\u5148\u4eba\u800c\u540e\u5df1","title":"\u541b\u5b50\u8d35\u4eba\u8d31\u5df1\uff0c\u5148\u4eba\u800c\u540e\u5df1","tags":["\u968f\u611f","\u8499\u7279\u5229\u5c14"],"date":"2019-07-11T00:00:00.000Z"},"unlisted":false,"prevItem":{"title":"\u672a\u89c9\u6c60\u5858\u6625\u8349\u68a6\uff0c\u9636\u524d\u68a7\u53f6\u5df2\u79cb\u58f0","permalink":"/kilimanjaro/\u672a\u89c9\u6c60\u5858\u6625\u8349\u68a6\u9636\u524d\u68a7\u53f6\u5df2\u79cb\u58f0"},"nextItem":{"title":"\u65e0\u5e38\u7686\u65e5\u5e38","permalink":"/kilimanjaro/\u65e0\u5e38\u7686\u65e5\u5e38"}},"content":"![mtl metro](./img/metro01.jpg)\\n\u5730\u94c1\u662f\u4e2a\u51e0\u4e4e\u6ca1\u6709\u4eba\u60c5\u51b7\u6696\u7684\u5730\u65b9\uff0c\u5168\u4e16\u754c\u7684\u5730\u94c1\u90fd\u4e00\u6837\u3002\u7ad9\u7740\u7684\u4eba\u60f3\u5750\u4e0b\uff0c\u5750\u7740\u7684\u4eba\u60f3\u51fa\u53bb\u3002\\n\\n\u53a2\u95e8\u6253\u5f00\uff0c\u4e00\u540c\u4e0a\u6765\u51e0\u4e2a\u65e0\u804a\u7684\u9762\u5b54\u3002\u6211\u521a\u51c6\u5907\u5750\u4e0b\u65f6\u7a81\u7136\u770b\u89c1\u4e00\u4e2a\u5934\u53d1\u82b1\u767d\u7684\u4eba\u8d70\u8fdb\u6765\uff0c\u6b63\u4e49\u611f\u7a81\u5982\u5176\u6765\uff1a\u8ba9\u4e2a\u5ea7\u5427\u3002\u6211\u4ee5\u4e3a\u8001\u4eba\u90fd\u662f\u60f3\u5750\u7684\u3002\u6211\u6295\u4ee5\u671f\u5f85\u7684\u76ee\u5149\uff0c\u8d77\u8eab\uff0c\u53f0\u8bcd\u8fd8\u6ca1\u8bf4\u51fa\u53e3\uff0c\u8001\u4eba\u5374\u7acb\u9a6c\u770b\u5411\u6211\uff0c\u4e25\u8083\u6de1\u5b9a\u5730\u8bf4\uff1aNon non\uff0csit\uff01\uff08\u522b\uff0c\u4f60\u5750\uff01\uff09\\n\\n\u786e\u5207\u7684\u8bf4\uff0c\u6211\u90a3\u72b6\u6001\u90fd\u4e0d\u80fd\u53eb\u8ba9\u5ea7\uff0c\u662f\u8ba9\u5ea7\u7684\u672a\u5b8c\u6210\u65f6\u3002\u6211\u53ea\u4e0d\u8fc7\u662f\u628a\u6b63\u51c6\u5907\u5750\u4e0b\u53bb\u7684\u5f2f\u66f2\u7684\u819d\u76d6\u77ac\u95f4\u8e6c\u76f4\u4e86\u800c\u5df2\u3002\u8001\u4eba\u770b\u6211\u6709\u8ba9\u5ea7\u7684\u6001\u5ea6\uff0c\u5df2\u7136\u4e0d\u723d\uff0c\u56fa\u6267\u5730\u7ad9\u7740\uff0c\u6211\u7adf\u65e0\u8a00\u4ee5\u5bf9\uff0c\u514b\u5236\u4e00\u95ea\u800c\u8fc7\u7684\u5c34\u5c2c\uff0c\u4e56\u4e56\u5730\u5750\u4e0b\u4e86\u3002\\n\\n\u54ce\u54df\u4f60\u4e0d\u5750\u6b63\u597d\uff0c\u4f60\u8001\u5c31\u8be5\u5750\u5417\uff0c\u6211\u5e74\u8f7b\u5c31\u8be5\u8ba9\u5417\uff0c\u6211\u8fd9\u5fd9\u4e86\u4e00\u5929\u7d2f\u6b7b\u4e86\uff0c\u5750\u4e0b\u6b47\u6b47\u6b63\u597d\u2026\u2026 \u731b\u7136\u95f4\u6211\u610f\u8bc6\u5230\u8fd9\u4e0d\u77e5\u4ece\u4f55\u800c\u6765\u7684\u7410\u788e\u7684\u7262\u9a9a\uff0c\u6216\u662f\u81ea\u6211\u5b89\u6170\u3002\u770b\u7740\u8f66\u7a97\u91cc\u81ea\u5df1\u7684\u5012\u5f71\uff0c\u6211\u771f\u7684\u662f\u60f3\u5e2e\u52a9\u522b\u4eba\u5417\uff1f\u8fd8\u662f\u559c\u6b22\u5e2e\u52a9\u4ed6\u4eba\u540e\u7684\u81ea\u6211\u611f\u53d7\u826f\u597d\uff0c\u54ea\u6015\u53ea\u662f\u4e00\u77ac\u95f4\u7684\u5c0f\u5c0f\u7684\u81ea\u6211\u6b23\u8d4f\uff0c\u91cd\u70b9\u5374\u662f\u52a9\u4eba\u4e3a\u4e50\u7684\u201c\u4e50\u201d\u5b57\u3002\\n\\n\u4f46\u662f\uff0c\u522b\u4eba\u4e0d\u4e00\u5b9a\u9700\u8981\u6216\u63a5\u53d7\u5e2e\u52a9\u3002\u90a3\u4e48\uff0c\u5728\u5584\u5fc3\u5f97\u4e0d\u5230\u8ba4\u53ef\u6216\u63a5\u7eb3\u65f6\uff0c\u539f\u672c\u79ef\u6781\u7684\u5fc3\u60c5\u7adf\u7136\u4f1a\u6162\u6162\u7d2f\u79ef\u6210\u8d1f\u80fd\u91cf\u3002\\n\\n![mtl metro](./img/metro02.jpg)\\n\\n\u5730\u94c1\u662f\u4e2a\u51e0\u4e4e\u6ca1\u6709\u4eba\u60c5\u51b7\u6696\u7684\u5730\u65b9\uff0c\u6700\u7a77\u7684\u6700\u81ed\u7684\u90fd\u805a\u96c6\u4e8e\u6b64\u3002\u8d77\u521d\u6211\u5bb9\u6613\u6709\u607b\u9690\u4e4b\u5fc3\uff0c\u4e45\u800c\u4e45\u4e4b\u53d1\u73b0\u4e86\u4e0d\u5c11\u804c\u4e1a\u8ba8\u996d\u7684\u719f\u8138\uff0c\u4e5f\u8bb8\u6709\u7684\u4eba\u662f\u771f\u7a77\uff0c\u4e5f\u8bb8\u6709\u7684\u4eba\u662f\u88c5\u7a77\u3002\u4e00\u4e9b\u65e0\u4e1a\u6d41\u6c11\u7ec8\u65e5\u9760\u4e5e\u8ba8\u6d88\u78e8\u65f6\u5149\u3002\\n\\n\u7ad9\u53f0\u4e0a\u7b49\u8f66\u7684\u4eba\u6216\u7ad9\u6216\u5750\uff0c\u90a3\u5f20\u719f\u8138\u4fbf\u968f\u7740\u4eba\u7fa4\u4e00\u6761\u8fb9\u7684\u95ee\u8fc7\u53bb\uff0c\u4f46\u8fd9\u6837\u7684\u6e38\u51fb\u6218\u57fa\u672c\u6536\u83b7\u6d45\u8584\uff0c\u6bd5\u7adf\u5927\u591a\u6570\u4eba\u5bf9\u5176\u7f6e\u4e4b\u4e0d\u7406\u3002\u4e0d\u8fdc\u5904\u4e00\u4e2a\u5750\u7740\u7684\u8001\u8005\u4e5f\u672a\u642d\u7406\uff0c\u4ed6\u5931\u671b\u5730\u7ee7\u7eed\u5411\u524d\u8d70\uff0c\u6ca1\u8d70\u51e0\u6b65\u5374\u626d\u5934\u5927\u9a82\u4e86\u8001\u8005\u51e0\u53e5\u3002\u6211\u60ca\u5f97\u8d76\u7d27\u6536\u56de\u4e86\u89c2\u5bdf\u7684\u89c6\u7ebf\uff0c\u76f4\u89c6\u524d\u65b9\u7a7a\u8361\u7684\u94c1\u8f68\uff0c\u4eff\u4f5b\u4ec0\u4e48\u4e5f\u6ca1\u542c\u89c1\u3002\\n\\n\u8fd9\u4e16\u754c\u7b80\u76f4\u662f\u8981\u9020\u53cd\uff0c\u597d\u4eba\u96be\u5f53\uff0c\u4e0d\u8bf4\u8bdd\u4e5f\u6328\u9a82\u3002\u518d\u9047\u5230\u8fd9\u4e9b\u4eba\u771f\u5f97\u6234\u4e0a\u8033\u673a\uff0c\u88c5\u804b\u4f5c\u54d1\uff0c\u88c5\u6b7b\u88c5\u7761\u3002\u6211\u672c\u6765\u8d70\u8def\u4e60\u60ef\u5c31\u5f88\u5feb\uff0c\u73b0\u5728\u8d70\u7684\u66f4\u5feb\uff0c\u5feb\u5230\u8fde\u8ba8\u996d\u7684\u8ddf\u4e0d\u4e0a\u4e5f\u558a\u4e0d\u52a8\u3002\\n\\n![mtl metro](./img/metro03.jpg)\\n\\n\u4e5f\u8bb8\u6211\u8d70\u7684\u8fd8\u4e0d\u591f\u5feb\uff0c\u6211\u7adf\u7136\u88ab\u4e00\u4e2a\u8001\u5a46\u5a46\u62e6\u4e0b\u4e86\u3002\u6211\u751a\u81f3\u6ca1\u6ce8\u610f\u5230\u89c6\u7ebf\u91cc\u8fd9\u4e2a\u77ee\u5c0f\u7684\u8eab\u5f71\uff0c\u5979\u731b\u7684\u4e00\u626d\u5934\u5c31\u5f20\u53e3\u558a\u4f4f\u6211\uff1a\u201c\u4f60\u80fd\u5e2e\u6211\u62ce\u4e00\u4e0b\u5417\uff1f\u201d \u8ba9\u6211\u8d70\u8def\u4e5f\u80fd\u8e29\u51fa\u6025\u5239\u8f66\u7684\u611f\u89c9\u4e5f\u662f\u7edd\u4e86\u3002\u8001\u5a46\u5a46\u505c\u5728\u4e0b\u884c\u697c\u68af\u7684\u5730\u65b9\uff0c\u8eab\u8fb9\u4e00\u4e2a\u5de8\u5927\u7684\u8d2d\u7269\u888b\uff0c\u4f30\u8ba1\u662f\u5df2\u7ecf\u62ce\u4e0d\u52a8\u4e86\u3002\u5f53\u65f6\u6211\u8d70\u7684\u5f88\u5feb\uff0c\u8fd8\u6234\u7740\u8033\u673a\uff0c\u65c1\u8fb9\u90a3\u4e48\u591a\u7ecf\u8fc7\u7684\u9752\u5e74\u58ee\u6c49\u5979\u4e0d\u558a\uff0c\u504f\u558a\u4e2a\u59d1\u5a18\u6765\u63d0\u91cd\u7269\uff0c\u8fd9\u963f\u5a46\u662f\u591a\u4e48\u7f3a\u4e4f\u773c\u5934\u89c1\u8bc6\u3002\\n\\n\u75c5\u6025\u4e71\u6295\u533b\uff0c\u4e5f\u662f\u56e0\u4e3a\u9700\u8981\u5e2e\u52a9\u7684\u5f31\u8005\u4f1a\u4e3b\u52a8\u8bf7\u6c42\u5e2e\u52a9\u3002\u6211\u4f30\u8ba1\u5730\u94c1\u5feb\u8fdb\u7ad9\u4e86\uff0c\u5fc3\u60f3\u65f6\u95f4\u5b9d\u8d35\uff0c\u4e8e\u662f\u6211\u679c\u65ad\u5730\u5e2e\u5979\u62ce\u8d77\u888b\u5b50\u5c31\u5f80\u4e0b\u8d70\uff0c\u5230\u5e95\u624d\u53d1\u73b0\u963f\u5a46\u8fd8\u5f98\u5f8a\u5728\u7b2c\u56db\u53f0\u9636\u3002\u771f\u662f\u4e0d\u597d\u610f\u601d\uff0c\u6211\u600e\u4e48\u529b\u6c14\u90a3\u4e48\u5927\uff0c\u4e5f\u6ca1\u7b49\u4e00\u4e0b\u8001\u4eba\u5bb6\uff0c\u770b\u6765\u8fd9\u51e0\u5e74\u62ce\u884c\u674e\u7684\u672c\u4e8b\u662f\u953b\u70bc\u4e86\u4e0d\u5c11\u3002\u6211\u76ee\u9001\u8001\u4eba\u4fa7\u7740\u8eab\u5b50\u4e00\u6b65\u4e00\u4e2a\u53f0\u9636\u5730\u5f80\u4e0b\u8d70\uff0c\u5979\u5c3d\u6700\u5927\u7684\u52aa\u529b\u5f80\u4e0b\u632a\u3002\u53f0\u9636\u4e0b\u4e86\u516d\u4e03\u7ea7\uff0c\u5979\u4e5f\u8fb9\u4e0b\u8fb9\u8bf4\u4e86\u516d\u4e03\u6b21\u8c22\u8c22\uff0c\u7ede\u7684\u6211\u5fc3\u91cc\u4e00\u9635\u96be\u8fc7\u4e00\u9635\u9ad8\u5174\u3002\\n\\n\u5730\u94c1\u5f88\u5feb\u8fdb\u7ad9\uff0c\u6211\u6545\u610f\u7ad9\u5f97\u79bb\u5979\u7a0d\u5fae\u8fdc\u4e86\u70b9\uff0c\u4f46\u6211\u8fd8\u662f\u975e\u8981\u770b\u7740\u90a3\u8001\u592a\u8fdb\u4e86\u8f66\u53a2\u624d\u81ea\u5df1\u4e5f\u8fdb\u53bb\u4e86\uff0c\u611f\u89c9\u597d\u50cf\u8fd9\u6837\u4e8b\u60c5\u624d\u5706\u6ee1\u4e86\u3002\\n\\n\u5730\u94c1\u662f\u4e2a\u51e0\u4e4e\u6ca1\u6709\u4eba\u60c5\u51b7\u6696\u7684\u5730\u65b9\u3002\u51fa\u4e8e\u65e0\u5fc3\u4e4b\u4e3e\uff0c\u770b\u4f3c\u4e3e\u624b\u4e4b\u52b3\uff0c\u5374\u5f00\u5fc3\u5f97\u83ab\u540d\u5176\u5999\u3002\u8fd9\u8c08\u4e0d\u4e0a\u4e50\u5584\u597d\u65bd\uff0c\u4e5f\u7b97\u4e0d\u4e86\u54c1\u5fb7\u9ad8\u5c1a\uff0c\u53ea\u80fd\u8bf4\u642c\u884c\u674e\u53ef\u80fd\u662f\u4e00\u4ef6\u4ee4\u53cc\u65b9\u90fd\u8eab\u5fc3\u6109\u60a6\u7684\u4e8b\u60c5\u3002\\n\\n\u5730\u94c1\u662f\u4e2a\u51e0\u4e4e\u6ca1\u6709\u4eba\u60c5\u51b7\u6696\u7684\u5730\u65b9\u3002\u6211\u6240\u89c1\u7684\u4e5f\u662f\u4f60\u6240\u89c1\u7684\uff0c\u5343\u4e07\u4e2a\u4eba\u80cc\u540e\u6709\u5343\u4e07\u4e2a\u6545\u4e8b\uff0c\u4f46\u4eba\u4eec\u4e0d\u62ac\u773c\uff0c\u4e0d\u8046\u542c\u3002\u5168\u4e16\u754c\u7684\u5730\u94c1\u90fd\u4e00\u6837\uff0c\u56e0\u4e3a\u5168\u4e16\u754c\u7684\u4eba\u90fd\u4e00\u6837\u3002\\n\\n![mtl metro](./img/metro04.jpg)"},{"id":"\u65e0\u5e38\u7686\u65e5\u5e38","metadata":{"permalink":"/kilimanjaro/\u65e0\u5e38\u7686\u65e5\u5e38","editUrl":"https://github.com/jing-gu/kilimanjaro/blog/2019/2019-05-04-\u65e0\u5e38\u7686\u65e5\u5e38.md","source":"@site/blog/2019/2019-05-04-\u65e0\u5e38\u7686\u65e5\u5e38.md","title":"\u65e0\u5e38\u7686\u65e5\u5e38","description":"mtl","date":"2019-05-04T00:00:00.000Z","tags":[{"inline":false,"label":"\u968f\u611f","permalink":"/kilimanjaro/tags/\u968f\u611f","description":"\u968f\u611f tag description"},{"inline":true,"label":"\u8499\u7279\u5229\u5c14","permalink":"/kilimanjaro/tags/\u8499\u7279\u5229\u5c14"}],"readingTime":5.835,"hasTruncateMarker":false,"authors":[],"frontMatter":{"slug":"\u65e0\u5e38\u7686\u65e5\u5e38","title":"\u65e0\u5e38\u7686\u65e5\u5e38","tags":["\u968f\u611f","\u8499\u7279\u5229\u5c14"],"date":"2019-05-04T00:00:00.000Z"},"unlisted":false,"prevItem":{"title":"\u541b\u5b50\u8d35\u4eba\u8d31\u5df1\uff0c\u5148\u4eba\u800c\u540e\u5df1","permalink":"/kilimanjaro/\u541b\u5b50\u8d35\u4eba\u8d31\u5df1\u5148\u4eba\u800c\u540e\u5df1"},"nextItem":{"title":"\u5f80\u4e8b\u5e76\u4e0d\u5982\u70df","permalink":"/kilimanjaro/\u5f80\u4e8b\u5e76\u4e0d\u5982\u70df"}},"content":"![mtl](./img/wuchang.jpg)\\n\\n\u6211\u603b\u8bf4\u9b41\u5317\u514b\u7684\u5929\u6c14\u53d8\u5316\u4e4b\u65e0\u5e38\uff0c\u6625\u5929\u770b\u4f3c\u9065\u9065\u65e0\u671f\u3002\u51e0\u4e4e\u6bcf\u5468\u90fd\u6709\u6c14\u8c61\u9884\u62a5\u8bf4\u4e0b\u5468\u6709\u671b\u8e0f\u5165\u6625\u5929\uff0c\u4f46\u603b\u662f\u575a\u6301\u4e0d\u5230\u5468\u65e5\uff0c\u7136\u540e\u4e2d\u9014\u4e00\u80a1\u5bd2\u6d41\uff0c\u522e\u8d70\u4e86\u51e0\u5929\u9633\u5149\u822c\u7684\u6069\u8d50\u3002\u9694\u65e5\u51b7\u98ce\u51b7\u96e8\u53c8\u4e0d\u6253\u62db\u547c\uff0c\u624d\u8131\u4e0b\u7684\u8863\u670d\u90fd\u6765\u4e0d\u53ca\u7a7f\u56de\u53bb\u3002\\n\\n\u5f53\u5ba2\u89c2\u65e5\u671f\u5df2\u8fdb\u5165\u6625\u5929\u7684\u65f6\u5019\uff0c\u4e3b\u89c2\u611f\u77e5\u8fd8\u505c\u7559\u5728\u51ac\u5929\uff0c\u53ef\u60b2\u7684\u662f\u5927\u697c\u7684\u516c\u5171\u4f9b\u6696\u7cfb\u7edf\u5374\u4e0d\u4ee5\u4eba\u7684\u4e3b\u89c2\u610f\u5fd7\u4e3a\u8f6c\u79fb\uff0c\u6696\u6c14\u6309\u7167\u8282\u6c14\u89c4\u5b9a\u8bf4\u7ed3\u675f\u5c31\u7ed3\u675f\uff0c\u90fd\u4e0d\u77e5\u5728\u54ea\u5929\u5c31\u88ab\u4e00\u5200\u5207\u4e86\uff0c\u53ea\u8bb0\u5f97\u67d0\u65e5\u6211\u8d77\u5e8a\u540e\u9f3b\u585e\uff0c\u5f53\u5929\u5c31\u5f00\u59cb\u611f\u5192\u53d1\u70e7\uff0c\u6211\u611f\u89c9\u4e0d\u5bf9\u52b2\uff0c\u4e00\u6478\u6696\u6c14\u7247\uff0c\u679c\u7136\uff0c\u51c9\u900f\u4e86\u3002\u5927\u6982\u662f\u4e0a\u4e2a\u6708\u4e2d\u65ec\u6211\u5012\u4e0b\u4e86\uff0c\u6b7b\u625b\u4e86\u4e00\u5468\u597d\u8f6c\uff0c\u4e24\u5468\u590d\u6d3b\u3002\u611f\u6168\u4e07\u5206\uff0c\u6211\u6089\u5fc3\u4fdd\u517b\u4e86\u4e00\u6574\u4e2a\u51ac\u5929\uff0c\u81ea\u8c6a\u6ca1\u6709\u4efb\u4f55\u5c0f\u75c5\u5c0f\u75db\uff0c\u5374\u4e0d\u66fe\u6599\u5230\u81ea\u5df1\u7adf\u7136\u5012\u5728\u4e86\u6625\u5929\u7684\u8d77\u8dd1\u7ebf\u4e0a\u3002\\n\\n\u65f6\u95f4\u5c31\u662f\u4e0d\u53ef\u601d\u8bae\u7684\u89e3\u836f\uff0c\u4e00\u5207\u7684\u7b54\u6848\u90fd\u662f\u4e60\u60ef\u5c31\u597d\uff0c\u65e0\u5e38\u4e5f\u4f1a\u53d8\u6210\u65e5\u5e38\u3002\u5929\u6c14\u65e0\u5e38\uff0c\u6211\u4e0d\u6562\u5962\u671b\uff0c\u4f46\u6700\u8fd1\u662f\u771f\u7684\u53d8\u6696\u4e86\uff0c\u6211\u59d1\u4e14\u5c31\u518d\u76f8\u4fe1\u6c14\u8c61\u9884\u62a5\u4e00\u6b21\uff0c\u4e0b\u5468\u6709\u671b\u8e0f\u5165\u6625\u5929\uff01\\n\\n\u51ac\u5929\u7684\u90a3\u51e0\u4e2a\u6708\uff0c\u6211\u65e0\u5fc3\u6b23\u8d4f\u8fd9\u4e2a\u57ce\u5e02\u7684\u9762\u8c8c\uff0c\u56e0\u4e3a\u5929\u51b7\u65f6\u4ec0\u4e48\u90fd\u770b\u4e0d\u89c1\uff0c\u4ec0\u4e48\u90fd\u4e0d\u60f3\u770b\u3002\u773c\u775b\u4e0d\u77e5\u5f80\u54ea\u513f\u779f\uff0c\u5927\u6982\u5728\u779f\u54ea\u91cc\u53ef\u4ee5\u6321\u98ce\u906e\u96e8\uff0c\u4e8e\u662f\u8d76\u7d27\u7f29\u5934\u5f13\u8170\u94bb\u8fdb\u4e0b\u4e00\u4e2a\u6709\u5c4b\u9876\u7684\u5730\u65b9\uff0c\u6bcf\u8d70\u5feb\u4e00\u6b65\uff0c\u5c31\u591a\u4eab\u53d7\u4e00\u4f1a\u513f\u5ba4\u5185\u7684\u6696\u6c14\u3002\\n\\n\u5929\u51b7\u65f6\uff0c\u8fd1\u5728\u54ab\u5c3a\u7684\u4eba\u548c\u7269\u4e5f\u4e0d\u5165\u773c\uff0c\u5168\u9760\u4e60\u60ef\u6307\u6325\u5f80\u54ea\u513f\u8d70\uff0c\u773c\u795e\u53ea\u662f\u8f85\u52a9\u3002\u5076\u5c14\u591a\u770b\u4e00\u773c\uff0c\u90a3\u4eba\u597d\u9762\u719f\uff0c\u6628\u5929\u597d\u50cf\u4e5f\u5728\u8fd9\u91cc\u7528\u95ee\u597d\u7684\u65b9\u5f0f\u5411\u4eba\u4e5e\u8ba8\uff0c\u4e5f\u8bb8\u524d\u5929\u4e5f\u5728\u8fd9\u91cc\u3002\u4ed6\u4e60\u60ef\u6027\u5730\u91cd\u590d\u81ea\u5df1\u7684\u52a8\u4f5c\uff0c\u6211\u4e60\u60ef\u6027\u5730\u4e0e\u4ed6\u64e6\u80a9\u800c\u8fc7\u3002\\n\\n\u5929\u6696\u65f6\uff0c\u6211\u731b\u7136\u53d1\u73b0\u89c6\u7ebf\u90fd\u53d8\u5f00\u9614\u4e86\uff0c\u540c\u6837\u7684\u8def\u5c45\u7136\u4ea7\u751f\u4e0d\u540c\u7684\u666f\u81f4\uff0c\u4eff\u4f5b\u51e0\u4e2a\u6708\u6211\u624d\u5f00\u4e86\u773c\u3002\u9053\u8def\u548c\u5929\u7a7a\u90fd\u5728\u53d8\uff0c\u4f46\u53d8\u5316\u6700\u5927\u7684\u8fd8\u662f\u4eba\uff0c\u8d70\u8def\u7684\u8282\u594f\u90fd\u53d8\u6162\u4e86\uff0c\u548c\u5929\u51b7\u65f6\u6a2a\u51b2\u76f4\u649e\u7684\u539f\u5219\u4e00\u6837\uff0c\u6bcf\u8d70\u6162\u4e00\u6b65\uff0c\u5c31\u591a\u4eab\u53d7\u4e00\u4f1a\u513f\u5962\u4f88\u7684\u9633\u5149\u3002\\n\\n\u4e00\u65e6\u4e60\u60ef\u4e86\u51b7\u5929\u7684\u65e0\u5e38\uff0c\u9633\u5149\u707f\u70c2\u7684\u65e5\u5e38\u90fd\u8db3\u4ee5\u6210\u4e3a\u4e00\u5929\u7684\u5c0f\u786e\u5e78\u3002\\n\\n\u6e10\u6e10\u5730\uff0c\u6211\u53d1\u73b0\u81ea\u5df1\u613f\u610f\u5728\u5ba4\u5916\u5446\u66f4\u4e45\uff0c\u5f00\u59cb\u5750\u5728\u516c\u56ed\u957f\u51f3\u4e0a\uff0c\u81ea\u7136\u5730\u4f1a\u626d\u5934\u770b\u5929\uff0c\u8116\u5b50\u7ec8\u4e8e\u4e5f\u4e0d\u50f5\u4e86\uff0c\u4f53\u5185\u5916\u56e0\u7d20\u90fd\u5728\u8bf4\u660e\u6e29\u6696\u7684\u6c14\u5019\u5373\u5c06\u6210\u4e3a\u65e5\u5e38\u3002\u6211\u770b\u89c1\u66fe\u7ecf\u770b\u4e0d\u89c1\u7684\uff0c\u542c\u89c1\u66fe\u7ecf\u542c\u4e0d\u89c1\u7684\uff0c\u57ce\u5e02\u90fd\u77ac\u95f4\u53d8\u597d\u770b\u4e86\u3002\u57ce\u5e02\u4e5f\u8bb8\u4ece\u6765\u4e0d\u53d8\uff0c\u4f46\u82e5\u4e0d\u89c2\u5bdf\uff0c\u518d\u7f8e\u7684\u5730\u65b9\u4e5f\u6ca1\u6709\u98ce\u666f\u53ef\u8a00\uff0c\u7b80\u76f4\u767d\u957f\u4e00\u53cc\u773c\u3002\u53ef\u60dc\u4eba\u4eec\u5e76\u4e0d\u89c2\u5bdf\u81ea\u5df1\u7684\u65e5\u5e38\uff0c\u66f4\u4e0d\u8981\u63d0\u5ba1\u89c6\u3002\\n\\n\u521a\u6765\u8499\u7279\u5229\u5c14\u7684\u51e0\u5929\u5185\u6211\u5199\u4e86\u7b2c\u4e00\u7bc7[\u300a\u65e0\u51fa\u8def\u5496\u5561\u9986\u300b](/\u65e0\u51fa\u8def\u5496\u5561\u9986)\uff0c\u60f3\u60f3\u4e5f\u771f\u662f\u5de7\uff0c\u51e0\u4e2a\u6708\u540e\u6211\u5c45\u7136\u53c8\u8fdb\u5165\u4e86\u540c\u6837\u7684\u5fc3\u5883\u3002\u6211\u9009\u62e9\u4e86\u4e00\u4e2a\u53ef\u4ee5\u770b\u5230\u6240\u6709\u5ea7\u4f4d\u548c\u5427\u53f0\u7684\u684c\u5b50\uff0c\u8fd9\u6837\u6211\u53ef\u4ee5\u968f\u65f6\u89c2\u5bdf\u6765\u5f80\u7684\u7537\u7537\u5973\u5973\u8001\u8001\u5c11\u5c11\u3002\u867d\u7136\u6211\u5728\u770b\u4e00\u672c\u4e66\uff0c\u4f46\u8fd9\u4e0d\u59a8\u788d\u6211\u5927\u5927\u65b9\u65b9\u5730\u89c2\u5bdf\u4ed6\u4eba\uff1a\u6709\u4eba\u9ad8\u8c08\u9614\u8bba\u751f\u610f\u5f80\u6765\uff1b\u6709\u4eba\u4e09\u4e94\u6210\u7fa4\u805a\u4f17\u804a\u5929\uff1b\u6709\u4eba\u4f4e\u5934\u8033\u8bed\u5206\u5403\u4e00\u4efd\u751c\u70b9\uff1b\u6709\u4eba\u5750\u5728\u5427\u53f0\u65c1\u81ea\u8a00\u81ea\u8bed\uff1b\u6709\u4eba\u72ec\u81ea\u54c1\u5c1d\uff0c\u4e00\u53e3\u4e00\u53e3\u5403\u7684\u5341\u5206\u8ba4\u771f\u3002\u770b\u8fd9\u4e2a\u4eba\u5403\u4e1c\u897f\u771f\u662f\u6709\u79cd\u83ab\u540d\u7684\u6cbb\u6108\u611f\uff0c\u5207\u86cb\u7cd5\u6574\u9f50\u800c\u7ec6\u81f4\uff0c\u62bf\u4e00\u53e3\u8fd8\u8981\u518d\u628a\u53c9\u5b50\u8214\u5e72\u51c0\uff0c\u7aef\u8be6\u4e00\u773c\uff0c\u518d\u5207\u4e0b\u4e00\u5200\uff0c\u6211\u51e0\u4e4e\u60f3\u51b2\u4e0a\u53bb\u95ee\uff1a\u4f60\u5230\u5e95\u5403\u7684\u4ec0\u4e48\u90a3\u4e48\u9999\uff1f\\n\\n\u4eba\u679c\u7136\u8fd8\u662f\u6709\u7b2c\u516d\u611f\u7684\uff0c\u5403\u7684\u5c31\u7b97\u518d\u5fd8\u4e4e\u6240\u4ee5\u8fd8\u662f\u4f1a\u53d1\u89c9\u6709\u4eba\u5728\u5077\u770b\u3002\u6211\u7acb\u523b\u628a\u5934\u626d\u4e86\u4e00\u5927\u5708\uff0c\u597d\u50cf\u5728\u7f13\u89e3\u8116\u5b50\u75bc\uff0c\u518d\u7a0d\u5fae\u81ea\u7136\u5730\u628a\u89c6\u7ebf\u6536\u56de\u5230\u2026\u2026\u4e0d\u77e5\u9053\u770b\u5230\u7b2c\u51e0\u884c\uff0c\u8fd8\u8f9b\u4e8f\u6211\u624b\u4e0a\u6709\u672c\u4e66\u3002\\n\\n\u5468\u906d\u65f6\u800c\u55a7\u95f9\u4e00\u9635\u53c8\u5f52\u4e8e\u5e73\u9759\uff0c\u4f60\u90fd\u4e0d\u77e5\u89c2\u5bdf\u4eba\u7c7b\u6709\u591a\u6709\u8da3\uff0c\u5c24\u5176\u662f\u4ed6\u4eec\u4e0d\u77e5\u9053\u7684\u65f6\u5019\uff0c\u8fd9\u5c31\u662f\u65e5\u5e38\u3002\u6211\u51b3\u5b9a\u4e0b\u6b21\u8fd8\u8981\u5750\u5728\u89c6\u7ebf\u4e00\u767e\u516b\u5341\u5ea6\u5f00\u9614\u7684\u5ea7\u4f4d\u4e0a\uff0c\u8fd9\u624d\u662f\u5802\u5403\u7684\u610f\u4e49\u3002"},{"id":"\u5f80\u4e8b\u5e76\u4e0d\u5982\u70df","metadata":{"permalink":"/kilimanjaro/\u5f80\u4e8b\u5e76\u4e0d\u5982\u70df","editUrl":"https://github.com/jing-gu/kilimanjaro/blog/2019/2019-03-09-\u5f80\u4e8b\u5e76\u4e0d\u5982\u70df.md","source":"@site/blog/2019/2019-03-09-\u5f80\u4e8b\u5e76\u4e0d\u5982\u70df.md","title":"\u5f80\u4e8b\u5e76\u4e0d\u5982\u70df","description":"\u73b0\u5728\u7684\u6211\u4e0e\u5317\u4eac\u65f6\u95f4\u76f8\u5dee\u5341\u4e09\u5c0f\u65f6\uff0c\u4e0e\u4e1c\u4eac\u65f6\u95f4\u76f8\u5dee\u5341\u56db\u5c0f\u65f6\u3002\u6211\u53ea\u5bf9\u8fd9\u4e24\u4e2a\u65f6\u533a\u6709\u6240\u7275\u6302\uff0c\u56e0\u4e3a\u90a3\u91cc\u6709\u91cd\u8981\u7684\u4eba\u3002","date":"2019-03-09T00:00:00.000Z","tags":[{"inline":false,"label":"\u968f\u611f","permalink":"/kilimanjaro/tags/\u968f\u611f","description":"\u968f\u611f tag description"}],"readingTime":14.5,"hasTruncateMarker":false,"authors":[],"frontMatter":{"slug":"\u5f80\u4e8b\u5e76\u4e0d\u5982\u70df","title":"\u5f80\u4e8b\u5e76\u4e0d\u5982\u70df","tags":["\u968f\u611f"],"date":"2019-03-09T00:00:00.000Z"},"unlisted":false,"prevItem":{"title":"\u65e0\u5e38\u7686\u65e5\u5e38","permalink":"/kilimanjaro/\u65e0\u5e38\u7686\u65e5\u5e38"},"nextItem":{"title":"\u65e0\u51fa\u8def\u5496\u5561\u9986","permalink":"/kilimanjaro/\u65e0\u51fa\u8def\u5496\u5561\u9986"}},"content":"\u73b0\u5728\u7684\u6211\u4e0e\u5317\u4eac\u65f6\u95f4\u76f8\u5dee\u5341\u4e09\u5c0f\u65f6\uff0c\u4e0e\u4e1c\u4eac\u65f6\u95f4\u76f8\u5dee\u5341\u56db\u5c0f\u65f6\u3002\u6211\u53ea\u5bf9\u8fd9\u4e24\u4e2a\u65f6\u533a\u6709\u6240\u7275\u6302\uff0c\u56e0\u4e3a\u90a3\u91cc\u6709\u91cd\u8981\u7684\u4eba\u3002\\n\\n\u4e24\u4e09\u5468\u524d\u7684\u65e9\u4e0a\uff0c\u6211\u88ab\u4e00\u6761\u6d88\u606f\u53ee\u9192\u3002\u5927\u610f\u662f\u201c\u4f60\u7684\u5730\u5740\u662f\u4ec0\u4e48\uff0c\u5feb\u544a\u8bc9\u6211\u3002\u201d\\n\\n\u6211\u5c45\u7136\u4e00\u7741\u773c\u5c31\u770b\u5230\u4e00\u6761\u7948\u4f7f\u53e5\u3002\u5927\u8111\u6761\u4ef6\u53cd\u5c04\uff0c\u624b\u6307\u8fc5\u901f\u56de\u590d\uff0c\u7d27\u63a5\u7740\u6211\u53c8\u7761\u773c\u60fa\u5fea\u5730\u5012\u4e0b\u4e86\uff0c\u518d\u6b21\u8d77\u5e8a\u540e\u6211\u5e76\u6ca1\u6709\u8ffd\u95ee\u8fd9\u4e2a\u4e8b\u60c5\u7684\u7f18\u7531\u3002\u76f4\u5230\u51e0\u5929\u524d\u6211\u6536\u5230\u90ae\u5c40\u7684\u63d0\u793a\uff0c\u6709\u5305\u88f9\u5f85\u63d0\u53d6\u3002\u6211\u4e00\u60f3\u4fbf\u5fc3\u4e2d\u6709\u6570\uff0c\u5468\u56f4\u5982\u540c\u6380\u8d77\u4e00\u9635\u80dc\u5229\u7684\u72c2\u98ce\u3002\u8fd9\u6837\u5c31\u5bf9\u4e86\uff0c\u6211\u77e5\u9053\u5728\u6211\u8fc7\u751f\u65e5\u7684\u8fd9\u4e2a\u6708\u91cc\u7edd\u5bf9\u6709\u4e1c\u897f\u503c\u5f97\u671f\u5f85\uff0c\u4e0d\u7ba1\u6211\u4eec\u8ddd\u79bb\u6709\u591a\u8fdc\uff0c\u65f6\u5dee\u6709\u591a\u4e45\u3002\\n\\n\u4ece\u90ae\u5c40\u5e26\u56de\u5305\u88f9\uff0c\u6211\u62ff\u8d77\u526a\u5200\u88c1\u5f00\u7eb8\u7bb1\uff0c\u731c\u4e0d\u5230\u91cc\u9762\u662f\u4ec0\u4e48\uff0c\u7b2c\u4e00\u4e2a\u638f\u51fa\u6765\u7684\u662f\u4e00\u888b\u94dc\u9523\u70e7\uff0c\u518d\u5f80\u91cc\u9762\u4e00\u770b\u5c45\u7136\u4e00\u7bb1\u5168\u662f\u65e5\u672c\u96f6\u98df\u3002\u660e\u660e\u53ea\u53d1\u4e00\u53e5\u95ee\u5019\u6211\u4e5f\u5c31\u5f00\u5fc3\u4e86\uff0c\u4f46\u624b\u5199\u7684\u8d3a\u5361\u663e\u7136\u80dc\u8fc7\u4e00\u5207\u8868\u60c5\u5305\uff0c\u6211\u5076\u5c14\u8fd8\u662f\u4e2a\u6000\u65e7\u7684\u4eba\uff0c\u66f4\u522b\u63d0\u8fd9\u4e00\u7bb1\u90fd\u662f\u6211\u559c\u6b22\u7684\u3002\u660e\u660e\u53ea\u6bd4\u6211\u5927\u4e24\u5c81\uff0c\u771f\u628a\u6211\u5f53\u5b69\u5b50\u4e86\uff0c\u6211\u5374\u603b\u662f\u88ab\u65e0\u7406\u7531\u5a07\u60ef\u7684\u90a3\u4e00\u4e2a\u3002\\n\\n\u6211\u4e0eM\u7684\u65f6\u5dee\u662f14\u5c0f\u65f6\uff0c\u867d\u7136\u6211\u5f88\u60f3\u62a5\u544a\u5305\u88f9\u5df2\u6536\u5230\uff0c\u4f46\u8fd8\u662f\u51b3\u5b9a\u7b49\u5979\u65f6\u95f4\u7a0d\u665a\u65f6\u518d\u9a9a\u6270\u3002\u65f6\u5dee\u8fd9\u4e2a\u672c\u6ca1\u6709\u592a\u5927\u610f\u4e49\u7684\u6982\u5ff5\u56e0\u4e3a\u7275\u6302\u800c\u6709\u6240\u4e0d\u540c\u3002\u4e00\u76f4\u4ee5\u6765\u6211\u4eec\u7684\u5173\u7cfb\u5982\u540c\u540e\u5929\u4eb2\u4eba\uff0c\u6211\u80fd\u770b\u5f97\u8fdc\u611f\u609f\u591a\uff0c\u5f88\u5927\u7a0b\u5ea6\u4e0a\u662f\u56e0\u4e3a\u6211\u662f\u88ab\u5e26\u9886\u7684\u90a3\u4e00\u4e2a\uff0c\u88ab\u7167\u987e\u7684\u90a3\u4e00\u4e2a\u3002\\n\\n\u6211\u7b2c\u4e00\u6b21\u53bb\u540d\u53e4\u5c4b\u7684\u65f6\u5019\uff0cM\u8bf4\u8981\u5e26\u6211\u53bb\u5979\u5916\u5a46\u5bb6\u91cc\u3002\\n\\n\u201c\u6211\u53c8\u8981\u4f4f\u4f60\u7236\u6bcd\u5bb6\uff0c\u8fd8\u8981\u53bb\u770b\u5916\u5a46\uff0c\u600e\u4e48\u50cf\u88ab\u4f60\u5e26\u4e0a\u95e8\u7684\u5973\u5a7f\u3002\u201d\\n\\n\u201c...... \u6211\u5916\u5a46\u4f4f\u7684\u662f\u548c\u5f0f\u7684\u5c4b\u5b50\uff0c\u8fd9\u6837\u7684\u683c\u8c03\u5728\u57ce\u5e02\u91cc\u5f88\u5c11\u89c1\u4e86\uff0c\u6211\u6015\u4f60\u4ee5\u540e\u6ca1\u673a\u4f1a\u89c1\u5230\u3002\u201d\\n\\n\u4e8e\u662f\u6211\u5e26\u7740\u4e00\u80a1\u730e\u5947\u7684\u5fc3\u7406\u53bb\u62dc\u8bbf\u3002M\u5374\u8bf4\uff1a\u201c\u6211\u5916\u5a46\u5f88\u53e4\u602a\uff0c\u72ec\u6765\u72ec\u5f80\uff0c\u5bb6\u4eba\u90fd\u4e0d\u592a\u559c\u6b22\u5979\uff0c\u6211\u4e5f\u4e0d\u559c\u6b22\u3002\u201d\\n\\n\u6211\u5927\u5403\u4e00\u60ca\uff1a\u201c\u5440\uff0c\u90a3\u4f60\u8fd8\u5e26\u6211\u8fd9\u4e2a\u5916\u4eba\u6765\u5e72\u561b\uff1f\u201d\\n\\n\u201c\u6ca1\u4e8b\uff0c\u53c2\u89c2\u623f\u5b50\uff0c\u5979\u53ea\u662f\u5bf9\u5bb6\u4eba\u4e0d\u4eb2\u8fd1\uff0c\u53cd\u800c\u5bf9\u5916\u4eba\u5f88\u6709\u793c\u8c8c\u3002\u201d\\n\\n\u6211\u730e\u5947\u7684\u5fc3\u7406\u66f4\u4e0a\u4e00\u5c42\uff0c\u5916\u5a46\u8fd9\u4e2a\u89d2\u8272\u5728\u6211\u5370\u8c61\u4e2d\u4ece\u6765\u4e0d\u662f\u8fd9\u6837\u7684\u3002\u4e00\u8def\u4e0aM\u7ed9\u6211\u505a\u8db3\u4e86\u94fa\u57ab\uff0c\u7ed3\u679c\u6211\u6784\u601d\u4e86\u4e00\u4e2a\u51b7\u9762\u7280\u5229\u7684\u8001\u5a46\u5a46\u5f62\u8c61\uff0c\u6697\u81ea\u51b3\u5b9a\u4e00\u5207\u8a00\u884c\u4e3e\u6b62\u90fd\u8981\u8c28\u614e\u3002\\n\\n\u8111\u6d77\u4e2d\u6325\u4e4b\u4e0d\u53bb\u300a\u5343\u4e0e\u5343\u5bfb\u300b\u7684\u6c64\u5a46\u5a46\uff0c\u6211\u771f\u7684\u6bd4\u4e0a\u95e8\u5973\u5a7f\u8fd8\u8981\u7d27\u5f20\u3002\u8fce\u63a5\u6211\u4eec\u7684\u5374\u662f\u4e00\u4e2a\u6ee1\u5934\u767d\u53d1\u4f46\u7cbe\u795e\u723d\u5229\u7684\u8001\u4eba\u3002\\n\\n\u201c\u4f60\u5916\u5a46\u591a\u5927\u4e86\uff1f\u201d \u6211\u60f3\u6084\u6084\u786e\u8ba4\u773c\u524d\u7684\u7591\u60d1\u3002\\n\\n\u201c\u516b\u5341\u591a\u5c81\u4e86\u3002\u201d\\n\\n\u201c\u4e0d\u50cf\u5427\uff0c\u5979\u600e\u4e48\u611f\u89c9\u5316\u5986\u4e86\uff1f\u6211\u7684\u5929\uff01\u201d\\n\\n\u60ca\u559c\u63a5\u8e35\u800c\u81f3\uff0c\u9999\u5473\u56db\u6ea2\uff0c\u8981\u6709\u5927\u9910\u62db\u5f85\u3002\u4e00\u4e2a\u8001\u4eba\u7528\u8fd9\u4e48\u5927\u53a8\u623f\uff0c\u6211\u90fd\u6709\u4e9b\u7fa1\u6155\uff0c\u800c\u4e14\u5979\u4ec0\u4e48\u5de5\u5177\u90fd\u6709\uff0c\u6211\u4e00\u8fdb\u9910\u5385\u5c31\u770b\u5230\u684c\u4e0a\u7684\u5e73\u5e95\u7535\u9505\uff0c\u8fd9\u662f\u8981\u81ea\u5df1\u5728\u5bb6\u505a\u201c\u5927\u962a\u70e7\u201d\u7684\u8282\u594f\uff01\\n\\n\u5916\u5a46\u51c6\u5907\u7684\u98df\u7269\u4e4b\u591a\u8fdc\u8fdc\u8d85\u8fc7\u6211\u4eec\u7684\u5fc3\u7406\u548c\u751f\u7406\u7684\u53cc\u91cd\u627f\u53d7\u80fd\u529b\u3002\u4e00\u5f00\u59cb\u814c\u841d\u535c\u5403\u591a\u4e86\uff0c\u5473\u589e\u6c64\u4e00\u5927\u7897\uff0c\u4e00\u4eba\u7ed9\u70e4\u4e86\u4e24\u4e2a\u5927\u962a\u70e7\uff0c\u8fd8\u95ee\u6709\u6ca1\u6709\u5403\u9971\uff01\u53c8\u7ed9\u634f\u4e86\u597d\u51e0\u4e2a\u996d\u56e2\u3002\u6211\u4e0eM\u7684\u5bf9\u89c6\u4e2d\u662f\u5fc3\u9886\u795e\u4f1a\u7684\u4e92\u76f8\u5632\u8bbd\uff0c\u770b\u5427\uff0c\u5e73\u65f6\u534a\u7897\u996d\u90fd\u558a\u6491\u7684\u4eba\uff0c\u4e0d\u77e5\u8fd8\u85cf\u6709\u8fd9\u6837\u7684\u6d2a\u8352\u4e4b\u529b\u5427\uff0c\u8fd9\u4e00\u987f\u4f30\u8ba1\u662f\u628a\u4e00\u5468\u7684\u78b3\u6c34\u5316\u5408\u7269\u90fd\u5403\u591f\u4e86\u3002\\n\\n![Nagoya](./img/wangshi1.jpg)\\n\\n\u4e14\u4e0d\u8bf4\u6bcf\u4e2a\u4eba\u7684\u5916\u5a46\u4e2a\u6027\u6709\u591a\u4e0d\u540c\uff0c\u4f46\u5728\u5bf9\u513f\u5b59\u7684\u5403\u996d\u65b9\u9762\u90fd\u662f\u4e00\u6837\u7684\u5927\u516c\u65e0\u79c1\u3002\u5916\u5a46\u4eec\u8bf4\u201c\u5403\u554a\uff0c\u8fd8\u6709\u5f88\u591a\u201d\u662f\u5b9e\u8bdd\uff0c\u800c\u5b59\u5973\u4eec\u8bf4\u201c\u771f\u7684\u5403\u4e0d\u4e0b\u4e86\u201d\u4e5f\u662f\u5b9e\u8bdd\u3002\u534a\u63a8\u534a\u5c31\uff0c\u7ec8\u81f3\u6781\u9650\uff0c\u5916\u5a46\u5374\u95ee\u201c\u8fd8\u6709\u70b9\u5fc3\uff0c\u5403\u4e0d\u5403\uff1f\u201d M\u662f\u5403\u4e0d\u4e0b\uff0c\u6211\u662f\u653e\u4e0d\u4e0b\uff0c\u6211\u60f3\u5403\u53c8\u5403\u4e0d\u52a8\uff0c\u771f\u662f\u597d\u4f24\u5fc3\uff0c\u6068\u4e0d\u5f97\u5c11\u559d\u4e00\u7897\u6c64\uff0c\u591a\u957f\u4e00\u4e2a\u80c3\u3002\\n\\n\u8bf4\u5230\u672c\u6b21\u4e3b\u8981\u884c\u52a8\u662f\u53c2\u89c2\u623f\u5b50\uff0c\u4e8e\u662f\u6211\u628a\u4eba\u5bb6\u6bcf\u4e2a\u623f\u95f4\u90fd\u770b\u5728\u773c\u91cc\u3002\u623f\u95f4\u5168\u662f\u69bb\u69bb\u7c73\uff0c\u6728\u683c\u7a97\u4e0a\u7cca\u7684\u662f\u7eb8\uff0c\u5f88\u8f7b\uff0c\u4e0a\u4e0b\u4e00\u62c9\u53ef\u4ee5\u548c\u9662\u843d\u5f62\u6210\u9694\u65ad\u5374\u4f9d\u7136\u901a\u900f\uff0c\u679c\u7136\u597d\u4f20\u7edf\u3002\\n\\n![Nagoya](./img/wangshi2.jpg)\\n\\n\u4f46\u6709\u4e00\u4e2a\u7591\u60d1\u4ece\u6211\u4e00\u8fdb\u95e8\u5c31\u4ea7\u751f\u4e86\uff0c\u8fd9\u4e2a\u5bb6\u5927\u7684\u51fa\u5947\uff0c\u53ef\u4ee5\u4f4f\u4e00\u5bb6\u51e0\u53e3\uff0c\u5374\u53ea\u6709\u4e00\u4e2a\u8001\u4eba\u72ec\u5c45\u3002\\n\\n\u201c\u4e3a\u4ec0\u4e48\u4e0d\u4e00\u8d77\u4f4f\uff1f\u4f60\u4eec\u5bb6\u53ef\u6ca1\u8fd9\u6c14\u9b44\u5462\u3002\u201d \u6211\u751a\u81f3\u89c9\u5f97\u8fd9\u623f\u5b50\u4e0d\u62ff\u51fa\u6765\u5f53Airbnb\u540d\u5bbf\u79df\u51fa\u53bb\u90fd\u53ef\u60dc\u4e86\uff0c\u5730\u65b9\u5927\uff0c\u6709\u4e2a\u6027\uff0c\u95f9\u4e2d\u53d6\u9759\uff0c\u4e00\u665a\u623f\u79df\u5982\u4f55\u5982\u4f55\u3002\\n\\n\u201c\u56e0\u4e3a\u5916\u5a46\u53e4\u602a\u554a\u3002\u201d\\n\\n\u201c\u4f60\u5916\u5a46\u5230\u5e95\u54ea\u91cc\u602a\u4e86\uff1f\u201d \u5403\u996d\u65f6\u6211\u5e76\u6ca1\u6709\u89c9\u5f97\u773c\u524d\u7684\u5916\u5a46\u548c\u5b59\u5973\u6709\u660e\u663e\u7684\u9694\u9602\uff0c\u4e5f\u8bb8M\u8bf4\u7684\u6ca1\u9519\uff0c\u5916\u5a46\u5f85\u4eba\u63a5\u5ba2\u5f88\u6210\u529f\uff0c\u4ece\u5916\u4eba\u773c\u4e2d\u786e\u5b9e\u770b\u4e0d\u51fa\u4efb\u4f55\u4e0d\u534f\u8c03\uff0c\u4f46\u504f\u504f\u5916\u4eba\u770b\u6765\u7f8e\u6ee1\u7684\u4e1c\u897f\u53ea\u6709\u81ea\u5df1\u6e05\u695a\u54ea\u91cc\u522b\u626d\u3002\u80af\u5b9a\u6709\u6211\u77ed\u65f6\u95f4\u5185\u770b\u4e0d\u89c1\u7684\u4e1c\u897f\uff0c\u90a3\u5c31\u662f\u539f\u56e0\u3002\\n\\n\u201c\u5927\u6982\u662f\u751f\u6d3b\u5408\u4e0d\u6765\u5427\uff0c\u7238\u5988\u65e9\u5c31\u642c\u51fa\u6765\u4e86\uff0c\u5b81\u53ef\u81ea\u5df1\u4e70\u5c0f\u623f\u5b50\u4f4f\u3002\u5916\u5a46\u7684\u751f\u6d3b\u53ef\u6311\u5254\u4e86\uff0c\u6bcf\u5929\u65e9\u4e0a\u90fd\u53bb\u6d0b\u98df\u5c4b\u5403\u65e9\u9910\uff01\u201d \u6bcf\u5929\u65e9\u4e0a\uff1f\u8fd9\u4e2a\u5916\u5a46\u7684\u4eea\u5f0f\u611f\u5b9e\u5728\u662f\u592a\u5f3a\u5927\u4e86\uff0c\u665a\u8f88\u4e0d\u53ca\u3002\\n\\n\u201c\u90a3\u5979\u7684\u5f00\u9500\u5462\uff1f\u751f\u6d3b\u8d39\u4e4b\u7c7b\u7684\u3002\u201d \u6211\u5f88\u597d\u5947\u5979\u5982\u4f55\u8fd9\u822c\u81ea\u7531\uff0c\u56e0\u4e3a\u6211\u7684\u5916\u5a46\u662f\u4e2a\u82e6\u547d\u7684\u89d2\u8272\uff0c\u6c38\u8fdc\u90fd\u662f\u8003\u8651\u4ed6\u4eba\u5ffd\u7565\u81ea\u5df1\uff0c\u660e\u660e\u81ea\u5df1\u4e5f\u6ca1\u6709\uff0c\u4f46\u5c31\u662f\u786c\u6491\u4e5f\u603b\u60f3\u4f9b\u5e94\u513f\u5b59\u3002\u5265\u524a\u81ea\u5df1\u6210\u4e86\u5979\u5c81\u6708\u4e2d\u7684\u4e60\u60ef\u3002\\n\\n\u201c\u5979\u6709\u81ea\u5df1\u7684\u94b1\uff0c\u513f\u5b50\u4e0d\u6b62\u6211\u7238\u4e00\u4e2a\uff0c\u53ea\u662f\u8c01\u4e5f\u4e0d\u7ed9\u7f62\u4e86\u3002\u4f46\u662f\u8fd9\u6837\u4e5f\u597d\uff0c\u5927\u5bb6\u77e5\u9053\u5979\u81ea\u5df1\u8fc7\u7684\u81ea\u8db3\u53cd\u800c\u5b89\u5fc3\u3002\u201d \u6211\u604d\u7136\u5927\u609f\uff0c\u96be\u602a\u5bb6\u4eba\u4e0d\u5f85\u89c1\uff0c\u56e0\u4e3a\u8fd9\u4e2a\u5916\u5a46\u4e0d\u201c\u5949\u732e\u201d\u554a\u3002\\n\\n\u8f6c\u800c\u4e00\u60f3\u53c8\u597d\u5fc3\u9178\uff0c\u539f\u6765\u8001\u4eba\u81ea\u5df1\u53ef\u4ee5\u8fc7\u7684\u5f88\u597d\uff0c\u5230\u5e95\u662f\u8c01\u5728\u62d6\u8c01\u540e\u817f\uff1f\u4e0b\u4e00\u4ee3\u5982\u679c\u4e0d\u80fd\u96c6\u4f53\u627f\u62c5\u8d61\u517b\u8001\u4eba\u7684\u8d23\u4efb\uff0c\u4e0d\u5982\u4e0d\u8981\u89ca\u89ce\u8001\u4eba\u7684\u8d22\u4ea7\uff0c\u6700\u516c\u5e73\u7684\u505a\u6cd5\u5c31\u662f\u8c01\u4e5f\u5f97\u4e0d\u5230\uff0c\u7ed9\u8001\u4eba\u81ea\u6211\u652f\u914d\u7684\u6743\u529b\u548c\u81ea\u7531\u3002\u663e\u7136\uff0c\u8fd9\u6837\u7f3a\u5c11\u4e86\u4e00\u4e9b\u5929\u4f26\u4e4b\u4e50\uff0c\u4f46\u4e0d\u540c\u793e\u4f1a\u6709\u81ea\u5df1\u7684\u8fd0\u4f5c\u65b9\u5f0f\uff0c\u65e5\u672c\u662f\u4e2a\u8001\u9f84\u5316\u4e25\u91cd\u7684\u56fd\u5bb6\uff0c\u8001\u4eba\u5f85\u9047\u81ea\u7136\u5dee\u4e0d\u4e86\uff0c\u4f46\u5e74\u8f7b\u4eba\u7a0e\u52a1\u5219\u66f4\u91cd\uff0c\u53ef\u662f\u4e0e\u5176\u7ea0\u7eb7\u5404\u5bb6\u7684\u8d61\u517b\u8d23\u4efb\uff0c\u4e0d\u5982\u5927\u5bb6\u7684\u8001\u4eba\u5927\u5bb6\u517b\u3002\\n\\n![Nagoya](./img/wangshi3.jpg)\\n\\n\u6211\u4eec\u5c31\u90a3\u6837\u5750\u5728\u4e00\u95f4\u548c\u5ba4\u91cc\u804a\u623f\u5b50\u80cc\u540e\u7684\u6545\u4e8b\uff0c\u5916\u5a46\u63a8\u95e8\uff0c\u5e26\u6765\u751c\u70b9\u548c\u7eff\u8336\uff0c\u521a\u624d\u5403\u4e0d\u4e0b\u7684\u548c\u83d3\u5b50\u7ec8\u4e8e\u8fd8\u662f\u88ab\u6211\u76fc\u5230\u4e86\u3002\u4e0d\u4e00\u4f1a\u513f\uff0c\u5916\u5a46\u81ea\u544a\u594b\u52c7\u8981\u7ed9\u6211\u4eec\u62cd\u7167\uff0c\u4f46\u600e\u4e48\u4e5f\u6446\u5f04\u4e0d\u4e86\u81ea\u5df1\u7684\u624b\u673a\u3002\u524d\u540e\u51c6\u5907\u4e86\u5feb\u5341\u6b21\uff0c\u4e0d\u662f\u62cd\u5230\u684c\u5b50\u5c31\u662f\u624b\u6296\uff0c\u6211\u5df2\u7ecf\u8138\u90fd\u7b11\u50f5\u4e86\uff0c\u7b49\u5916\u5a46\u64cd\u7ec3\u5b8c\u6bd5\uff0c\u90a3\u50f5\u786c\u7684\u7167\u7247\u4f30\u8ba1\u4e5f\u662f\u4e0d\u80fd\u770b\u3002\\n\\n\u201c\u54a6\uff0c\u6211\u600e\u4e48\u4ec0\u4e48\u4e5f\u770b\u4e0d\u89c1\u5462\uff1f\u201d\\n\\n\u201c\u963f\u5a46\u554a\uff0c\u4f60\u81ea\u5df1\u624b\u6307\u6321\u4f4f\u955c\u5934\u4e86\u3002\u201d M\u56de\u7b54\u4e4b\u98de\u901f\u5982\u540c\u65e9\u5df2\u9884\u77e5\u4e00\u822c\u51c6\u786e\u3002\u6211\u60f3\u5979\u4e0d\u7ba1\u591a\u4e48\u7279\u7acb\u72ec\u884c\uff0c\u5979\u7ec8\u7a76\u8fd8\u662f\u4e2a\u8001\u4eba\u3002\u8001\u4eba\u7684\u56fa\u6267\uff0c\u8001\u4eba\u7684\u53ef\u7231\uff0c\u5979\u5bf9\u81ea\u5df1\u6a21\u7cca\u7684\u4f5c\u54c1\u76f8\u5f53\u6ee1\u610f\u3002\\n\\n\u56de\u53bb\u7684\u8def\u4e0a\uff0c\u56e0\u4e3a\u5403\u7684\u592a\u9971\uff0c\u6240\u4ee5\u53ea\u80fd\u6563\u6b65\uff0c\u6211\u4eec\u4e00\u8def\u63a5\u7740\u8bf4\u8fd9\u4e2a\u5916\u5a46\u7684\u5947\u8469\u3002\\n\\n\u6211\u8bf4\uff1a\u201c\u5916\u5a46\u4f1a\u628a\u6211\u4eec\u7684\u7167\u7247\u53d1\u8fc7\u6765\u5427\u3002\u201d\\n\\nM\u8bf4\uff1a \u201c\u600e\u4e48\u53ef\u80fd\uff0c\u5979\u8fde\u624b\u673a\u90fd\u4e0d\u592a\u4f1a\u7528\uff0c\u4eca\u5929\u7834\u5929\u8352\u62cd\u7167\uff0c\u6211\u4e5f\u662f\u5934\u4e00\u56de\u89c1\u3002\u521a\u624d\u6ca1\u8981\u4e5f\u5c31\u7b97\u4e86\uff0c\u518d\u8981\u4f30\u8ba1\u5c31\u5f97\u6211\u81ea\u5df1\u6765\u53d6\uff0c\u4f46\u6211\u4e0d\u60f3\u518d\u6765\u3002\u201d\\n\\n\u201c\u55ef\uff0c\u6211\u61c2\uff0c\u4f60\u4e0d\u559c\u6b22\u5979\u3002\u201d\\n\\n\u201c\u54e6\uff0c\u6211\u90fd\u5fd8\u4e86\u8bf4\uff0c\u4e3a\u4e86\u5e26\u4f60\u6765\uff0c\u6211\u53ef\u662f\u8981\u63d0\u524d\u4e00\u5468\u548c\u5916\u5a46\u9884\u7ea6\u5462\u3002\u201d\\n\\n\u201c\u9884\u7ea6\u4ec0\u4e48\u554a\uff1f\u201d \u6211\u4ee5\u4e3a\u81ea\u4e2a\u513f\u662fVIP\uff0c\u4e0d\u81f3\u4e8e\u5427\u3002\\n\\n\u201c\u65f6\u95f4\u5450\uff0c\u5979\u53ef\u662f\u5f88\u5fd9\u7684\uff0c\u5979\u4e5f\u6709\u81ea\u5df1\u7684\u8001\u59ca\u59b9\u554a\uff0c\u6ca1\u4e8b\u53bb\u559d\u8336\uff0c\u8fd8\u603b\u662f\u53bb\u901b\u540d\u53e4\u5c4b\u6700\u597d\u7684\u5546\u573a\u3002\u4f60\u770b\uff0c\u4ec0\u4e48\u4e8b\u90fd\u6709\u53ef\u80fd\u53d1\u751f\uff0c\u5c31\u662f\u4e0d\u4e00\u5b9a\u4f1a\u5728\u5bb6\u3002\u201d\\n\\n\u6211\u7adf\u65e0\u8a00\u4ee5\u5bf9\uff0c\u4e0d\u7981\u5bf9\u8fd9\u4e2a\u81ea\u7acb\u81ea\u5f3a\u4e0d\u6d3b\u5728\u5b50\u5973\u773c\u4e2d\u7684\u8001\u4eba\u518d\u6b21\u522e\u76ee\u76f8\u770b\uff0c\u4e5f\u8bb8\u522b\u4eba\u6709\u610f\u89c1\uff0c\u4f46\u5979\u81ea\u5df1\u4e00\u5b9a\u8fc7\u5f97\u5f88\u8212\u670d\u3002\u4f46\u8fd9\u4e5f\u6ca1\u9519\uff0c\u90a3\u4e2a\u793e\u4f1a\u7684\u51c6\u5219\u53ea\u8981\u4e0d\u59a8\u788d\u4ed6\u4eba\u5c31\u662f\u6b63\u786e\u7684\uff0c\u662f\u597d\u662f\u6b79\uff0c\u53cd\u6b63\u522b\u4eba\u603b\u6709\u610f\u89c1\uff0c\u4f46\u81f3\u5c11\u8fd9\u6837\u5979\u4f1a\u66f4\u559c\u6b22\u5979\u81ea\u5df1\u3002\\n\\n\u6211\u5b9e\u5728\u7981\u4e0d\u4f4f\u628a\u6211\u4eec\u7684\u5916\u5a46\u5bf9\u6bd4\uff0c\u56e0\u4e3a\u5dee\u522b\u5b9e\u5728\u592a\u5927\u4e86\u3002\u65e0\u8a00\u4ee5\u5bf9\u7684\u90a3\u4e00\u77ac\u95f4\uff0c\u6211\u8111\u5b50\u91cc\u53ea\u76d8\u65cb\u7740\u4e00\u4e2a\u5ff5\u5934\uff1a\u6211\u7684\u5916\u5a46\u554a\uff0c\u6211\u7684\u5916\u5a46\u554a\uff0c\u6211\u591a\u5e0c\u671b\u4f60\u4e5f\u81ea\u79c1\u4e00\u70b9\uff0c\u518d\u81ea\u79c1\u4e00\u70b9\u3002\\n\\n\u201c\u5979\u8981\u6211\u7cbe\u786e\u5230\u51e0\u70b9\uff0c\u624d\u597d\u63d0\u524d\u51c6\u5907\u98df\u7269\u3002\u5509\u600e\u4e48\u5c31\u662f\u4e0d\u559c\u6b22\u5979\u5462\uff0c\u6211\u7b2c\u4e00\u559c\u6b22\u5988\u5988\uff0c\u7b2c\u4e8c\u559c\u6b22\u4f60\u3002\u201d \u6211\u534a\u664c\u8bf4\u4e0d\u51fa\u8bdd\uff0c\u88ab\u5f53\u6210\u4eb2\u4eba\u7684\u611f\u89c9\u771f\u597d\uff0c\u4f46\u5979\u4e0d\u77e5\u9053\u6211\u5176\u5b9e\u5fc3\u751f\u7fa1\u6155\u3002\u4e0d\u7ba1\u8fd9\u4e2a\u5916\u5a46\u5947\u8469\u4e5f\u7f62\uff0c\u53e4\u602a\u4e5f\u7f62\uff0c\u559c\u4e0d\u559c\u6b22\u90fd\u65e0\u6240\u8c13\uff0c\u5979\u8fd8\u662f\u5728\u90a3\u91cc\u7684\u3002\u5982\u679c\u53ef\u4ee5\uff0c\u6211\u4e5f\u60f3\u9884\u7ea6\uff0c\u53ef\u6211\u600e\u4e48\u9884\u7ea6\u6211\u7684\u5916\u5a46\uff1f\u5929\u5802\u662f\u5426\u63a5\u53d7\u9884\u7ea6\u70ed\u7ebf\uff1f\\n\\n\u5916\u5a46\u5df2\u7ecf\u8fc7\u4e16\u3002\\n\\n\u6211\u6ca1\u6709\u770b\u5230\u5979\u6700\u540e\u4e00\u9762\uff0c\u6240\u4ee5\u4e00\u70b9\u90fd\u4e0d\u771f\u5b9e\uff0c\u53ea\u662f\u50cf\u9762\u5bf9\u8003\u8bd5\u90a3\u6837\u63a5\u53d7\u4e86\u8fd9\u4e2a\u94c1\u4e00\u822c\u7684\u4e8b\u5b9e\u3002\u5076\u5c14\u56de\u5bb6\u65f6\uff0c\u53d1\u73b0\u4e00\u4e2a\u4eba\u5c31\u8fd9\u4e48\u7a81\u7136\u4e0d\u89c1\u4e86\uff0c\u4f46\u6211\u8fd8\u662f\u96be\u4ee5\u60f3\u8c61\uff0c\u56e0\u4e3a\u5979\u81f3\u4eca\u7559\u7ed9\u6211\u7684\u97f3\u5bb9\u7b11\u8c8c\u8fd8\u662f\u9887\u4e3a\u5065\u5eb7\u7684\u8eab\u59ff\uff0c\u8c01\u90fd\u6ca1\u6709\u60f3\u5230\u5979\u4f1a\u7a81\u7136\u79bb\u5f00\u3002\\n\\n\u6211\u4e0d\u523b\u610f\u611f\u4f24\u6000\u65e7\uff0c\u603b\u4ee5\u4e3a\u5f80\u4e8b\u5982\u70df\u98d8\u6563\uff0c\u5f80\u4e8b\u5374\u5728\u4e0d\u7ecf\u610f\u95f4\u523a\u75db\u6211\u5fc3\u3002\u524d\u5e74\u5728\u6df1\u5733\u5f53\u4e86\u4e00\u6bb5\u65f6\u95f4\u7684\u52a8\u6f2b\u8001\u5e08\uff0c\u67d0\u5929\u6709\u4eba\u7ed9\u96c6\u4f53\u70b9\u4e86\u4e00\u6279\u5c0f\u9984\u9968\u7684\u5916\u5356\u3002\u5608\u6742\u4e2d\u5927\u5bb6\u5403\u7684\u70ed\u706b\u671d\u5929\uff0c\u6211\u7a81\u7136\u8fb9\u5403\u8fb9\u4f24\u5fc3\uff0c\u5c0f\u9984\u9968\u662f\u5916\u5a46\u5bf9\u6211\u7684\u7279\u4f8b\u3002\u6211\u4e00\u76f4\u8ba8\u538c\u732a\u8089\uff0c\u4f46\u5c0f\u9984\u9968\u7684\u80e1\u6912\u5473\u91cd\uff0c\u7ed3\u679c\u9c9c\u5473\u76d6\u8fc7\u4e86\u732a\u5473\u3002\u90a3\u65f6\u8001\u5bb6\u6ca1\u4ec0\u4e48\u6211\u7231\u5403\u7684\uff0c\u5916\u5a46\u603b\u53bb\u4e70\u9984\u9968\uff0c\u4e70\u4e00\u9505\u719f\u7684\uff0c\u62ce\u4e00\u888b\u751f\u7684\uff0c\u8fde\u5356\u9984\u9968\u7684\u4eba\u90fd\u77e5\u9053\u90a3\u662f\u7ed9\u5979\u5b59\u5973\u51c6\u5907\u7684\u3002\\n\\n\u6211\u4ece\u6765\u4e0d\u77e5\u7779\u7269\u601d\u4eba\u7adf\u6709\u5982\u6b64\u5f3a\u5927\u7684\u5a01\u529b\uff0c\u6211\u5374\u518d\u4e5f\u4e0d\u5403\u5c0f\u9984\u9968\u4e86\u3002\\n\\n\u6211\u751a\u81f3\u4e0d\u60f3\u770b\u5230\u90a3\u79cd\u8001\u5f0f\u7684\u94a2\u7cbe\u9505\u5b50\uff0c\u56e0\u4e3a\u5916\u5a46\u603b\u7528\u90a3\u540c\u4e00\u53ea\u9505\u53bb\u88c5\u9984\u9968\u3002\u603b\u4ee5\u4e3a\u5f80\u4e8b\u5982\u70df\u98d8\u6563\uff0c\u5f80\u4e8b\u5374\u65e5\u4e45\u5f25\u65b0\uff0c\u9505\u5b50\u4e24\u7aef\u9ed1\u8272\u7684\u628a\u624b\u677e\u52a8\u65e0\u6bd4\uff0c\u624b\u6307\u4e00\u62e8\u5c31\u5495\u565c\u565c\u7684\u76f4\u8f6c\u3002\\n\\n\u6211\u8bb0\u5fc6\u4e2d\u4ec0\u4e48\u65f6\u5019\u523b\u610f\u4fdd\u7559\u90a3\u53ea\u5751\u5751\u6d3c\u6d3c\u7684\u65e7\u9505\u4e86\uff1f\\n\\n\u5f80\u4e8b\u5e76\u4e0d\u5982\u70df\u3002"},{"id":"\u65e0\u51fa\u8def\u5496\u5561\u9986","metadata":{"permalink":"/kilimanjaro/\u65e0\u51fa\u8def\u5496\u5561\u9986","editUrl":"https://github.com/jing-gu/kilimanjaro/blog/2019/2019-01-18-\u65e0\u51fa\u8def\u5496\u5561\u9986.md","source":"@site/blog/2019/2019-01-18-\u65e0\u51fa\u8def\u5496\u5561\u9986.md","title":"\u65e0\u51fa\u8def\u5496\u5561\u9986","description":"Mtl","date":"2019-01-18T00:00:00.000Z","tags":[{"inline":false,"label":"\u968f\u611f","permalink":"/kilimanjaro/tags/\u968f\u611f","description":"\u968f\u611f tag description"},{"inline":true,"label":"\u8499\u7279\u5229\u5c14","permalink":"/kilimanjaro/tags/\u8499\u7279\u5229\u5c14"}],"readingTime":17.38,"hasTruncateMarker":false,"authors":[],"frontMatter":{"slug":"\u65e0\u51fa\u8def\u5496\u5561\u9986","title":"\u65e0\u51fa\u8def\u5496\u5561\u9986","tags":["\u968f\u611f","\u8499\u7279\u5229\u5c14"],"date":"2019-01-18T00:00:00.000Z"},"unlisted":false,"prevItem":{"title":"\u5f80\u4e8b\u5e76\u4e0d\u5982\u70df","permalink":"/kilimanjaro/\u5f80\u4e8b\u5e76\u4e0d\u5982\u70df"},"nextItem":{"title":"\u4e00\u57ce\u4e00\u5473\uff0c\u4e00\u671f\u4e00\u4f1a","permalink":"/kilimanjaro/\u4e00\u57ce\u4e00\u5473\u4e00\u671f\u4e00\u4f1a"}},"content":"![Mtl](./img/cafe1.jpg)\\n\\n\u6211\u6240\u89c1\u5230\u7684\u6bcf\u4e2a\u4eba\uff0c\u5728\u51e0\u53e5\u5bd2\u6684\u4e4b\u540e\u90fd\u4f1a\u95ee\u6211\u8fd9\u4e2a\u95ee\u9898 \u201cSo \u4f60\u89c9\u5f97\u8fd9\u513f\u600e\u4e48\u6837\uff1f\u201d\\n\\n\u201c\u5f88\u597d\uff0c\u4e5f\u5f88\u51b7\u3002\u201d \u5bf9\u65b9\u77ac\u95f4\u7b11\u6210\u4e00\u6735\u82b1\uff0c\u8868\u793a\u8d5e\u540c\uff0c\u8fde\u53cd\u5e94\u90fd\u662f\u4e00\u6837\u7684\u3002\u6211\u8bd5\u7740\u5bf9\u4e0d\u540c\u7684\u4eba\u8bf4\u540c\u6837\u7684\u7b54\u6848\uff0c\u6536\u83b7\u7684\u90fd\u662f\u4e00\u6837\u7684\u54c8\u54c8\u5927\u7b11\u3002\\n\\n\u4ece\u5929\u6c14\u627e\u8bdd\u832c\u771f\u662f\u767e\u53d1\u767e\u4e2d\uff0c\u56e0\u4e3a\u8fd9\u4e00\u70b9\u786e\u5b9e\u8fbe\u6210\u5171\u8bc6\u3002\u8d77\u521d\u6211\u4e0d\u8fc7\u6709\u611f\u800c\u53d1\uff0c\u9053\u8def\u79ef\u96ea\u672a\u5316\uff0c\u5929\u53c8\u98d8\u7740\u5927\u96ea\uff0c\u9b41\u5317\u514b\u5929\u51b7\u662f\u65e0\u53ef\u53cd\u9a73\u7684\u4e8b\u5b9e\u3002\u5927\u6982\u5728\u6625\u5929\u6765\u4e34\u4e4b\u524d\uff0c\u6211\u90fd\u672a\u5fc5\u80fd\u60f3\u51fa\u4e00\u4e2a\u66f4\u6709\u521b\u610f\u7684\u7b54\u6848\u3002\\n\\n## 1\\n\\n\u96ea\u82b1\u5e38\u5e38\u4e0d\u8bf7\u81ea\u6765\u3002\u6211\u770b\u51c6\u4e86\u7a97\u5916\u65e0\u96ea\uff0c\u4e8e\u662f\u6362\u597d\u8863\u670d\u8e0f\u51fa\u5bb6\u95e8\uff0c\u8fce\u9762\u800c\u6765\u7684\u5374\u662f\u901f\u5ea6\u6bd4\u6211\u66f4\u5feb\u7684\u98de\u96ea\u3002\u4e0b\u96ea\u672c\u8eab\u5e76\u4e0d\u8ba8\u538c\uff0c\u5e72\u96ea\u98d8\u7684\u50cf\u7eb8\u7247\uff0c\u5374\u6ca1\u6709\u4ec0\u4e48\u6740\u4f24\u529b\u3002\u6211\u51fa\u95e8\u65f6\u4fe1\u8a93\u65e6\u65e6\u5730\u51b3\u5b9a\u53bb\u4e70\u4f1e\uff0c\u5230\u4e86\u8d85\u5e02\u95e8\u53e3\u53cd\u800c\u89c9\u5f97\u8fd9\u4e00\u8def\u8d70\u7684\u633a\u597d\uff0c\u96ea\u82b1\u6ca1\u6709\u6253\u6e7f\u5916\u5957\uff0c\u6211\u4e5f\u5e76\u6ca1\u6709\u51bb\u6210\u72d7\u3002\u4e1c\u6311\u897f\u9009\u4e86\u4e00\u5806\uff0c\u4ec0\u4e48\u90fd\u4e70\u4e86\uff0c\u5c31\u662f\u6ca1\u4e70\u4f1e\u3002\\n\\n\u53cd\u6b63\u6bcf\u5929\u90fd\u662f\u96f6\u4e0b\uff0c\u8fde\u5929\u7a7a\u90fd\u5931\u53bb\u4e86\u4e0b\u96e8\u7684\u529f\u80fd\uff0c\u4f1e\u8fd9\u56de\u4e8b\u5c31\u7ed9\u5fd8\u4e86\u3002\u5982\u679c\u96ea\u8d8a\u6765\u8d8a\u731b\u7684\u8bdd\uff0c\u76f4\u63a5\u8eb2\u8fdb\u8def\u8fb9\u7684\u5c0f\u5e97\u5c31\u884c\uff0c\u5f88\u5feb\u4e5f\u5c31\u6563\u4e86\u3002\\n\\n\u67d0\u4e00\u65e5\uff0c\u6211\u5c31\u8fd9\u4e48\u8eb2\u8fdb\u4e86\u4e00\u95f4\u7279\u522b\u597d\u559d\u7684\u5496\u5561\u5c4b\u3002\u5728\u4e0b\u96ea\u5929\uff0c\u597d\u50cf\u55c5\u89c9\u90fd\u53d8\u7075\u654f\u4e86\uff0c\u5b83\u660e\u660e\u95e8\u7a97\u7d27\u95ed\uff0c\u9999\u6c14\u5374\u4eff\u4f5b\u4ece\u610f\u8bc6\u8fdb\u5165\u6211\u7684\u8eab\u4f53\u3002MYRIADE\u5496\u5561\u5c4b\u7684\u9762\u79ef\u5b9e\u5728\u6709\u9650\uff0c\u6211\u7784\u4e2d\u4e86\u9760\u5899\u7684\u4e00\u5f20\u5c0f\u684c\uff0c\u51e0\u4e4e\u6ca1\u6709\u8fc7\u9053\u53ef\u8a00\uff0c\u4f46\u8fd8\u662f\u5bb9\u5f97\u4e0b\u6211\u628a\u81ea\u5df1\u585e\u8fdb\u53bb\u3002\\n\\n![MYRIADE cafe](./img/cafe2.jpg)\\n\\n\u4eba\u5747\u7a7a\u95f4\u5df2\u7ecf\u5c0f\u7684\u5269\u4e0b\u534a\u5f20\u684c\u5b50\u4e86\uff0c\u8fd8\u662f\u6709\u4eba\u4e0d\u65ad\u63a8\u95e8\u3002\u662f\u548c\u6211\u4e00\u6837\u6765\u8eb2\u907f\u98ce\u96ea\u7684\u5417\uff1f\u4e0d\uff0c\u5496\u5561\u662f\u771f\u7684\u597d\u559d\uff0c\u72ed\u5c0f\u7684\u7a7a\u95f4\u53cd\u800c\u8ba9\u9999\u5473\u66f4\u52a0\u6d53\u7f29\u3002\\n\\n\u6709\u4eba\u867d\u7136\u70b9\u4e86\u5916\u5e26\u7684\u676f\u5b50\uff0c\u4f46\u8fd8\u662f\u7ad9\u5728\u90a3\u91cc\u78e8\u78e8\u8e6d\u8e6d\u7684\u653e\u7cd6\u3001\u6405\u62cc\u3001\u52a0\u5976\uff0c\u7b49\u7740\u54ea\u91cc\u6709\u7a7a\u5ea7\u817e\u51fa\u6765\u3002\u6211\u5b58\u5fc3\u5750\u8fd9\u513f\u53d6\u6696\uff0c\u53c8\u6015\u8868\u73b0\u5f97\u5f88\u4e0d\u539a\u9053\uff0c\u7279\u522b\u60f3\u624b\u5934\u6709\u4e8b\u53ef\u505a\u3002\u7535\u8111\u53ef\u4ee5\u88c5\u88c5\u6837\u5b50\uff0c\u53ef\u662f\u7740\u6025\u7684\u4efb\u52a1\u90fd\u88ab\u6211\u7740\u6025\u5730\u505a\u5b8c\u4e86\u3002\u552f\u6709\u6587\u7ae0\u5c82\u6709\u5199\u5230\u5934\u7684\u9053\u7406\uff1f\u4e8e\u662f\u6211\u628a\u5496\u5561\u676f\u4e00\u6a2a\uff1a\\n\\n\u6211\u5728\u7801\u5b57\uff01\uff08\u5176\u5b9e\u8fde\u5934\u7eea\u90fd\u8fd8\u6ca1\u6709\uff09\\n\\n\u6211\u5728\u8d76\u65f6\u95f4\uff01\uff08\u5176\u5b9e\u5e76\u4e0d\u5fd9\uff09\\n\\n\u522b\u60f3\u76ef\u6211\u7684\u5ea7\u4f4d\uff01\uff08\u5176\u5b9e\u6211\u5fc3\u91cc\u662f\u5584\u826f\u7684\uff0c\u518d\u8ba9\u6211\u5750\u70ed\u4e00\u4f1a\u513f\u5c31\u79bb\u5f00\uff09\\n\\n![MYRIADE cafe](./img/cafe3.jpg)\\n\\n\u5c31\u5728\u6211\u96c6\u4e2d\u6ce8\u610f\u529b\u7684\u65f6\u5019\uff0c\u4e00\u4e2a\u58f0\u97f3\u6253\u65ad\u4e86\u6211\u3002\u201c\u4f60\u597d\uff0c\u4f60\u4ecb\u610f\u6211\u5750\u5728\u4f60\u5bf9\u9762\u5417\uff1f\u201d\\n\\n\u6211\u731b\u4e00\u62ac\u5934\uff0c\u539f\u6765\u6211\u811a\u524d\u8fd8\u6709\u4e00\u4e2a\u6905\u5b50\uff0c\u4f46\u56e0\u4e3a\u5de6\u8fb9\u9760\u5899\u540e\u62b5\u67dc\u53f0\u7684\u539f\u56e0\uff0c\u6839\u672c\u62c9\u4e0d\u5f00\u554a\u3002\u5c45\u7136\u8fd8\u6709\u6bd4\u6211\u66f4\u80fd\u6324\u7684\u4eba\uff01\u8981\u548c\u6211\u5206\u4eab\u8fd9\u7247\u5df4\u638c\u5927\u7684\u5c0f\u5706\u684c\u3002\\n\\n\u201c\u597d\u554a\u3002\u201d\uff08\u6211\u8fd8\u80fd\u8bf4\u4ec0\u4e48\uff09\u201c\u90a3\u6211\u628a\u684c\u5b50\u5f80\u6211\u8fd9\u91cc\u62c9\u4e00\u4e9b\u5427\uff0c\u4f60\u5c31\u597d\u5750\u4e86\u3002\u201d \u8fd9\u4e0b\u5b50\uff0c\u684c\u5b50\u5f7b\u5e95\u628a\u6211\u9876\u4f4f\u4e86\uff0c\u6211\u6177\u6168\u5730\u7ed9\u5979\u6324\u51fa\u4e86\u534a\u6761\u817f\u7684\u8ddd\u79bb\u3002\\n\\n\u201c\u554a\uff0c\u592a\u8c22\u8c22\u4f60\u4e86\u3002\u201d \u8bf4\u5b8c\u5979\u5c45\u7136\u62ff\u51fa\u4e86\u7535\u8111\uff01\u6211\u4eec\u684c\u4e0b\u811a\u6324\u811a\uff0c\u684c\u9762\u4e0a\u7535\u8111\u8fd8\u8981\u80cc\u9760\u80cc\uff0c\u50cf\u4e24\u4e2a\u4e89\u5206\u593a\u79d2\u7684\u5b87\u5b99\u201c\u5927\u5fd9\u4eba\u201d\u3002\u5728\u5979\u7684\u63a9\u62a4\u4e0b\uff0c\u6211\u611f\u89c9\u8e0f\u5b9e\u4e86\u4e0d\u5c11\uff0c\u4f60\u8bf4\u8c01\u8fd8\u597d\u610f\u601d\u6253\u8fd9\u4e24\u4e2a\u4eba\u5ea7\u4f4d\u7684\u4e3b\u610f\uff1f\u4e8e\u662f\u6211\u5b89\u5168\u5199\u4f5c\uff0c\u672c\u7bc7\u5c31\u662f\u8fd9\u4e48\u5728\u7578\u5f62\u7684\u5fc3\u7406\u6597\u4e89\u4e2d\u8bde\u751f\u7684\u3002\\n\\n\u5496\u5561\u51b7\u4e86\uff0c\u96ea\u4e0d\u89c1\u5c0f\u3002\u6211\u7684\u676f\u5b50\u91cc\u6bcf\u6b21\u90fd\u6545\u610f\u5269\u4e0b\u6700\u540e\u4e00\u53e3\uff0c\u559d\u4e2a\u7cbe\u5149\u8fd8\u4e0d\u8d70\u4eba\u5c31\u592a\u5c34\u5c2c\u4e86\u3002\\n\\n![Mtl](./img/cafe4.jpg)\\n\\n## 2\\n\\n\u4e0b\u96ea\u672c\u8eab\u5e76\u4e0d\u8ba8\u538c\uff0c\u4f46\u96ea\u540e\u4e00\u5bbf\u7684\u5730\u9762\u5374\u5f88\u5371\u9669\u3002\u51bb\u96ea\u5728\u4e2a\u522b\u8def\u6bb5\u7279\u522b\u6ed1\uff0c\u8499\u7279\u5229\u5c14\u51ac\u5929\u7684\u533b\u9662\u6bcf\u5929\u90fd\u4f1a\u6536\u5230\u8dcc\u6253\u635f\u4f24\u7684\u75c5\u53f7\uff0c\u591a\u5219\u51e0\u767e\u4eba\uff0c\u5168\u90e8\u90fd\u662f\u96ea\u5730\u6ed1\u5012\u3002\u542c\u5230\u8fd9\u6837\u7684\u65b0\u95fb\u540e\uff0c\u6211\u5c3d\u91cf\u6cbf\u7740\u88ab\u8e29\u51fa\u5f88\u591a\u811a\u5370\u7684\u75d5\u8ff9\u524d\u8fdb\uff0c\u90a3\u90fd\u662f\u88ab\u7fa4\u4f17\u4eec\u9a8c\u8bc1\u8fc7\u7684\u5b89\u5168\u901a\u9053\u3002\\n\\n\u7ec8\u4e8e\u6709\u4e00\u5929\uff0c\u6211\u7684\u5fc5\u7ecf\u4e4b\u8def\u88ab\u7ea2\u8272\u8b66\u6212\u7ebf\u56f4\u4f4f\u4e86\uff0c\u7ea2\u7ebf\u4e0a\u662f\u8fde\u7eed\u91cd\u590d\u7684\u9ed1\u8272\u5355\u8bcddanger\u3002\u6211\u4e00\u9635\u5fc3\u60ca\uff0c\u80af\u5b9a\u662f\u6709\u4eba\u6454\u5f97\u4e0d\u8f7b\u624d\u62a5\u4e86\u8b66\u3002\u800c\u6211\u4ee5\u4e3a\u5f88\u5b89\u5168\u7684\u9053\u8def\u4e5f\u6ca1\u6709\u90a3\u4e48\u5b89\u5168\u3002\u4eba\u90fd\u529d\u6211\u4fdd\u6696\uff0c\u4f46\u76f8\u6bd4\u5fa1\u5bd2\uff0c\u9632\u6ed1\u624d\u66f4\u91cd\u8981\u3002\\n\\n\u96ea\u5929\u628a\u4e00\u5207\u90fd\u886c\u6258\u7684\u65e0\u6bd4\u660e\u663e\uff0c\u5305\u62ec\u6d41\u6d6a\u6c49\u7684\u8eab\u5f71\u3002\u6700\u8fd1\u6211\u8ba4\u51fa\u51e0\u4e2a\u719f\u8138\u7684\u6d41\u6d6a\u6c49\uff0c\u6bcf\u5929\u8ddf\u4e0a\u73ed\u4e00\u6837\u5b9a\u70b9\u624e\u5728\u81ea\u5df1\u7684\u5730\u76d8\u4e0a\u4e5e\u8ba8\u3002\u5728\u5143\u65e6\u524d\u5915\uff0c\u4e5e\u8ba8\u7684\u82b1\u6837\u4e5f\u4e0d\u5c11\uff0c\u4ed6\u4eec\u548c\u6bcf\u4e2a\u4eba\u8bf4\u65b0\u5e74\u5feb\u4e50\uff0c\u6216\u5728\u74e6\u695e\u677f\u4e0a\u5199\u7740Happy New Year\u3002\\n\\n\u6709\u4e00\u4e2a\u8001\u4eba\u7ad9\u5728\u5730\u94c1\u7ad9\u95e8\u53e3\uff0c\u4e3a\u8fdb\u8fdb\u8fdb\u51fa\u7684\u4eba\u5f00\u95e8\u95ee\u5019\uff0c\u884c\u8272\u5306\u5306\u7684\u4eba\u603b\u559c\u6b22\u628a\u624b\u63d2\u5728\u53e3\u888b\u91cc\uff0c\u5982\u679c\u521a\u597d\u515c\u91cc\u6709\u786c\u5e01\uff0c\u5927\u6982\u5c31\u4f1a\u987a\u624b\u653e\u8fdb\u8001\u4eba\u5de6\u624b\u7684\u7eb8\u676f\u91cc\u3002\u5929\u8272\u7a0d\u665a\u65f6\u6211\u53c8\u7ecf\u8fc7\u4e86\u90a3\u4e2a\u7ad9\uff0c\u53d1\u73b0\u8001\u4eba\u8fd8\u5728\u90a3\u91cc\u5f00\u95e8\u3002\u90a3\u4e2a\u5730\u94c1\u7684\u63a8\u95e8\u53c8\u91cd\u53c8\u51b0\uff0c\u6211\u5bf9\u4ed6\u4ea7\u751f\u4e86\u4e00\u77ac\u95f4\u7684\u656c\u610f\uff0c\u4ed6\u8fd9\u6837\u7684\u5fae\u7b11\u670d\u52a1\u548c\u9152\u5e97\u95e8\u7ae5\u7684\u5de5\u4f5c\u6027\u8d28\u53c8\u6709\u4ec0\u4e48\u533a\u522b\uff1f\\n\\n![Mtl](./img/cafe5.jpg)\\n\\n\u53d1\u8fbe\u56fd\u5bb6\u7684\u65e0\u5bb6\u53ef\u5f52\u4e4b\u4eba\u597d\u50cf\u66f4\u591a\uff0c\u518d\u597d\u7684\u798f\u5229\u5236\u5ea6\u90fd\u65e0\u6cd5\u60e0\u6d4e\u4f17\u4eba\u3002\u4ece\u4ec0\u4e48\u65f6\u5019\u5f00\u59cb\uff0c\u5317\u7f8e\u7684\u65b0\u8d35\u65cf\u53d8\u6210\u79fb\u6c11\u7fa4\u4f53\u4e86\uff1f\u4e5f\u5c31\u51e0\u5341\u5e74\u800c\u5df2\u3002\u4e25\u6b4c\u82d3\u7684\u4e00\u90e8\u5c0f\u8bf4\u53eb\u300a\u65e0\u51fa\u8def\u5496\u5561\u9986\u300b\uff0c\u80cc\u666f\u662f\u4e0a\u4e16\u7eaa\u7684\u7f8e\u56fd\uff0c\u5916\u6765\u4eba\u53e3\u4e0e\u767d\u4eba\u7684\u7b49\u7ea7\u53ef\u8c13\u4e91\u6ce5\u4e4b\u522b\u3002\u6211\u8bb0\u5f97\u4e25\u5728\u4e66\u4e2d\u5f62\u5bb9\uff0c\u5728\u90a3\u4e2a\u5e74\u4ee3\u7559\u5b66\u751f\u4e09\u4e2a\u5b57\u5c31\u662f\u7a77\u4eba\u7684\u4ee3\u540d\u8bcd\u3002\u90a3\u672c\u4e66\u591a\u5c11\u6709\u70b9\u81ea\u4f20\u7684\u6210\u5206\uff0c\u53ea\u6709\u7ecf\u5386\u6478\u722c\u6eda\u6253\u7684\u4eba\u624d\u77e5\u9053\u600e\u4e48\u5014\u5f3a\u5730\u6d3b\u4e0b\u53bb\u3002\\n\\n\u4e25\u7684\u5c0f\u8bf4\u6211\u51e0\u4e4e\u6bcf\u90e8\u90fd\u559c\u6b22\uff0c\u8fd9\u4e00\u672c\u5c24\u5176\u5370\u8c61\u6df1\u523b\uff0c\u56e0\u4e3a\u8eab\u4efd\u548c\u5730\u70b9\u7684\u4ee3\u5165\u611f\u6781\u5f3a\u3002\u987a\u7740\u5979\u7684\u7ebf\u7d22\uff0c\u6211\u7406\u89e3\u5176\u4e2d\u4e00\u5207\u7684\u7269\u8d28\u3001\u8d22\u5bcc\u3001\u7cbe\u795e\u3001\u7231\u60c5\u3001\u5c0a\u4e25\u3001\u80cc\u53db\u3001\u771f\u5b9e\u3001\u671f\u5f85\u3002\u4ece\u6b64\u523b\u7684\u89d2\u5ea6\u53bb\u770b\u5386\u53f2\u6709\u4e00\u79cd\u532a\u5937\u6240\u601d\u7684\u771f\u5b9e\u611f\uff0c\u4f46\u4e25\u6b4c\u82d3\u662f\u4e2a\u72e0\u4eba\uff0c\u7ed3\u5c40\u8fd8\u662f\u65e0\u51fa\u8def\u3002\\n\\n## 3\\n\\n\u6211\u6070\u5de7\u5728\u65b0\u5e74\u7684\u5047\u671f\u5185\u964d\u843d\u4e86\u8499\u7279\u5229\u5c14\uff0c\u79df\u623f\u96be\u5982\u767b\u5929\u3002\u5ba2\u623f\u6211\u53ea\u8ba2\u4e86\u4e09\u665a\uff0c\u9694\u65e5\u53c8\u660f\u7761\u4e86\u5927\u534a\u5929\uff0c\u65f6\u95f4\u5e76\u4e0d\u8db3\u4ee5\u6211\u56db\u5904\u770b\u623f\u79df\u623f\u3002\u52a0\u4e0a\u623f\u4e1c\u4eec\u57fa\u672c\u90fd\u5728\u653e\u5047\uff0c\u53d1\u51fa\u53bb\u7684\u6d88\u606f\u8981\u4e48\u77f3\u6c89\u5927\u6d77\uff0c\u8981\u4e48\u5b89\u6392\u8282\u540e\u63a5\u5f85\u3002\\n\\nCheckout\u90a3\u5929\u662f12\u670831\u53f7\uff0c\u800c\u6211\u5fc5\u987b\u5728\u4e00\u5929\u4e4b\u5185\u79df\u5230\u623f\u5b50\uff0c\u56e0\u4e3a\u8de8\u5e74\u524d\u540e\u7684\u5927\u5c0f\u9152\u5e97\u4e00\u5237\u6c34\u7684\u6ee1\u623f\uff0c\u5c31\u662f\u518d\u60f3\u6361\u6f0f\uff0c\u623f\u4ef7\u4e5f\u662f\u7ffb\u4e86\u4e09\u756a\uff0c\u6d3b\u751f\u751f\u5730\u62ff\u6807\u95f4\u5f53\u5957\u623f\u5356\uff01\\n\\n\u597d\u4e0d\u5bb9\u6613\u6709\u4e00\u5bb6\u90ae\u4ef6\u56de\u590d\u7684\u516c\u5bd3\u3002\u9152\u5e97\u9000\u623f\u540e\u6211\u76f4\u6251\u5b83\u4e00\u697c\u7684\u5c0f\u529e\u516c\u5ba4\u3002\u90a3\u4e2a\u5973\u4eba\u8bf4\u518d\u8fc7\u51e0\u5c0f\u65f6\u5230\u4e94\u70b9\u5979\u5c31\u4e0b\u73ed\u4e86\uff0c\u7136\u540e\u5979\u8981\u4f11\u4e00\u5468\u957f\u5047\u3002\u6211\u7acb\u523b\u8b66\u89c9\uff0c\u518d\u4e0d\u6293\u4f4f\u8fd9\u6700\u540e\u4e00\u6839\u7a3b\u8349\u7684\u8bdd\u4eca\u665a\u8be5\u4f55\u5904\u4e0b\u69bb\uff1f\u626d\u56de\u53bb\u4f4f\u5957\u623f\u4ef7\u7684\u6807\u95f4\uff0c\u8fde\u8fd9\u60f3\u6cd5\u90fd\u8ba9\u6211\u75db\u5fc3\u75be\u9996\u3002\\n\\n![Mtl](./img/cafe6.jpg)\\n\\n\u623f\u95f4\u6bd4\u6211\u60f3\u8c61\u7684\u5927\uff0c\u867d\u7136\u6708\u79df\u6bd4\u9884\u60f3\u7684\u8d35\u4f46\u7b2c\u4e00\u4e2a\u6708\u514d\u79df\u91d1\uff0c\u6c34\u7535\u6696\u4e09\u5305\uff0c\u5012\u817e\u4e00\u4e0b\u4e5f\u5dee\u4e0d\u591a\uff0c\u518d\u8bf4\u6211\u8fd8\u6709\u9009\u62e9\u7684\u4f59\u5730\u5417\uff1f\u4e8e\u662f\u770b\u5b8c\u623f\u6211\u4eec\u5c31\u76f4\u63a5\u51c6\u5907\u7b7e\u5951\u7ea6\u3002\\n\\n\u90a3\u4e2a\u5973\u4eba\u95ee\u8d77\u6211\u7684\u5f53\u5730\u8d26\u6237\uff0c\u6211\u8bf4\u6211\u624d\u6765\u4e24\u5929\uff0c\u8fde\u94f6\u884c\u8fd8\u6ca1\u53bb\u5462\u3002\u5979\u8fdf\u949d\u4e86\u4e00\u4f1a\u513f\uff0c\u5927\u6982\u662f\u4ece\u6ca1\u89c1\u8fc7\u8fd9\u4e48\u98ce\u98ce\u706b\u706b\u627e\u623f\u5b50\u7684\u4eba\uff0c\u5979\u9762\u9732\u96be\u8272\uff0c\u6211\u5fc3\u60ca\u80c6\u6218\u3002\u800c\u540e\u5979\u5374\u95ee\u4e86\u4e00\u53e5\u6beb\u4e0d\u76f8\u5e72\u7684\u8bdd\uff1a\u201c\u4f60\u4e4b\u524d\u5728\u7f8e\u56fd\u4f4f\u8fc7\u5417\uff0c\u662f\u5426\u6709\u5730\u5740\u5462\uff1f\u201d\\n\\n\u201c\u6709\u662f\u6709\uff0c\u4f46\u8fd9\u6709\u4ec0\u4e48\u5173\u7cfb\u5462\uff1f\u201d \u6211\u4e00\u56e2\u4e71\u9ebb\u3002\\n\\n\u201c\u90a3\u5c31\u65b9\u4fbf\u591a\u4e86\uff0c\u8fd9\u6837\u6211\u5c31\u53ef\u4ee5\u67e5\u4f60\u7684\u4fe1\u7528\u8bb0\u5f55\u3002\u201d \u8fd9\u4e24\u4e2a\u56fd\u5bb6\u679c\u7136\u662f\u5728\u5f88\u591a\u65b9\u9762\u4e0d\u5206\u5f7c\u6b64\u3002\\n\\n\u6211\u53ea\u77e5\u9053\u4fe1\u7528\u8bb0\u5f55\u5728\u897f\u65b9\u662f\u4e2a\u51b3\u4e0d\u80fd\u9a6c\u864e\u7684\u51ed\u636e\uff0c\u5bf9\u5b83\u7684\u80a4\u6d45\u8ba4\u77e5\u8fd8\u662f\u6765\u6e90\u4e8e\u5c0f\u8bf4\u3002\u300a\u65e0\u51fa\u8def\u5496\u5561\u9986\u300b\u91cc\u6709\u4e00\u6bb5FBI\u548c\u4e3b\u4eba\u516c\u201c\u6211\u201d\u7684\u5bf9\u8bdd\u5c31\u662f\u9488\u5bf9\u4e8e\u6b64\u3002\\n\\nFBI\u600e\u4e48\u4e5f\u638f\u4e0d\u51fa\u201c\u6211\u201d\u7684\u8001\u5e95\uff0c\u5f88\u5403\u60ca\uff1a \u201c\u4f60\u6ca1\u6709\u4fe1\u7528\u53ef\u67e5\uff0c\u53ef\u662f\u4e3a\u4ec0\u4e48\u5462\uff1f\u201d\\n\\n\u201c\u4f60\u770b\uff0c\u597d\u51e0\u5bb6\u94f6\u884c\u52a8\u5458\u6211\u7533\u8bf7\u4ed6\u4eec\u7684\u4fe1\u7528\u5361\uff0c\u53ef\u6211\u4e00\u7533\u8bf7\u4ed6\u4eec\u90fd\u56de\u7b54\u8bf4\uff1a\u5bf9\u4e0d\u8d77\uff0c\u6211\u4eec\u65e0\u6cd5\u67e5\u5230\u60a8\u7684\u4fe1\u7528\u8bb0\u5f55\u3002\u201d\\n\\n\u201c\u6362\u4e86\u6211\u4e5f\u4f1a\u7ed9\u4f60\u540c\u6837\u7684\u56de\u7b54\uff0c\u6240\u4ee5\u4f60\u5fc5\u987b\u5efa\u7acb\u4fe1\u7528\u8bb0\u5f55\u3002\u201d\\n\\n\u201c\u90a3\u8fd9\u5f97\u5148\u501f\u94b1\uff0c\u7136\u540e\u6309\u671f\u8fd8\u6b3e\u3002\u53ef\u4f60\u8ddf\u4efb\u4f55\u4eba\u501f\u94b1\uff0c\u4ed6\u90fd\u8981\u770b\u770b\u4f60\u662f\u5426\u8bb0\u5f55\u826f\u597d\u3002\u201d\\n\\n\u6ca1\u6709\u4fe1\u7528\u8bb0\u5f55\u5c31\u4e0d\u80fd\u8d37\u6b3e\uff0c\u53ef\u4e0d\u8d37\u6b3e\u53c8\u6ca1\u6cd5\u5efa\u7acb\u4fe1\u7528\u8bb0\u5f55\u3002\u8fd9\u53ef\u4e0d\u5c31\u662f\u5178\u578b\u7684\u201c\u7b2c\u4e8c\u5341\u4e8c\u6761\u519b\u89c4\u201d\uff1f\\n\\n\u201c\u8fd9\u662f\u4f60\u5728\u7f8e\u56fd\u7684\u5730\u5740\u5417\uff1f\u201d \u4e00\u4e2a\u58f0\u97f3\u4f3c\u8fd1\u4f3c\u8fdc\u5730\u4f20\u6765\u3002\\n\\n\u201c\u554a\uff0c\u4ec0\u4e48\uff1f\u201d\\n\\n\u201c\u8bf7\u6838\u5bf9\u4e00\u4e0b\u4f60\u7684\u5730\u5740\u3002\u201d \u90a3\u4e2a\u5973\u4eba\u7ee7\u7eed\u6572\u6253\u952e\u76d8\u3002\u6211\u6709\u65f6\uff0c\u7adf\u7136\u53ef\u4ee5\u5728\u4e00\u4e2a\u79bb\u6211\u90a3\u4e48\u8fd1\u7684\u4eba\u9762\u524d\u8d70\u795e\u8d70\u7684\u4e00\u584c\u7cca\u6d82\uff01\\n\\n\u6211\u5927\u81f4\u626b\u4e86\u4e00\u773c\u6240\u6709\u6761\u7ea6\uff0c\u7136\u540e\u5f88\u7528\u529b\u5730\u7b7e\u4e86\u4e2a\u540d\uff0c\u5dee\u70b9\u6233\u901a\u4e86\u7eb8\uff0c\u62c9\u56de\u4e86\u6240\u6709\u6e38\u79bb\u7684\u601d\u7ef4\u3002\\n\\n\u5973\u4eba\u7ed9\u4e86\u6211\u94a5\u5319\uff0c\u9001\u6211\u8fdb\u95e8\u3002\u6765\u7684\u8def\u4e0a\u6211\u8fd8\u5728\u60f3\u201c\u62bc\u4e00\u4ed8\u4e8c\u201d\u90a3\u4e9b\u884c\u8bdd\uff0c\u73b0\u91d1\u4e0d\u591f\u600e\u4e48\u529e\uff0c\u8981\u600e\u4e48\u4ea4\u6613\u7b49\u7b49\u3002\u4e00\u5207\u7ed3\u675f\u65f6\u624d\u53d1\u73b0\uff0c\u6211\u4e0d\u4ec5\u6ca1\u63d0\u524d\u4ea4\u623f\u79df\uff0c\u8fde\u62bc\u91d1\u90fd\u4e0d\u7528\uff0c\u52a0\u4e0a\u9996\u6708\u514d\u79df\uff0c\u6211\u534a\u6bdb\u94b1\u90fd\u6ca1\u7ed9\u5c31\u62ce\u5305\u5165\u4f4f\u4e86\u3002\\n\\n\u672b\u4e86\uff0c\u6211\u8fd8\u662f\u60f3\u8d77\u4e86\u4e66\u4e0a\u90a3\u6bb5\uff0c\u8054\u60f3\u88ab\u6253\u65ad\u7684\u540e\u6587\u662f\uff1a\u6ca1\u6709\u4fe1\u7528\u8bb0\u5f55\uff0c\u4f60\u8fd9\u4e2a\u4eba\u7b49\u4e8e\u4e0d\u5b58\u5728\u3002\\n\\n## 4\\n\\n\u4f4f\u5904\u6709\u4e86\uff0c\u4f46\u6211\u8fd8\u662f\u6ca1\u6709\u5927\u529f\u544a\u6210\u7684\u611f\u89c9\u3002\u6ca1\u6709\u5e8a\uff0c\u4e0d\u80fd\u8eba\uff1b\u6ca1\u6905\u5b50\uff0c\u4e0d\u80fd\u5750\uff1b\u6709\u51b0\u7bb1\uff0c\u662f\u7a7a\u7684\u3002\\n\\n\u5f53\u65f6\u4e0b\u5348\u4e24\u70b9\u5de6\u53f3\uff0c\u4e94\u70b9\u949f\u6240\u6709\u7684\u5546\u5bb6\u90fd\u4f1a\u63d0\u524d\u6253\u70ca\uff0c\u5143\u65e6\u8fd8\u8981\u5173\u95e8\u4e00\u5929\u3002\u6211\u7acb\u523b\u51fa\u95e8\uff0c\u4e09\u5c0f\u65f6\u6211\u5f97\u641e\u6765\u4e00\u5f20\u5e8a\u3002\u5927\u4ef6\u4e0d\u597d\u529e\uff0c\u6211\u60f3\u597d\u4e0b\u7b56\uff0c\u5927\u4e0d\u4e86\u4e70\u4e00\u4e2a\u91ce\u8425\u7761\u888b\u628a\u81ea\u5df1\u7ed1\u4e24\u665a\u3002\u7761\u888b\u6ca1\u627e\u7740\uff0c\u6211\u5012\u53d1\u73b0\u4e86\u5145\u6c14\u5e8a\u57ab\uff0c\u5145\u5b8c\u540e\u5c3a\u5bf8\u7adf\u7136\u6bd4\u5e8a\u5927\u3002\\n\\n\u6211\u4e0d\u505c\u7684\u5f80\u8fd4\u4e8e\u516c\u5bd3\u4e0e\u6700\u8fd1\u7684\u5546\u573a\u4e4b\u95f4\uff0c\u597d\u5728\u8ddd\u79bb\u4e0d\u8fdc\uff0c\u6211\u4e00\u8def\u8dd1\u53bb\u518d\u624b\u63d0\u80cc\u625b\u5730\u8fd0\u8f93\u7269\u8d44\u56de\u5934\u3002\u65f6\u95f4\u4e00\u5206\u5206\u5730\u8fc7\u53bb\uff0c\u4e0b\u73ed\u7684\u4eba\u6d41\u91cf\u8d8a\u6765\u8d8a\u731b\uff0c\u6240\u6709\u4eba\u5f52\u5fc3\u4f3c\u7bad\uff0c\u7b49\u5f85\u8de8\u5e74\u3002\u4e3a\u5c6f\u7cae\u800c\u4e70\u83dc\u7684\u4eba\u987f\u65f6\u591a\u4e86\u8d77\u6765\uff0c\u8d85\u5e02\u6536\u94f6\u5458\u6765\u4e0d\u53ca\u62ac\u5934\uff0c\u626b\u7801\u7684\u624b\u901f\u8d8a\u6765\u8d8a\u5feb\uff0c\u4ed6\u5728\u7b97\u7740\u81ea\u5df1\u8fd8\u6709\u591a\u4e45\u5c31\u89e3\u653e\uff0c\u6211\u4e5f\u5728\u7b97\u7740\u8fd8\u9700\u8981\u518d\u8dd1\u51e0\u4e2a\u6765\u56de\u3002\\n\\n![Mtl](./img/cafe7.jpg)\\n\\n\u79bb\u5317\u6781\u5708\u8fd1\u7684\u5730\u65b9\u5929\u9ed1\u7684\u65e9\uff0c\u56db\u70b9\u534a\u5c31\u5f00\u59cb\u4eae\u706f\uff0c\u6211\u8fd9\u624d\u6ce8\u610f\u5230\u4e00\u6392\u5927\u6811\u4e0a\u7ed5\u6ee1\u4e86\u8282\u65e5\u7684\u5f69\u706f\u3002\u6d41\u6d6a\u6c49\u4eec\u6293\u7d27\u6700\u540e\u4e00\u6ce2\u4eba\u6d41\u6765\u4e5e\u8ba8\uff0c\u56e0\u4e3a\u4ed6\u4eec\u4e5f\u8feb\u5207\u5730\u60f3\u8fc7\u4e2a\u597d\u5e74\u3002\u65f6\u95f4\u591f\u6211\u6700\u540e\u4e00\u4e2a\u6765\u56de\u7684\u51b2\u523a\uff0c\u4e70\u5e8a\u5355\u4e70\u6bdb\u6bef\uff0c\u4e70\u7a97\u5e18\u4e70\u5395\u7eb8\u3002\u90a3\u5929\u90a3\u4e48\u628a\u65f6\u95f4\u5f53\u547d\u8d76\u7684\uff0c\u5c31\u662f\u6d41\u6d6a\u6c49\u548c\u6211\uff0c\u53ea\u4e0d\u8fc7\u4ed6\u4e3a\u4e00\u665a\uff0c\u6211\u4e3a\u4e00\u5e74\u4e3a\u4e00\u751f\u3002\\n\\n\u73b0\u5728\u8ba9\u6211\u518d\u62ff\u51fa\u90a3\u5929\u7684\u52b2\u5934\u662f\u600e\u4e48\u4e5f\u529e\u4e0d\u5230\u4e86\u3002\u9694\u5929\u5f00\u59cb\u808c\u8089\u75bc\uff0c\u6bd4\u505a\u4e86\u51e0\u5341\u4e2a\u6df1\u8e72\u8fd8\u9178\u723d\u3002\u6ca1\u6709\u4e86\u7d27\u8feb\u611f\uff0c\u610f\u8bc6\u5c31\u677e\u61c8\u4e86\uff0c\u4e1c\u897f\u53ea\u80fd\u6162\u6162\u4e70\u3002\u4eca\u5929\u62ce\u53ea\u6c34\u58f6\uff0c\u660e\u5929\u63d0\u4e2a\u62d6\u628a\uff0c\u6709\u7a7a\u5e26\u8d70\u8863\u67b6\uff0c\u5076\u5c14\u518d\u4e70\u51e0\u4e2a\u6f02\u4eae\u7684\u7897\uff0c\u70df\u706b\u6c14\u5728\u8682\u8681\u642c\u5bb6\u4e2d\u4e00\u5929\u5929\u4ea7\u751f\u3002\u6211\u672c\u6765\u5c31\u6253\u7b97\u8fd9\u6837\u4e0d\u7d27\u4e0d\u6162\uff0c\u54ea\u77e5\u706b\u707e\u73b0\u573a\u51fa\u86ee\u52b2\uff0c\u90a3\u5929\u7684\u8d85\u4eba\u4f53\u8d28\u4e00\u53bb\u4e0d\u590d\u8fd4\u3002\\n\\n## 5\\n\\n\u5e76\u6ca1\u6709\u5f88\u591a\u4eba\u77e5\u9053\u6211\u7684\u53bb\u5411\u3002\u4e0b\u98de\u673a\u540e\u6211\u5728\u8138\u4e66\u4e0acheck-in\u4e86\u673a\u573a\u5750\u6807\uff0c\u4f30\u8ba1\u8fd9\u5c31\u662f\u6211\u66b4\u9732\u4e86\u884c\u8e2a\u7684\u539f\u56e0\u3002\u9694\u5929\u6211\u6536\u5230\u4e86\u4e00\u6761\u4ee4\u6211\u8be7\u5f02\u7684\u4fe1\u606f\u3002\\n\\n\u201c\u55e8\uff0c\u4f60\u8fd8\u8bb0\u5f97\u6211\u5417\uff1f\u4f60\u5728\u8499\u7279\u5229\u5c14\u5417\uff0c\u6211\u5728\u591a\u4f26\u591a\uff0c\u5e0c\u671b\u53ef\u4ee5\u518d\u89c1\u4e00\u9762\u3002\u201d\\n\\n\u8fd9\u5230\u5e95\u662f\u8c01\u3002\u540d\u5b57\u5b8c\u5168\u63d0\u793a\u4e0d\u4e86\u4efb\u4f55\u8bb0\u5fc6\uff0c\u4f46\u82e5\u4e0d\u8ba4\u8bc6\u7684\u8bdd\u600e\u4e48\u4f1a\u5728\u6211\u7684\u8054\u7cfb\u4eba\u91cc\u3002\u6253\u5f00\u5bf9\u8bdd\u540e\u6211\u628a\u5c4f\u5e55\u5f80\u4e0a\u6eda\u4e86\u51e0\u884c\uff0c\u4e0a\u4e00\u6b21\u4fe1\u606f\uff0c\u5c45\u7136\u662f\u57282013\u5e742\u67089\u53f7\u3002\\n\\n![Mtl](./img/cafe8.jpg)\\n\\n\u6211\u60f3\u8d77\u6765\u4e86\uff0c\u5728\u5c0f\u57ce\u8d1d\u85cf\u677e\u7684\u8f66\u7ad9\u6211\u8ff7\u8def\u4e86\u3002\u6211\u53ef\u4ee5\u60f3\u8c61\u81ea\u5df1\u66fe\u7ecf\u6709\u591a\u83dc\u9e1f\uff0c\u662f\u8fd9\u4e2a\u6cd5\u56fd\u4eba\u6559\u6211\u600e\u4e48\u8f6c\u8f66\uff0c\u518d\u5750\u54ea\u4e2a\u706b\u8f66\u53bb\u5357\u90e8\u7684\u3002\u4e34\u8d70\u65f6\u4ed6\u8bf4\u4e0b\u6b21\u518d\u7ecf\u8fc7\u8d1d\u85cf\u677e\u7684\u8bdd\u8fd8\u53ef\u4ee5\u627e\u4ed6\uff0c\u6211\u975e\u5e38\u793c\u8c8c\u5730\u56de\u590d\u4e86\u597d\u5e76\u611f\u8c22\u4e86\u4ed6\u7684\u6c5f\u6e56\u6551\u6025\u3002\\n\\n\u8bf4\u6765\u8fd9\u786e\u5b9e\u662f\u4e00\u4e2a\u5f88\u5ba2\u5957\u7684\u7ea6\u5b9a\uff0c\u8fd9\u7ea6\u4e00\u723d\u5c31\u662f\u4e94\u5e74\u3002\u4e16\u754c\u7adf\u5982\u6b64\u4e4b\u5c0f\uff0c\u4f46\u6211\u4eec\u840d\u6c34\u76f8\u9022\uff0c\u53ea\u80fd\u540e\u4f1a\u65e0\u671f\u3002\\n\\n\u53d1\u4fe1\u606f\u53ef\u4ee5\u63a9\u9970\u8bb0\u5fc6\u4e0a\u7684\u6f0f\u6d1e\uff0c\u8bdd\u9898\u5c45\u7136\u4e0d\u5c34\u4e0d\u5c2c\u5730\u63a5\u4e0a\u4e86\u3002\u51e0\u53e5\u5bd2\u6684\u4e4b\u540e\uff0c\u679c\u7136\uff0c\u4eba\u89c1\u4eba\u95ee\u7684\u5927\u95ee\u9898\u53c8\u6765\u4e86 \u201cSo \u4f60\u89c9\u5f97\u8fd9\u513f\u600e\u4e48\u6837\uff1f\u201d\\n\\n\u201c\u5f88\u597d\uff0c\u4e5f\u5f88\u51b7\u3002\u201d\\n\\n\u6211\u5f53\u7136\u770b\u4e0d\u89c1\u4e5f\u542c\u4e0d\u89c1\u4ed6\u6709\u6ca1\u6709\u7b11\u3002\u4f46\u968f\u5373\u53ee\u53ee\u549a\u549a\u53d1\u6765\u4e00\u4e32\u5927\u7b11\u7684\u8868\u60c5\u5305\uff0c\u6211\u7b11\u4e86\u3002"},{"id":"\u4e00\u57ce\u4e00\u5473\u4e00\u671f\u4e00\u4f1a","metadata":{"permalink":"/kilimanjaro/\u4e00\u57ce\u4e00\u5473\u4e00\u671f\u4e00\u4f1a","editUrl":"https://github.com/jing-gu/kilimanjaro/blog/2018/2018-11-29-\u4e00\u57ce\u4e00\u5473\u4e00\u671f\u4e00\u4f1a.md","source":"@site/blog/2018/2018-11-29-\u4e00\u57ce\u4e00\u5473\u4e00\u671f\u4e00\u4f1a.md","title":"\u4e00\u57ce\u4e00\u5473\uff0c\u4e00\u671f\u4e00\u4f1a","description":"Okinawa","date":"2018-11-29T00:00:00.000Z","tags":[{"inline":false,"label":"\u65c5\u884c","permalink":"/kilimanjaro/tags/\u65c5\u884c","description":"\u65c5\u884c tag description"},{"inline":true,"label":"\u51b2\u7ef3","permalink":"/kilimanjaro/tags/\u51b2\u7ef3"}],"readingTime":12.3,"hasTruncateMarker":false,"authors":[],"frontMatter":{"slug":"\u4e00\u57ce\u4e00\u5473\u4e00\u671f\u4e00\u4f1a","title":"\u4e00\u57ce\u4e00\u5473\uff0c\u4e00\u671f\u4e00\u4f1a","tags":["\u65c5\u884c","\u51b2\u7ef3"],"date":"2018-11-29T00:00:00.000Z"},"unlisted":false,"prevItem":{"title":"\u65e0\u51fa\u8def\u5496\u5561\u9986","permalink":"/kilimanjaro/\u65e0\u51fa\u8def\u5496\u5561\u9986"},"nextItem":{"title":"\u4eac\u90fd | \u53bb\u4eac\u90fd\u6f2b\u6b65\uff0c\u4f4f\u80f6\u56ca\u5403\u6ce1\u996d","permalink":"/kilimanjaro/\u4eac\u90fd\u53bb\u4eac\u90fd\u6f2b\u6b65\u4f4f\u80f6\u56ca\u5403\u6ce1\u996d"}},"content":"![Okinawa](./img/okinawa1.jpg)\\n\\n\u8fd9\u6b21\u53bb\u51b2\u7ef3\uff0c\u5b9e\u5728\u662f\u4e2a\u610f\u6599\u4e4b\u5916\u7684\u4e8b\u4ef6\u3002\\n\\n\u672c\u6765\u6253\u7b97\u7ea6\u53bb\u9999\u6e2f\uff0c\u4e8e\u662f\u6211\u4eec\u9009\u597d\u4e86\u65e5\u671f\uff0c\u770b\u4e2d\u4e86\u673a\u7968\uff0c\u7269\u8272\u4e86\u9152\u5e97\uff0c\u6252\u597d\u4e86\u653b\u7565\u2026\u5c31\u5728\u8ba2\u673a\u7968\u7684\u5343\u94a7\u4e00\u53d1\u65f6\u523b\uff0c\u624b\u673a\u5c4f\u5e55\u4e0a\u7684\u4e00\u6761\u65b0\u4fe1\u606f\u5374\u628a\u6211\u5413\u5f97\u9b42\u98de\u9b44\u6563\u3002\\n\\n\u201c\u6211\u4e70\u4e0d\u4e86\u673a\u7968\u554a\uff0c\u6211\u62a4\u7167\u8fc7\u671f\u4e86\u5929\u5450\uff01\u201d\\n\\n\u6211\u4e24\u773c\u4e00\u9ed1\u3002\u59d0\u554a\uff0c\u4f60\u8fd9\u662f\u6709\u591a\u4e45\u6ca1\u51fa\u8fdc\u95e8\u4e86\uff0c\u62a4\u7167\u8fc7\u671f\u4e00\u4e2a\u6708\u5c45\u7136\u4e0d\u81ea\u77e5\uff1f\uff01\\n\\n\u6211\u5411\u6765\u5bf9\u96f7\u5389\u98ce\u884c\u7684\u5feb\u624b\u5341\u5206\u6ee1\u610f\uff0c\u4f46\u8fd9\u6b21\u6211\u771f\u5e86\u5e78\u6162\u4e86\u4e00\u62cd\u3002\u4e14\u4e0d\u8bf4\u8ba1\u5212\u6ce1\u6c64\uff0c\u8fd9\u79cd\u65e0\u8bed\u7684\u7406\u7531\u6309\u5e38\u7406\u6211\u5927\u6982\u8981\u62cd\u684c\u62cd\u5927\u817f\u4e86\u3002\u7acb\u9a6c\u8f6c\u79fb\u6ce8\u610f\u529b\uff0c\u5feb\u60f3\u65b9\u6848B\uff0c\u95ee\u9898\u89e3\u51b3\u9ad8\u4e8e\u4e00\u5207\u8d23\u96be\u662f\u975e\u3002\\n\\n\u4e8e\u662f\u6211\u5728\u6210\u7530\u673a\u573a\u548c\u6d66\u4e1c\u673a\u573a\u4e4b\u95f4\u5212\u4e86\u6761\u7ebf\uff0c\u5f80\u5357\u98de\u7684\u822a\u73ed\u8017\u65f6\u5dee\u4e0d\u591a\uff0c\u4e00\u76f4\u4e00\u76f4\u5f80\u5357\u770b\uff0c\u7784\u4e2d\u4e86\u51b2\u7ef3\u3002\u56e0\u4e3a\u8fd9\u4e2a\u6ca1\u6709\u62a4\u7167\u5c31\u51fa\u4e0d\u4e86\u56fd\u7684\u4eba\uff0c\u4e8b\u6001\u7a81\u53d8\u4e4b\u4e0b\u5c31\u53d8\u6210\u6211\u51fa\u4e86\uff0c\u8c01\u8ba9\u5979\u662f\u6211\u59d0\u5462\uff0c\u662f\u6211\u6700\u7231\u7684\u4e00\u53ea\u5462\u3002\\n\\nM\u6bd4\u6211\u5927\u4e24\u5c81\uff0cM\u5979\u5a18\u8bf4\u597d\u50cf\u591a\u4e86\u4e2a\u5c0f\u5973\u513f\uff0c\u6240\u4ee5\u6211\u603b\u662f\u53eb\u5979\u300c\u304a\u59c9\u3061\u3083\u3093\u300d\uff08M\u5c0f\u59d0\u59d0\uff09\u3002\u6ca1\u6709\u8840\u7f18\u7684\u5173\u7cfb\uff0c\u53ea\u6709\u65f6\u95f4\u7684\u6c89\u6dc0\uff0c\u4e5f\u771f\u4e0d\u77e5\u662f\u4ec0\u4e48\u5b87\u5b99\u95f4\u7684\u5438\u5f15\u529b\u6cd5\u5219\u53ef\u4ee5\u8fd9\u6837\u5f62\u6210\u7275\u7eca\uff0c\u60f3\u60f3\u6709\u65f6\u540e\u5929\u4eb2\u4eba\u5927\u6982\u5c31\u662f\u5982\u6b64\u5427\u3002\\n\\n![Okinawa](./img/okinawa2.jpg)\\n\\n\u8bb0\u5fc6\u79bb\u4e0d\u5f00\u5730\u70b9\u7684\u4f9d\u6258\uff0c\u800c\u8bb0\u4f4f\u4e00\u4e2a\u57ce\u5e02\u6700\u597d\u7684\u65b9\u6cd5\u662f\u5473\u89c9\uff0c\u89c6\u89c9\u662f\u7ecf\u4e0d\u8d77\u65f6\u95f4\u8003\u91cf\u7684\u3002\u4eba\u6bd5\u7adf\u662f\u8d8a\u8001\u773c\u8d8a\u82b1\uff0c\u53ef\u4f60\u5f88\u5c11\u542c\u8bf4\u8c01\u8d8a\u8001\u820c\u5934\u8d8a\u949d\u3002\u5176\u6b21\uff0c\u98ce\u666f\u662f\u53ef\u4ee5\u590d\u5236\u7684\uff0c\u53ea\u8981\u591f\u571f\u8c6a\uff0c\u767d\u5bab\u4e5f\u53ef\u4ee5\u625b\u8fc7\u6765\u3002\u4f46\u662f\uff0c\u6c34\u571f\u4e0d\u540c\u7684\u5730\u65b9\uff0c\u5374\u8fde\u4e00\u5757\u8c46\u8150\u7684\u5473\u9053\u90fd\u65e0\u6cd5\u91cd\u73b0\u3002\\n\\n\u5473\u89c9\u7684\u5524\u9192\u663e\u7136\u4e0d\u5982\u89c6\u89c9\u7684\u51b2\u51fb\uff0c\u540e\u8005\u6548\u679c\u66f4\u5f3a\uff0c\u4f46\u524d\u8005\u6301\u7eed\u66f4\u4e45\u3002\u6211\u4e00\u76f4\u94a6\u4f69\u90a3\u79cd\u53ef\u4ee5\u9760\u4e00\u9053\u83dc\u800c\u54c1\u51fa\u5bf9\u65b9\u5fc3\u5883\u7684\u4eba\uff0c\u8fd9\u5176\u4e2d\u5e94\u8be5\u4e0d\u53ea\u662f\u76f2\u54c1\u7684\u4e13\u4e1a\u6280\u5de7\uff0c\u8be5\u6709\u591a\u5c11\u98ce\u96e8\u6c89\u6d6e\u7684\u9605\u5386\u624d\u80fd\u7ec3\u5c31\u5ba0\u8fb1\u4e0d\u60ca\u7684\u5473\u89c9\u548c\u6d1e\u5bdf\u4e16\u4e8b\u7684\u540c\u7406\u5fc3\uff1f\\n\\n## \u8089\u98df\u8005\u4e0d\u9119\\nM\u662f\u8089\u98df\u52a8\u7269\uff0c\u6211\u662f\u8349\u98df\uff0c\u8bdd\u867d\u5982\u6b64\u6211\u8fd8\u662f\u505a\u4e0d\u5230\u4e25\u683c\u7684\u7d20\u98df\u4e3b\u4e49\uff0c\u65e0\u975e\u662f\u8ba8\u538c\u5403\u732a\u8089\u800c\u5df2\uff0c\u6240\u4ee5\u51c6\u786e\u7684\u8bf4\u6211\u662f\u6311\u98df\u52a8\u7269\u3002\u8fd9\u6837\u7684\u6211\u4eec\u5728\u996d\u684c\u4e0a\u4ece\u4e0d\u6d6a\u8d39\u7cae\u98df\uff0c\u6bd5\u7adf\u5404\u53d6\u6240\u9700\uff0c\u4e0d\u7231\u7684\u4e1c\u897f\u5bf9\u65b9\u5403\u3002\\n\\n\u4f46\u662f\uff0c\u51b2\u7ef3\u7684\u540d\u83dc\uff0c\u7adf\u7136\u662f\u732a\u8089\u3002\\n\\n\u201c\u4f60\u4e0d\u662f\u8981\u5c1d\u5f53\u5730\u7279\u8272\u5417\uff1f\u4e0d\u6765\u4e00\u53e3\u5417\uff1f\u201d\\n\\n\u201c\u5bf9\uff0c\u4ec5\u9650\u732a\u8089\u4e4b\u5916\u7684\u7279\u8272\u3002\u201d\\n\\n\u201c\u6709\uff0c\u300c\u30c1\u30e3\u30f3\u30d7\u30eb\u30fc\u300d\u7092\u82e6\u74dc\u3002\u201d \u90a3\u662f\u6211\u6781\u4e3a\u719f\u6089\u7684\u72e1\u9ee0\u7684\u795e\u8272\u3002\\n\\n\u54ea\u77e5\u8fd9\u4e5f\u4e0d\u662f\u4e2a\u5bb9\u6613\u7684\u9009\u62e9\u3002\u786e\u5b9e\uff0c\u4e0d\u7ba1\u600e\u4e48\u8c03\u67e5\uff0c\u51b2\u7ef3\u7684\u7279\u8272\u771f\u662f\u732a\u8089\u548c\u82e6\u74dc\u3002\\n\\n\u201c\u597d\u5427\u59d0\uff0c\u6211\u5403\u82e6\u74dc\u3002\u201d \u90a3\u4e00\u789f\u8089\u5c31\u88ab\u6beb\u4e0d\u5ba2\u6c14\u5730\u63fd\u4e0b\u53bb\u4e86\u3002\\n\\n![Okinawa](./img/okinawa3.jpg)\\n\\n\u53ef\u6211\u600e\u4e48\u770b\uff0c\u8fd9\u51b2\u7ef3\u7684\u540d\u7269\uff0c\u4e0d\u5c31\u662f\u4e1c\u5761\u8089\u5417\uff1f\u6211\u60f3\u8d77\u82cf\u4e1c\u5761\u7684\u6253\u6cb9\u8bd7\uff1a\u65e0\u7af9\u4ee4\u4eba\u4fd7\uff0c\u65e0\u8089\u4ee4\u4eba\u7626\uff0c\u82e5\u8981\u4e0d\u4fd7\u4e0e\u4e0d\u7626\uff0c\u9664\u975e\u5929\u5929\u7b0b\u70e7\u8089\u3002M\u770b\u6211\u7b11\u7684\u8be1\u5f02\uff0c\u5948\u4f55\u6211\u4e5f\u65e0\u6cd5\u89e3\u91ca\u8fd9\u6837\u7684\u7edd\u53e5\uff0c\u56e0\u4e3a\u771f\u6ca1\u6709\u4efb\u4f55\u8bed\u8a00\u53ef\u4ee5\u7ffb\u8bd1\u4e1c\u5761\u5148\u751f\u7684\u5e7d\u9ed8\u4e0e\u8c41\u8fbe\uff0c\u60f3\u6765\u4ed6\u4e5f\u662f\u6587\u53f2\u4e0a\u6709\u540d\u7684\u998b\u4eba\u5462\u3002\\n\\n\u82cf\u4e1c\u5761\u5bf9\u732a\u8089\u771f\u7684\u5f88\u6709\u4e00\u624b\uff0c\u574a\u95f4\u6d41\u4f20\u4ed6\u7684\u4e00\u9996\u732a\u8089\u9882\uff0c\u5f00\u5934\u201c\u9ec4\u5dde\u597d\u732a\u8089\u201d\u3002\u4f46\u8bf4\u201c\u5bcc\u8005\u4e0d\u89e3\u5403\uff0c\u8d2b\u8005\u4e0d\u89e3\u716e\u201d\uff0c\u597d\u5403\u5230\u679c\u771f\u5982\u6b64\u5417\uff1f\u6211\u4e5f\u65e0\u4ece\u77e5\u6653\uff0c\u56e0\u6211\u4ece\u6ca1\u5403\u8fc7\u4e1c\u5761\u8089\u3002\u4e5f\u4ece\u6ca1\u60f3\u5403\uff0c\u539a\u7684\u50cf\u4e00\u5757\u6a61\u76ae\uff0c\u770b\u4e86\u603b\u6709\u79cd\u60f3\u5f53\u6c99\u5305\u4e00\u6837\u629b\u51fa\u53bb\u7684\u6b32\u671b\u3002\\n\\n\u4f46\u7406\u667a\u544a\u8bc9\u6211\u90a3\u5757\u8089\u4e0d\u5bb9\u5c0f\u89d1\u3002\u6211\u770b\u7740M\u7528\u7b77\u5b50\uff0c\u6beb\u4e0d\u8d39\u529b\u5730\u5c06\u51b2\u7ef3\u732a\u8089\u76f4\u63a5\u5939\u65ad\u4e86\uff0c\u5802\u800c\u7687\u4e4b\u5730\u5403\u72ec\u98df\u3002\u6211\u5185\u5fc3\u4e00\u9635\u98a4\u6817\uff0c\u4f55\u6b62\u662f\u706b\u5019\uff0c\u90a3\u732a\u8089\u6050\u6015\u662f\u7096\u51fa\u4e86\u4e3b\u4eba\u4e00\u8eab\u7684\u5185\u529f\u3002\\n\\n## \u9c7c\u6211\u6240\u6b32\u4e5f\\n\u5982\u679c\u53ef\u80fd\u7684\u8bdd\uff0c\u6bcf\u5230\u4e00\u4e2a\u65b0\u5730\u65b9\u6211\u90fd\u6068\u4e0d\u5f97\u6e9c\u4e00\u5708\u83dc\u573a\u3002\u6ca1\u6709\u54ea\u91cc\u6bd4\u83dc\u573a\u66f4\u80fd\u53cd\u6620\u6c11\u751f\u4e86\uff0c\u573a\u5730\u5e72\u51c0\u8bf4\u660e\u4eba\u4eec\u52e4\u5feb\u536b\u751f\uff0c\u98df\u6750\u4e30\u5bcc\u6697\u793a\u751f\u6d3b\u6c34\u51c6\u4e0d\u4f4e\uff0c\u7269\u4ef7\u504f\u8d35\u770b\u6765\u4eba\u4eec\u6536\u5165\u4e5f\u4e0d\u83f2\uff0c\u4e0e\u83dc\u4ef7\u6c34\u6da8\u8239\u9ad8\u3002\\n\\n\u65e2\u80fd\u586b\u9971\u809a\u5b50\uff0c\u53c8\u80fd\u514d\u8d39\u6e38\u73a9\uff0c\u8fd8\u6709\u54ea\u91cc\u66f4\u6bd4\u83dc\u573a\u4e00\u77f3\u4e8c\u9e1f\uff1f\\n\\n![Okinawa](./img/okinawa4.jpg)\\n\\n\u90a3\u8987\u5e02\u7684\u7267\u5fd7\u5e02\u5834\u662f\u4e00\u4e2a\u4e0d\u7ba1\u5f53\u5730\u4eba\u8fd8\u662f\u5916\u6765\u4eba\u90fd\u559c\u6b22\u524d\u5f80\u7684\u5730\u65b9\u3002\u5b83\u7684\u72ec\u7279\u4e4b\u5904\u5728\u4e8e\u4e00\u697c\u5356\u98df\u6750\u548c\u751f\u9c9c\uff0c\u4e8c\u697c\u662f\u5404\u5bb6\u996d\u5802\u3002\u5927\u81f4\u8d70\u4e00\u5708\u4e00\u697c\u53ef\u4ee5\u770b\u5230\u4e0d\u5c11\u8001\u5976\u5976\u5728\u53eb\u5356\u81ea\u5df1\u505a\u7684\u6e0d\u7269\u3001\u6d77\u85fb\u7b49\u571f\u4ea7\u3002\u65c5\u884c\u7684\u4eba\u603b\u662f\u6210\u4e3a\u201c\u88ab\u8bd5\u5403\u201d\u7684\u5bf9\u8c61\uff0c\u7a0d\u6709\u4e00\u4e2a\u773c\u795e\u4ea4\u6d41\u9a6c\u4e0a\u5c31\u4e0d\u5bb9\u5206\u8bf4\u5730\u5c31\u5f80\u4f60\u624b\u5fc3\u91cc\u5012\u70b9\u5c0f\u5403\uff0c\u9012\u6839\u7259\u7b7e\uff0c\u9001\u4e0a\u7eb8\u5dfe\uff0c\u70ed\u60c5\u5230\u4e0d\u5fcd\u62d2\u7edd\u3002\\n\\n\u8fd9\u662f\u83dc\u573a\u7684\u5e38\u6001\uff0c\u5404\u56fd\u7684\u5546\u8d29\u90fd\u5f88\u7cbe\u901a\u201c\u4e34\u95e8\u4e00\u811a\u201d\u7684\u6280\u5de7\uff0c\u5e78\u597d\u822a\u7a7a\u7981\u6b62\u8fd9\u94c1\u6253\u7684\u4e8b\u5b9e\u603b\u80fd\u6210\u529f\u5730\u62e6\u622a\u5288\u5934\u76d6\u8138\u7684\u9500\u552e\u3002\u8c01\u77e5\u7cbe\u660e\u7684\u5e97\u4e3b\u7adf\u80fd\u5728\u6211\u72b9\u8c6b\u4e4b\u524d\u5148\u53d1\u5236\u4eba\uff1a\u8fd9\u662f\u771f\u7a7a\u5305\u88c5\uff0c\u53ef\u4ee5\u4e0a\u98de\u673a\u7684\u54df\u3002\u8fd9\u4f4d\u5927\u59d0\u554a\uff0c\u4f60\u62a2\u767d\u4e86\u6211\u552f\u4e00\u9632\u8eab\u9632\u94b1\u5305\u7684\u7406\u7531\uff0c\u8ba9\u6211\u4f55\u4ee5\u81ea\u5c45\u3002\\n\\n\u4e00\u697c\u767d\u5403\u4e00\u5708\u5f00\u80c3\u83dc\uff0c\u4e8c\u697c\u624d\u662f\u4e3b\u573a\u3002\u90a3\u4e9b\u5356\u6d77\u9c9c\u7684\u94fa\u5b50\u90fd\u6709\u81ea\u5bb6\u53a8\u623f\u5728\u4e8c\u697c\u5904\u7406\u98df\u6750\uff0c\u6240\u4ee5\u6700\u597d\u7684\u529e\u6cd5\u5c31\u662f\u5728\u4e00\u697c\u4eb2\u81ea\u6311\u9009\u559c\u6b22\u7684\u98df\u7269\uff0c\u7136\u540e\u53bb\u4e8c\u697c\u5750\u7b49\u3002\\n\\n\u6311\u6d77\u9c9c\u672c\u6765\u5c31\u662f\u4ef6\u9ebb\u70e6\u4e8b\uff0c\u66f4\u4e0d\u8981\u8bf4\u9762\u5bf9\u8fd9\u4e48\u4e9b\u964c\u751f\u79cd\u7c7b\u3002\u9f99\u867e\u5927\u7684\u6015\u4eba\uff0c\u6d77\u9c7c\u5219\u8fc7\u4e8e\u5996\u8273\u3002\u6211\u76ef\u7740\u90a3\u6761\u84dd\u7eff\u8272\u7684\u3001\u6781\u4e0d\u771f\u5b9e\u7684\u9c7c\u770b\u4e86\u5f88\u4e45\uff0c\u786e\u5b9a\u4f3c\u66fe\u76f8\u8bc6\u3002\\n\\n![Okinawa](./img/okinawa5.jpg)\\n\\n\u51e0\u79d2\u540e\u6211\u7ffb\u770b\u4e86\u4e0b\u6628\u5929\u7684\u76f8\u518c\uff0c\u60f3\u8bc1\u5b9e\u81ea\u5df1\u7684\u731c\u60f3\u3002\u679c\u7136\uff0c\u6211\u5728\u201c\u7f8e\u3089\u6d77\u6c34\u65cf\u9928\u201d\u770b\u89c1\u8fc7\u5b83\uff0c\u6216\u5b83\u7684\u540c\u7c7b\uff0c\u8fd8\u66fe\u60ca\u53f9\u5b83\u7684\u8272\u5f69\u4eff\u4f5b\u7535\u8111\u5408\u6210\u7684\u6548\u679c\u3002\\n\\n![Okinawa](./img/okinawa6.jpg)\\n\\n\u8fd9\u4e48\u7f8e\u4e3d\u7684\u4e1c\u897f\u771f\u7684\u80fd\u5403\u5417\uff1f(\u672c\u5f53\u306b\u98df\u3079\u3089\u308c\u308b\uff1f)\\n\\n\u751f\u6d3b\u4e2d\u5927\u51e1\u8fc7\u4e8e\u7f8e\u4e3d\u5f02\u5e38\u7684\u4e1c\u897f\u90fd\u662f\u78b0\u4e0d\u5f97\u6478\u4e0d\u5f97\uff0c\u8eab\u4ef7\u8fd8\u8001\u9ad8\u3002\u5b9e\u60e0\u7684\u4eba\u8fd8\u662f\u4e70\u6761\u767d\u8272\u7684\u9bdb\u5b89\u5fc3\uff0c\u534a\u6761\u5207\u523a\u8eab\uff0c\u534a\u6761\u505a\u76d0\u70e4\u3002\u518d\u914d\u4e24\u53ea\u5927\u867e\uff0c\u548c\u534a\u53ea\u6d77\u87f9\u505a\u6c64\u3002\u5c9b\u4e0a\u5c31\u662f\u8fd9\u6837\uff0c\u770b\u4e86\u597d\u591a\u9c7c\uff0c\u5403\u4e86\u597d\u591a\u9c7c\u3002\\n\\n![Okinawa](./img/okinawa7.jpg)\\n\\n## \u55dc\u751c\u8005\u72ec\u6b22\\n\u201c\u89c9\u4e0d\u89c9\u5f97\u8fd9\u91cc\u5f88\u50cf\u67d0\u4e2a\u5730\u65b9\uff1f\u201d\\n\\n\u201c\u55ef...\u9f99\u732b\uff1f\u5409\u535c\u529b\uff1f\u201d\\n\\n\u201c\u5bf9\uff0c\u53bb\u770b\u770b\u80fd\u4e0d\u80fd\u627e\u51fa\u6765\u4e00\u53ea\u3002\u201d\\n\\n![Okinawa](./img/okinawa8.jpg)\\n\\n\u6b8b\u7834\u7684\u5730\u65b9\u4e00\u65e6\u6742\u8349\u4e1b\u751f\u5012\u53cd\u800c\u751f\u51fa\u4e00\u79cd\u4e0d\u5f97\u4e86\u7684\u795e\u79d8\u611f\uff0c\u4e5f\u5c31\u662f\u5927\u81ea\u7136\u7684\u529b\u91cf\u5427\u3002\\n\\n\u5176\u5b9e\u8fd9\u91cc\u662f\u4e00\u4e2a\u8352\u5e9f\u7684\u7a91\u5382\uff0c\u770b\u9057\u8ff9\u662f\u66fe\u70e7\u8fc7\u4e0d\u5c11\u9676\u5668\u7684\u6837\u5b50\u3002\u65c1\u8fb9\u66f2\u5f84\u901a\u5e7d\u7684\u5c0f\u8857\u53eb\u300c\u58fa\u5c4b\u300d\uff0c\u6240\u6709\u7684\u5c0f\u5e97\u90fd\u5356\u4e0d\u540c\u98ce\u683c\u7684\u624b\u5236\u9676\u5668\uff0c\u7528\u4e8e\u98df\u5668\u3001\u5bb9\u5668\u3001\u6216\u88c5\u9970\uff0c\u6709\u4e0d\u5bf9\u79f0\u7684\u3001\u7c97\u7cd9\u7684\u3001\u4e0a\u8fc7\u91c9\u7684\uff0c\u4f46\u6bcf\u4e00\u4ef6\u90fd\u72ec\u4e00\u65e0\u4e8c\uff0c\u4e0d\u5c11\u8fd8\u90fd\u662f\u5b64\u54c1\u3002\\n\\n![Okinawa](./img/okinawa9.jpg)\\n\\n\u6240\u6709\u7684\u5c0f\u5e97\u8fd8\u6709\u53e6\u4e00\u4e2a\u5171\u540c\u70b9\uff0c\u5c31\u662f\u4ed6\u4eec\u90fd\u5728\u4e0d\u7ea6\u800c\u540c\u5730\u64ad\u653e\u540c\u4e00\u79cd\u7c7b\u578b\u7684\u97f3\u4e50\uff0c\u4e0d\u7ba1\u662f\u6765\u81ea\u4e8e\u300a\u5e7d\u7075\u516c\u4e3b\u300b\u3001\u300a\u98ce\u4e4b\u8c37\u300b\u8fd8\u662f\u300a\u5929\u7a7a\u4e4b\u57ce\u300b\uff0c\u679c\u7136\uff0c\u5168\u90fd\u662f\u5409\u535c\u529b\u7684\u97f3\u4e50\u3002\u6211\u5c31\u8bf4\u6211\u4eec\u7684\u7b2c\u516d\u611f\u591f\u654f\u9510\uff0c\u90a3\u8001\u7a91\u5b50\u4e00\u770b\u5c31\u50cf\u662f\u9f99\u732b\u4f4f\u8fc7\u7684\u3002\\n\\n![Okinawa](./img/okinawa10.jpg)\\n\\n\u9f99\u732b\u663e\u7136\u4e0d\u662f\u4fd7\u4eba\u80fd\u8f7b\u6613\u53d1\u73b0\u7684\uff0c\u4f46\u6211\u53d1\u73b0\u4e86\u4e00\u7a9d\u5c0f\u732b\uff01\\n\\n\u5176\u4e2d\u6709\u4e09\u80de\u80ce\uff0c\u65c1\u82e5\u65e0\u4eba\u5730\u6253\u6eda\uff0c\u800c\u90a3\u53ea\u603b\u662f\u5bf9\u6211\u659c\u773c\uff0c\u8b66\u89c9\u6027\u660e\u663e\u66f4\u9ad8\u7684\uff0c\u4e5f\u8bb8\u662f\u732b\u5988\u3002\\n\\n![Okinawa](./img/okinawa11.jpg)\\n\\n\u663e\u7136\u6211\u592a\u4e13\u6ce8\u4e86\uff0c\u800c\u6ca1\u6709\u6ce8\u610f\u5230\u65c1\u8fb9\u7684\u82b1\u76c6\u91cc\u8fd8\u6709\u4e00\u53ea\u9ed1\u732b\u3002\u4ed6\u770b\u6837\u5b50\u50cf\u5361\u4f4f\u4e86\uff0c\u4e5f\u6216\u8bb8\u5c31\u662f\u592a\u8212\u670d\uff0c\u5e76\u4e0d\u60f3\u51fa\u6765\u3002\\n\\n![Okinawa](./img/okinawa12.jpg)\\n\\n\u56e0\u7740\u8fd9\u7fa4\u732b\uff0c\u6211\u624d\u53d1\u73b0\u4e86\u732b\u7684\u4e3b\u4eba\u548c\u4e3b\u4eba\u7684\u5c0f\u5e97\uff0c\u90a3\u662f\u4e00\u4e2a\u5356\u9676\u5668\u7684\u5496\u5561\u9986\u3002\u5e97\u5185\u65e0\u4eba\uff0c\u552f\u6709\u5bb6\u4e3b\uff0c\u65e0\u4eba\u55a7\u6270\uff0c\u7a83\u559c\u4e4b\u3002\u573a\u5730\u771f\u7684\u4e0d\u5927\uff0c\u95e8\u53c8\u5c0f\uff0c\u50cf\u4e2a\u5c71\u6d1e\u4e00\u6837\u3002\u6211\u4eec\u8981\u4e86\u5496\u5561\u548c\u70e4\u677e\u997c\uff0c\u4e3b\u4eba\u8bf4\u8fd9\u662f\u7279\u5236\u7684\uff0c\u6211\u60f3\u8fd9\u997c\u7684\u989c\u8272\u6709\u70b9\u6df1\uff0c\u539f\u6765\u662f\u9ed1\u7cd6\u7684\u539f\u56e0\u3002\u8fd9\u5c31\u662f\u4e86\uff0c\u51b2\u7ef3\u9ed1\u7cd6\u554a\uff0c\u600e\u4e48\u80fd\u5fd8\u4e86\u8fd9\u4e2a\u540d\u7269\u3002\\n\\n![Okinawa](./img/okinawa13.jpg)\\n\\n\u6211\u4e00\u6fc0\u52a8\u53c8\u5fd8\u4e86\u8fd9\u4e2a\u5e97\u53eb\u4ec0\u4e48\u540d\u5b57\uff0c\u6709\u6ca1\u6709\u540d\u5b57\u90fd\u4e0d\u786e\u5b9a\u3002\u4f46\u5982\u679c\u5230\u4e86\u300c\u58fa\u5c4b\u300d\u5e94\u8be5\u662f\u4e0d\u4f1a\u9519\u8fc7\u7684\uff0c\u56e0\u4e3a\u90a3\u7a9d\u732b\u4e00\u5b9a\u8fd8\u5b88\u7740\u3002\\n\\n## \u5c81\u6708\u5e38\u76f8\u4f3c\\n\u5f53\u6211\u66fe\u7ecf\u88ab\u544a\u77e5\u300c\u4e00\u671f\u4e00\u4f1a\u300d\u8fd9\u4e2a\u8bcd\u65f6\uff0c\u6ca1\u60f3\u5230\u8fd9\u662f\u4e2a\u542b\u4e49\u6df1\u523b\u7684\u7ea6\u5b9a\u3002\\n\\n\u5b83\u6e90\u81ea\u8336\u9053\u672f\u8bed\uff0c\u5373\u53c2\u52a0\u8336\u9053\u4f1a\u7684\u4e3b\u5ba2\u7686\u5e94\u8bda\u610f\uff0c\u8981\u60f3\u5230\u8fd9\u673a\u4f1a\u5728\u4e00\u751f\u4e2d\u53ea\u6709\u4e00\u6b21\u3002\u6bd5\u7adf\u53e4\u4eba\u4ee5\u8336\u4f1a\u53cb\uff0c\u4ea4\u901a\u4e0d\u4fbf\uff0c\u53cd\u800c\u5904\u5904\u73cd\u60dc\u3002\u6240\u4ee5\u4e00\u671f\u4e00\u4f1a\u7684\u8336\u9053\uff0c\u53ef\u4e0d\u5c31\u662f\u4e00\u751f\u4e00\u6b21\u7684\u7f18\u5206\u3002\\n\\n\u201c\u6211\u4e00\u5b9a\u4f1a\u5f88\u60f3\u4f60\u7684\u3002\u201d \u9001\u81f3\u5b89\u68c0\uff0c\u6211\u4eec\u7684\u822a\u73ed\u76f8\u5dee\u51e0\u5c0f\u65f6\u3002\\n\\n\u201c\u6211\u4e0d\u60f3\uff0c\u603b\u6dfb\u4e71\u3002\u201d\\n\\n\u201c\u4f60\u8bf4\u4e0b\u6b21\u8be5\u53bb\u54ea\u91cc\u89c1\u4f60\u5462\uff1f\u201d\\n\\n\u201c\u5929\u4e0b\u6211\u5949\u966a\uff0c\u4f46\uff0c\u8bf7\u4e00\u5b9a\u4e00\u5b9a\u5e26\u4e0a\u6709\u6548\u671f\u4ee5\u5185\u7684\u62a4\u7167\u597d\u5417 \uff1f\uff01\u201d\\n\\n\u6211\u59cb\u7ec8\u79c9\u6027\u4e0d\u6539\uff0c\u5bf9\u5979\u8bf4\u8bdd\u6c38\u8fdc\u653e\u8086\u3002\u53ef\u4e0d\u662f\u4e48\uff0c\u80fd\u5728\u4e00\u8d77\u6109\u5feb\u73a9\u800d\u7684\u57fa\u7840\uff0c\u662f\u53cc\u65b9\u90fd\u6709\u6380\u684c\u5b50\u7684\u80fd\u529b\uff0c\u548c\u4e0d\u6380\u684c\u5b50\u7684\u4fee\u517b\u3002\\n\\n![Okinawa](./img/okinawa14.jpg)"},{"id":"\u4eac\u90fd\u53bb\u4eac\u90fd\u6f2b\u6b65\u4f4f\u80f6\u56ca\u5403\u6ce1\u996d","metadata":{"permalink":"/kilimanjaro/\u4eac\u90fd\u53bb\u4eac\u90fd\u6f2b\u6b65\u4f4f\u80f6\u56ca\u5403\u6ce1\u996d","editUrl":"https://github.com/jing-gu/kilimanjaro/blog/2018/2018-02-21-\u4eac\u90fd\u53bb\u4eac\u90fd\u6f2b\u6b65\u4f4f\u80f6\u56ca\u5403\u6ce1\u996d.md","source":"@site/blog/2018/2018-02-21-\u4eac\u90fd\u53bb\u4eac\u90fd\u6f2b\u6b65\u4f4f\u80f6\u56ca\u5403\u6ce1\u996d.md","title":"\u4eac\u90fd | \u53bb\u4eac\u90fd\u6f2b\u6b65\uff0c\u4f4f\u80f6\u56ca\u5403\u6ce1\u996d","description":"Kyoto","date":"2018-02-21T00:00:00.000Z","tags":[{"inline":false,"label":"\u65c5\u884c","permalink":"/kilimanjaro/tags/\u65c5\u884c","description":"\u65c5\u884c tag description"},{"inline":true,"label":"\u4eac\u90fd","permalink":"/kilimanjaro/tags/\u4eac\u90fd"}],"readingTime":12.17,"hasTruncateMarker":false,"authors":[],"frontMatter":{"slug":"\u4eac\u90fd\u53bb\u4eac\u90fd\u6f2b\u6b65\u4f4f\u80f6\u56ca\u5403\u6ce1\u996d","title":"\u4eac\u90fd | \u53bb\u4eac\u90fd\u6f2b\u6b65\uff0c\u4f4f\u80f6\u56ca\u5403\u6ce1\u996d","tags":["\u65c5\u884c","\u4eac\u90fd"],"date":"2018-02-21T00:00:00.000Z"},"unlisted":false,"prevItem":{"title":"\u4e00\u57ce\u4e00\u5473\uff0c\u4e00\u671f\u4e00\u4f1a","permalink":"/kilimanjaro/\u4e00\u57ce\u4e00\u5473\u4e00\u671f\u4e00\u4f1a"},"nextItem":{"title":"\u9999\u6e2f | \u7e41\u534e\u770b\u5c3d\uff0c\u6700\u7f8e\u4eba\u4e0d\u77e5","permalink":"/kilimanjaro/\u9999\u6e2f\u7e41\u534e\u770b\u5c3d\u6700\u7f8e\u4eba\u4e0d\u77e5"}},"content":"![Kyoto](./img/kyoto1.jpg)\\n\\n\u4eac\u90fd\uff0c\u662f\u5178\u578b\u7684\u300c\u53e4\u3044\u753a\u300d\u3002\u5f98\u5f8a\u4e8e\u4e00\u5c4b\u4e00\u74e6\u4e4b\u95f4\u603b\u7981\u4e0d\u4f4f\u8ba9\u4eba\u8054\u60f3\u4e0b\u4e00\u4e2a\u8f6c\u89d2\u4f1a\u4e0d\u4f1a\u8d70\u51fa\u4e00\u4e2a\u827a\u5993\u3002\u73b0\u5728\u5e94\u8be5\u4e0d\u592a\u53ef\u80fd\u4f1a\u6709\u4e86\uff0c\u90a3\u4e9b\u5728\u300c\u82b1\u898b\u5c0f\u8def\u300d\u4e0a\u7684\u60ca\u9e3f\u4e00\u77a5\uff0c\u53ef\u80fd\u90fd\u662f\u6e38\u5ba2\u4eec\u5728cosplay\u3002\\n\\n\u4ece\u82b1\u898b\u5c0f\u8def\u5230\u300c\u4e8c\u5e74\u5742\u300d\u300c\u4e09\u5e74\u5742\u300d\u76f4\u5230\u300c\u6e05\u6c34\u5bfa\u300d\uff0c\u662f\u6700\u5177\u4eac\u90fd\u98ce\u5473\u7684\u6e38\u5ba2\u6253\u5361\u96c6\u4e2d\u5730\u3002\u8fd9\u91cc\u786e\u5b9e\u6709\u5f88\u7f8e\u7684\u53e4\u98ce\uff0c\u4f46\u8981\u6765\u7684\u65e9\uff0c\u53ea\u6709\u65e9\u6668\u4e03\u70b9\u5de6\u53f3\u7a7a\u65f7\u7684\u77f3\u677f\u8def\u624d\u597d\u770b\uff0c\u518d\u665a\u4e24\u4e2a\u5c0f\u65f6\u53ef\u80fd\u5c31\u8981\u6324\u6210\u5357\u9523\u9f13\u5df7\u4e86\u3002\\n\\n![Kyoto](./img/kyoto2.jpg)\\n\\n![Kyoto](./img/kyoto3.jpg)\\n\\n\u4e0d\u77e5\u9053\u4f60\u6709\u6ca1\u6709\u8fd9\u6837\u7684\u611f\u89c9\uff0c\u5728\u4e00\u7247\u53e4\u6734\u4e4b\u4e2d\uff0c\u5982\u679c\u7a81\u7136\u6709\u4e00\u4e2a\u73b0\u4ee3\u611f\u7684\u5143\u7d20\u95ef\u5165\uff0c\u4f1a\u4ea7\u751f\u4e00\u79cd\u8bf1\u4eba\u7684\u53cd\u5dee\u611f\u4fc3\u4f7f\u4eba\u4e00\u63a2\u7a76\u7adf\uff0c\u6bd4\u5982\u5f00\u5728\u300c\u4e8c\u5e74\u5742\u300d\u7684\u661f\u5df4\u514b\u3002\u8fd9\u91cc\uff0c\u6807\u5fd7\u6027\u7684\u9ed1\u767d\u7eff\u53d8\u6210\u4e86\u539f\u6728\u8272\uff1b\u8fd9\u91cc\uff0c\u6c99\u53d1\u5ea7\u6905\u6362\u6210\u4e86\u69bb\u69bb\u7c73\uff1b\u8fd9\u91cc\uff0c\u4eba\u4eec\u76d8\u817f\u7aef\u5750\u5728\u77ee\u684c\u8fb9\u559d\u5496\u5561\uff1b\u7136\u800c\uff0c\u4e0d\u7ba1\u5671\u5934\u6253\u5f97\u591a\u8db3\uff0c\u4e5f\u6539\u53d8\u4e0d\u4e86\u661f\u5df4\u514b\u96be\u559d\u7684\u4e8b\u5b9e\u3002\\n\\n![Kyoto](./img/kyoto4.jpg)\\n\\n![Kyoto](./img/kyoto5.jpg)\\n\\n\u4eba\u4eec\u559c\u6b22\u4ece\u5404\u4e2a\u89d2\u5ea6\u53bb\u6bd4\u8f83\u6771\u4eac\u548c\u4eac\u90fd\uff0c\u4e0d\u4ec5\u662f\u6e38\u5ba2\uff0c\u65e5\u672c\u4eba\u81ea\u5df1\u4e5f\u4e60\u60ef\u6027\u5730\u4e1c\u897f\u4e24\u65b9\u4e92\u603c\uff0c\u7c7b\u4f3c\u4e8e\u56fd\u4eba\u4eca\u5929\u7684\u5317\u4eac\u4e0a\u6d77\u9488\u950b\u76f8\u5bf9\uff0c\u4f60\u662f\u559c\u6b22\u4eac\u5473\u8fd8\u662f\u6d77\u6d3e\uff1f\u6253\u4e2a\u6bd4\u65b9\uff0c\u5982\u679c\u6771\u4eac\u7684\u4eba\u8bbe\u662f\u521d\u97f3\u672a\u6765\uff0c\u4eac\u90fd\u5c31\u662f\u5927\u548c\u629a\u5b50\u3002\u6771\u4eac\u4ec0\u4e48\u90fd\u6709\uff0c\u6709\u65f6\u8282\u594f\u5feb\u5230\u6765\u4e0d\u53ca\u6d88\u5316\uff0c\u5728\u5730\u94c1\u7ad9\uff0c\u5982\u679c\u6211\u8d70\u8def\u592a\u6162\u5c31\u4f1a\u89c9\u5f97\u5f88\u5bf9\u4e0d\u8d77\u5927\u5bb6\uff0c\u800c\u8fd9\u4e5f\u662f\u6211\u559c\u6b22\u4eac\u90fd\u7684\u4e00\u4e2a\u91cd\u8981\u539f\u56e0\uff1a\u6211\u6c38\u8fdc\u90fd\u4e0d\u4f1a\u770b\u89c1\u90a3\u4e9b\u7a7f\u6234\u6574\u9f50\u5212\u4e00\uff0c\u624b\u62ce\u516c\u6587\u5305\u7684\u6771\u4eac\u4e0a\u73ed\u65cf\uff0c\u795e\u60c5\u4e25\u8083\u800c\u53c8\u5065\u6b65\u5982\u98de\uff0c\u5982\u540c\u50f5\u5c38\u8fc7\u8857\u822c\u7684\u6d69\u6d69\u8361\u8361\u3002\\n\\n![Kyoto](./img/kyoto6.jpg)\\n\\n\u8bf4\u5230\u56fd\u9645\u8303\uff0c\u6771\u4eac\u4e00\u5b9a\u6bd4\u4eac\u90fd\u524d\u6cbf\u5f88\u591a\uff0c\u4f46\u5176\u5b9e\u4eac\u90fd\u66f4\u5438\u5f15\u897f\u65b9\u6e38\u5ba2\uff0c\u6211\u4e00\u8def\u5c31\u770b\u5230\u5f88\u591a\u6b27\u7f8e\u7684\u80cc\u5305\u5ba2\u3002\u4eac\u90fd\u6709\u4e00\u4e2a\u5730\u65b9\u5f88\u201c\u56fd\u9645\u8303\u201d\uff0c\u5b83\u6c47\u805a\u4e86\u4e16\u754c\u5404\u5730\u7684\u6e38\u5ba2\uff0c\u56ca\u62ec\u5404\u79cd\u56fd\u7c4d\uff0c\u4f46\u5b83\u4e0d\u662f Bar\uff0c\u800c\u662fCapsule Hotel\uff0c\u5c31\u662f\u5728\u65e5\u672c\u521b\u59cb\u7684\u80f6\u56ca\u65c5\u9986\u3002\u8bf4\u6765\u8fd9\u4e5f\u662f\u610f\u5916\u7684\u53d1\u73b0\uff0c\u65e5\u672c\u4f4f\u5bbf\u662f\u51fa\u4e86\u540d\u7684\u8d35\uff0c\u8981\u5728\u4eac\u90fd\u5927\u962a\u9017\u7559\u51e0\u5929\u7684\u6211\u4eec\u5fc5\u987b\u9009\u62e9\u80f6\u56ca\u65c5\u9986\uff0c\u597d\u597d\u5730\u7701\u4e86\u4e00\u628a\u94f6\u5b50\u3002\u5f53\u7136\uff0c\u806a\u660e\u7684\u80cc\u5305\u5ba2\u90fd\u9009\u62e9\u4e86\u8fd9\u6837\u7684\u65b9\u6cd5\uff0c\u6216\u8005\u8bf4\u5982\u6b64\u72ec\u7279\u7684\u4f4f\u5bbf\u4f53\u9a8c\u53cd\u800c\u66f4\u5438\u5f15\u5916\u56fd\u4eba\u3002\\n\\n\u5728\u80f6\u56ca\u65c5\u9986\uff0c\u9664\u4e86\u4e00\u4e2a\u5e8a\u94fa\u5927\u5c0f\u7684\u957f\u65b9\u4f53\u7a7a\u95f4\u662f\u5c5e\u4e8e\u4e2a\u4eba\u7684\uff0c\u4f4f\u5bbf\u533a\u4f1a\u5206\u7537\u5973\u6216\u5bb6\u5ead\u80f6\u56ca\uff0c\u5176\u4ed6\u4e00\u5207\u8bbe\u65bd\u548c\u573a\u6240\u90fd\u662f\u516c\u7528\u7684\u3002\u65e9\u6668\uff0c\u4e0d\u540c\u80a4\u8272\u7684\u4eba\u7eb7\u7eb7\u722c\u51fa\u80f6\u56ca\uff0c\u84ec\u5934\u57a2\u9762\uff0c\u7761\u773c\u60fa\u5fea\u5730\u4e92\u76f8\u95ee\u597d \'Hey.\' \'Hello.\' \u3053\u3093\u306b\u3061\u306f\u301c\uff0c\u7136\u540e\u5728\u6d17\u6f31\u533a\u76f8\u9047\uff0c\u5237\u7259\u6d17\u8138\uff0c\u5316\u5986\u5439\u5934\u53d1\uff0c\u5373\u4fbf\u662f\u8bed\u8a00\u4e0d\u901a\u7684\u4eba\u4e5f\u80fd\u81ea\u7136\u878d\u5165\uff0c\u7ba1\u7406\u597d\u81ea\u5df1\u5c31\u884c\u3002\\n\\n![Kyoto](./img/kyoto7.jpg)\\n\\n\u4e00\u5207\u90fd\u53ef\u4ee5\u516c\u7528\uff0c\u552f\u6709\u6d17\u6fa1\u8fd9\u56de\u4e8b\u513f\u662f\u897f\u65b9\u4eba\u4e0d\u80fd\u7406\u89e3\u7684\u3002\u80f6\u56ca\u65c5\u9986\u80af\u5b9a\u662f\u91c7\u7528\u516c\u5171\u6c90\u6d74\u7684\uff0c\u6211\u4eec\u5728\u300c\u56db\u6761\u300d\u9009\u4e86 Centurion Cabin&Spa \u7684\u80f6\u56ca\u65c5\u9986\uff0c\u8fd8\u662f\u5e26\u5ba4\u5185\u6e29\u6cc9\u7684\u90a3\u79cd\uff0c\u5df2\u7ecf\u518d\u597d\u4e0d\u8fc7\u4e86\u3002\u897f\u65b9\u6587\u5316\u4e2d\u6709\u5f88\u5f3a\u7684\u81ea\u6211\u9690\u79c1\u6027\uff0c\u4ece\u66f4\u8863\u5230\u6c90\u6d74\u90fd\u662f\u6709\u81ea\u5df1\u7684\u7a7a\u95f4\u7684\uff0c\u7edd\u4e0d\u4f1a\u51fa\u73b0\u53e6\u5916\u4e00\u4e2a\u5149\u7740\u8eab\u5b50\u7684\u4eba\u7ad9\u5728\u65c1\u8fb9\u3002\u5f53\u4e9a\u6d32\u59d1\u5a18\u4eec\u5728\u66f4\u8863\u5ba4\u4e00\u8fb9\u8c08\u7b11\u98ce\u751f\u4e00\u8fb9\u723d\u5feb\u5229\u7d22\u5730\u8131\u8863\u670d\u51c6\u5907\u53bb\u6d17\u6fa1\u65f6\uff0c\u8fdb\u6765\u7684\u6bcf\u4e00\u4e2a\u897f\u65b9\u4eba\u4e0d\u7ba1\u662f\u5e74\u8f7b\u5973\u5b69\u8fd8\u662f\u4e2d\u5e74\u5987\u5973\u90fd\u662f\u76ee\u77aa\u53e3\u5446\u3002\\n\\n\u4e3a\u4ec0\u4e48\u5462\uff0c\u4e9a\u6d32\u662f\u5178\u578b\u7684\u96c6\u4f53\u4e3b\u4e49\u793e\u4f1a\uff0c\u50ac\u751f\u51fa\u516c\u5171\u6fa1\u5802\u7684\u6587\u5316\u5e76\u4e0d\u5947\u602a\uff1b\u800c\u897f\u65b9\u4ece\u6765\u90fd\u662f\u4e2a\u4eba\u4e3b\u4e49\uff0c\u4e0d\u5e72\u6d89\u522b\u4eba\u4e5f\u4e0d\u613f\u88ab\u4fb5\u72af\uff0c\u867d\u7136\u90fd\u662f\u5973\u4eba\u561b\uff0c\u4f46\u9762\u5bf9\u522b\u4eba\u7684\u88f8\u4f53\u65f6\uff0c\u6211\u8fd8\u662f\u770b\u51fa\u4e86\u5979\u4eec\u5446\u82e5\u6728\u9e21\u7684\u795e\u60c5\u4e0b\u6d45\u6d45\u7684\u7f9e\u6da9\uff0c\u4e0d\u597d\u610f\u601d\u66b4\u9732\u81ea\u5df1\u7684\u540c\u65f6\u4e5f\u5bb3\u7f9e\u770b\u89c1\u522b\u4eba\u3002\\n\\n\u8fd9\u4e9b\u4e0d\u81ea\u7136\u7684\u5c34\u5c2c\u548c\u7f9e\u6da9\u90fd\u662f\u77ac\u95f4\u4ea7\u751f\u5e76\u7acb\u523b\u6d88\u5931\u7684\uff0c\u6bd5\u7adf\u8fd9\u91cc\u5c31\u662f\u4e9a\u6d32\uff0c\u5728\u522b\u4eba\u7684\u9886\u5730\u4e0a\u8c01\u4e5f\u4e0d\u613f\u610f\u88ab\u5f53\u6210\u53e6\u7c7b\u3002\u6b27\u7f8e\u4eba\u5927\u90fd\u6ca1\u641e\u6e05\u695a\u72b6\u51b5\uff0c\u4f4e\u7740\u5934\u81ea\u4e2a\u513f\u8131\u8863\u670d\uff0c\u51e0\u4e2a\u5927\u5927\u54a7\u54a7\u7684\u7f8e\u56fd\u59d1\u5a18\u95ee What should I do\uff1f\u610f\u601d\u662f\u5230\u5e95\u8981\u548b\u6574\uff1f\u6211\u4eec\u8bf4\u8863\u670d\u8131\u4e86\u653e\u8fdb\u81ea\u5df1\u7684Locker\u5c31\u53ef\u4ee5\u76f4\u63a5\u8fdb\u53bb\u6d17\u6fa1\u4e86\u3002\u5370\u8c61\u4e2d\u7279\u522b\u6df1\u7684\u662f\u4e00\u4e2a\u4e2d\u5e74\u7684\u6b27\u6d32\u5973\u4eba\u5728\u4e00\u65c1\uff0c\u8863\u670d\u8131\u5230\u4e00\u534a\u8fd8\u662f\u89c9\u5f97\u5f88\u53d8\u626d\uff0c\u56de\u5934\u95ee\uff1a\'Can you tell me how does it work?\'\\n\\n\u5bf9\u8fd9\u53e5\u8bdd\u6211\u8bb0\u5f97\u5f88\u6e05\u695a\uff0c\u56e0\u4e3a\u8fd9\u4e2a\u63aa\u8f9e\u592a\u4e0d\u5bfb\u5e38\u4e86\uff0c\u4e0d\u4ec5\u4ec5\u5728\u95ee\uff1a\u6211\u8be5\u600e\u4e48\u505a\uff1f\u8fd8\u5728\u8d28\u7591\uff1a\u8fd9\u5230\u5e95\u662f\u4e2a\u4ec0\u4e48\u6d41\u7a0b\uff1f\u62ff\u7740\u8863\u670d\u8ff7\u60d1\u5730\u770b\u7740\u50a8\u7269\u67dc\u7684\u5979\u4e0d\u6562\u76f8\u4fe1\uff0c\u4e00\u8fdb\u6765\u5c31\u5728\u8fd9\u91cc\u8131\u5b8c\u4e48\uff1f\u6211\u597d\u50cf\u8bf4\u4e86 take it all\uff0cjust be naked \u4e4b\u7c7b\u7684\u76f4\u63a5\u6697\u793a\uff0c\u4f46\u662f\u8bdd\u7cd9\u7406\u4e0d\u7cd9\uff0c\u6211\u60f3\u544a\u8bc9\u5979\uff1a\u5bf9\u6ef4\uff0c\u4f60\u8981\u5728\u8fd9\u91cc\u8131\u5149\u5149\u54df\uff5e\\n\\n![Kyoto](./img/kyoto8.jpg)\\n\\n\u4e0d\u80fd\u514d\u4fd7\u5730\uff0c\u6211\u4eec\u8fd8\u662f\u8981\u8c08\u8c08\u5403\u3002\u5728\u4eac\u90fd\uff0c\u8fd8\u662f\u5148\u4e0d\u8981\u8003\u8651\u62c9\u9762\u5496\u55b1\u70b8\u732a\u6392\u7b49\u666e\u901a\u7684\u65e5\u6599\u4e86\uff0c\u53bb\u5403\u8336\u6ce1\u996d\u5427\u3002\u300c\u304a\u8336\u6f2c\u3051\u300d\u8336\u6ce1\u996d\u672c\u662f\u5e73\u6c11\u6599\u7406\uff0c\u5374\u5728\u4eac\u90fd\u7684\u70d8\u6258\u4e0b\u88ab\u63d0\u5347\u5f97\u903c\u683c\u6ee1\u6ee1\uff0c\u5c31\u597d\u6bd4\u61c2\u8425\u9500\u7684\u7d20\u98df\u9986\u53cd\u800c\u53ef\u4ee5\u7ecf\u8425\u5730\u66f4\u663e\u9ad8\u7ea7\u3002\\n\\n![Kyoto](./img/kyoto9.jpg)\\n\\n\u8336\u6ce1\u996d\u7b80\u5355\uff0c\u7cbe\u9ad3\u5374\u5728\u8336\uff0c\u70ed\u8336\u5148\u6ce1\u4e00\u5206\u949f\uff0c\u518d\u6162\u6162\u6d47\u5728\u7c73\u996d\u4e0a\u3002\u6bcf\u6b21\u7c73\u996d\u6700\u597d\u4e03\u5206\u6ee1\uff0c\u8fd9\u6837\u53ef\u4ee5\u5403\u4e24\u904d\uff0c\u4e00\u6b21\u714e\u8336\uff0c\u4e00\u6b21\u9752\u8336\u3002\u6771\u4eac\u4eba\u559c\u6b22\u52a0\u4e0a\u5929\u5987\u7f57\u3001\u91d1\u67aa\u9c7c\u6216\u9c91\u9c7c\u7b49\u8c6a\u534e\u7684\u98df\u6750\uff0c\u8fd8\u8bb0\u5f97\u300a\u6df1\u591c\u98df\u5802\u300b\u91cc\u7684\u8336\u6ce1\u996d\u4e09\u59d0\u59b9\u5417\uff1f\u201c\u8001\u677f\u301c\u4e4c\u6885\uff0c\u9c91\u9c7c\uff0c\u9cd5\u9c7c\u5b50\u3002\u201d \u5f80\u5f80\u4eb2\u5207\u800c\u6e29\u67d4\u7684\u8f7b\u98df\u6700\u80fd\u6e29\u6696\u75b2\u52b3\u7684\u80c3\u3002\\n\\n\u5728\u4eac\u90fd\uff0c\u4e0d\u600e\u4e48\u7528\u8364\u7684\uff0c\u7528\u7684\u53ea\u662f\u6e0d\u7269\u3002\u300c\u4e09\u5e74\u5742\u300d\u7684\u963f\u53e4\u5c4b\u662f\u81ea\u52a9\u9910\u611f\u89c9\u7684\u8336\u6f2c\u5c4b\uff0c\u53ea\u8981\u4f60\u5403\u5f97\u4e0b\uff0c\u53ef\u4ee5\u4e00\u7897\u4e00\u7897\u5730\u76db\u996d\uff0c\u5343\u5947\u767e\u602a\u7684\u9171\u83dc\u6ce1\u83dc\u54b8\u83dc\u4e5f\u662f\u4efb\u610f\u642d\u914d\u3002\\n\\n\u4eac\u90fd\u4eba\u597d\u50cf\u7279\u522b\u559c\u6b22\u814c\u6e0d\u8fc7\u7684\u98df\u7269\uff0c\u4ec0\u4e48\u98df\u6750\u90fd\u53ef\u4ee5\u62ff\u6765\u6e0d\u4e00\u6e0d\uff0c\u841d\u535c\u725b\u84a1\u6e0d\u4e00\u6e0d\uff0c\u5c71\u836f\u9ec4\u74dc\u6e0d\u4e00\u6e0d\uff0c\u6a31\u82b1\u4e5f\u8981\u6e0d\u4e00\u6e0d\u3002\u7947\u5712\u9644\u8fd1\u5f00\u7740\u597d\u591a\u5bb6\u201c\u4eac\u6e0d\u7269\u201d\u7684\u8001\u94fa\uff0c\u6bcf\u8def\u8fc7\u4e00\u5bb6\u6211\u4eec\u90fd\u8981\u95ef\u8fdb\u53bb\u8bd5\u5403\u51e0\u53e3\uff0c\u4e00\u8def\u4e0b\u6765\u5634\u5df4\u90fd\u5c1d\u54b8\u4e86\u3002 \u8981\u4e0d\u662f\u5473\u513f\u7565\u5927\uff0c\u98de\u673a\u4e0d\u8ba9\u5e26\uff0c\u6211\u53ef\u80fd\u4f1a\u80cc\u56de\u6765\u4e00\u7f50\u54b8\u83dc\u3002\\n\\n![Kyoto](./img/kyoto10.jpg)\\n\\n\u6e0d\u7269\u5403\u54b8\u4e86\uff0c\u81ea\u7136\u5c31\u60f3\u627e\u751c\u98df\u3002\u5728\u4eac\u90fd\uff0c\u300c\u3082\u3061\u300d\u548c\u300c\u56e3\u5b50\u300d\u90fd\u683c\u5916\u5e38\u89c1\uff0c\u90fd\u662f\u4e9b\u53d8\u7740\u82b1\u6837\u7684\u7cef\u7c73\u56e2\u5b50\u7c7b\u98df\u7269\uff0c\u6211\u660e\u663e\u611f\u89c9\u51fa\u81ea\u5df1\u78b3\u6c34\u5316\u5408\u7269\u7684\u6444\u5165\u91cf\u6bd4\u5728\u4e1c\u4eac\u9ad8\u4e86\u5f88\u591a\u3002\\n\\n![Kyoto](./img/kyoto11.jpg)\\n\\n\u9664\u4e86\u5403\uff0c\u4eac\u90fd\u503c\u5f97\u53bb\u7684\u5730\u65b9\u4e5f\u662f\u591a\u5f97\u8981\u5217\u6e05\u5355\u3002\u653b\u7565\u699c\u9996\u5e38\u6709\uff1a\u6e05\u6c34\u5bfa\uff0c\u91d1\u9601\u5bfa\uff0c\u4e8c\u6761\u57ce\uff0c\u4f0f\u89c1\u7a3b\u8377\uff0c\u516b\u5742\u795e\u793e\uff0c\u7947\u5712\uff0c\u5148\u6597\u753a\uff0c\u9e2d\u5ddd\uff0c\u5c31\u4e0d\u5199\u4e86\uff0c\u9a6c\u8702\u7a9d\u4e00\u5b9a\u6bd4\u6211\u5199\u5f97\u597d\u301c \u4e0d\u5982\u8bf4\u4e00\u4e2a\u6e21\u6708\u6865\u3002\\n\\n![Kyoto](./img/kyoto12.jpg)\\n\\n\u6e21\u6708\u6865\u672c\u8eab\u5c31\u662f\u4e00\u4e2a\u6ca1\u4ec0\u4e48\u7279\u70b9\u7684\u6728\u7ed3\u6784\u6865\uff0c\u6211\u53ea\u662f\u5355\u7eaf\u7684\u559c\u6b22\u8fd9\u4e2a\u540d\u5b57\uff0c\u800c\u4e14\u8fd8\u662f\u770b\u67ef\u5357\u770b\u51fa\u6765\u7684\uff0c\u6700\u65b0\u7684\u5267\u573a\u7248\u4e0d\u662f\u300a\u5510\u7ea2\u7684\u604b\u6b4c\u300b\u4e48\uff0c\u7247\u5c3e\u66f2\u5c31\u662f\u4ed3\u6728\u9ebb\u8863\u7684\u6e21\u6708\u6865\u5462\u3002\u770b\u8fc7\u5267\u573a\u7248\u7684\u8bdd\uff0c\u5c31\u4e00\u5b9a\u77e5\u9053\u6e21\u6708\u6865\u662f\u89c2\u8d4f\u7ea2\u53f6\u7684\u7edd\u4f73\u4e4b\u5730\uff0c\u79cb\u5929\u7684\u8bdd\u4e00\u5b9a\u5f88\u7f8e\uff0c\u53ef\u80fd\u8fd8\u4f1a\u5927\u585e\u8f66\u5427\u3002\\n\\n![Kyoto](./img/kyoto13.jpg)\\n\\n\u6e21\u6708\u6865\u5c5e\u4e8e\u5c9a\u5c71\uff0c\u5de6\u8fb9\u5c31\u662f\u5d6f\u5ce8\u91ce\uff0c\u62cd\u300a\u5367\u864e\u85cf\u9f99\u300b\u7684\u5730\u65b9\u3002\u5c9a\u5c71\u867d\u8fdc\uff0c\u79bb\u4eac\u90fd\u5e02\u5185\u6709\u70b9\u8ddd\u79bb\uff0c\u5374\u662f\u4e00\u4e2a\u503c\u5f97\u6d88\u8017\u4e00\u5929\u7684\u5730\u65b9\u3002\u53ef\u4ee5\u5750\u5750\u5d6f\u5ce8\u91ce\u5c0f\u706b\u8f66(\u30c8\u30ed\u30c3\u30b3\u5217\u8eca)\uff0c\u53ef\u4ee5\u5750\u4e0b\u5403\u548c\u83d3\u5b50\uff0c\u53ef\u4ee5\u901b\u901b\u53ef\u7231\u7684\u6742\u8d27\u5e97\u3002\\n\\n![Kyoto](./img/kyoto14.jpg)\\n\\n![Kyoto](./img/kyoto15.jpg)\\n\\n\u6700\u540e\uff0c\u6211\u8981\u5b89\u5229\u4e00\u4e2a\u4e70\u624b\u529e\u7684\u597d\u5e97\u300c\u3088\u30fc\u3058\u3084\u300d\u6216\u8005YOJIYA\u3002\u8fd9\u4e2a\u540d\u5b57\u5bf9\u4e8e\u5f88\u591a\u4eba\u6765\u8bf4\u8fd8\u5f88\u964c\u751f\uff0c\u4f46\u5728\u65e5\u672c\u672c\u571f\u5374\u662f\u4e2a\u6781\u5177\u6c89\u6dc0\uff0c\u65e0\u4eba\u4e0d\u77e5\u7684\u54c1\u724c\uff0c\u5c24\u5176\u5bf9\u4e8e\u5176\u53d1\u6e90\u5730\u4eac\u90fd\u66f4\u662f\u5b9d\u7269\u822c\u7684\u5b58\u5728\u3002\\n\\n![Kyoto](./img/kyoto16.jpg)\\n\\n\u56e0\u4e3a\u5b83\u53ea\u9650\u4e8e\u4eac\u90fd\uff0c\u5730\u57df\u9650\u5236\u6027\u5c31\u662fYOJIYA\u6700\u5927\u7684\u7279\u8272\u4e86\uff0c\u5728\u7947\u5712\u3001\u6e05\u6c34\u3001\u5d50\u5c71\u7b49\u90fd\u53ef\u4ee5\u627e\u5230\u3002\u6240\u4ee5\uff0c\u8fd9\u4efd\u793c\u7269\u8db3\u4ee5\u4ee3\u8868\u4eac\u90fd\u7684\u98ce\u60c5\uff0c\u5173\u952e\uff0c\u5b83\u53ea\u662fMuji\u7684\u4ef7\u683c\uff0c\u5374\u66f4\u6709\u4f60\u60f3\u8981\u7684\u4e2a\u6027\u3002\\n\\n\u4eac\u90fd\u65e2\u7136\u662f\u827a\u5993\u6587\u5316\u6d53\u90c1\u7684\u5730\u65b9\uff0cYOJIYA\u53ef\u60f3\u800c\u77e5\u662f\u4e00\u4e2a\u56e0\u827a\u5993\u800c\u4ea7\u751f\u7684\u5316\u5986\u54c1\u724c\u3002\u5176\u4e2d\u4ee5\u300c\u3042\u3076\u3089\u3068\u308a\u7d19\u300d\uff08\u5438\u6cb9\u9762\u7eb8\uff09\u6700\u4e3a\u51fa\u540d\uff0c\u542b\u6709\u91d1\u7b94\u6210\u5206\u7684\u5438\u6cb9\u9762\u7eb8\uff0c\u56e0\u80fd\u4f7f\u827a\u4eba\u7684\u5986\u5bb9\u6e05\u723d\u6301\u4e45\u800c\u5927\u53d7\u597d\u8bc4\u3002\u6539\u826f\u540e\u7684\u4ea7\u54c1\u50cf\u5c0f\u518c\u5b50\u4e00\u6837\u4fbf\u4e8e\u643a\u5e26\uff0c\u4ef7\u683c\u7f8e\u4e3d\uff08\u5374\u662f\u5b9e\u5728\u7684\u5438\u6cb9\u7eb8\u4e2d\u7684\u7231\u9a6c\u4ed5\u54c8\uff09\u3002\u5404\u79cd\u6cb9\u7eb8\u7684\u5b63\u8282\u9650\u5b9a\u54c1\u300c\u685c\u82b1\u300d\u300c\u67da\u5b50\u300d\u300c\u82a6\u835f\u300d\u66f4\u662f\u5907\u53d7\u5973\u6027\u9752\u7750\u3002YOJIYA\u7684\u67da\u5b50\u62a4\u5507\u818f\uff0c\u8ff7\u4f60\u82b1\u955c\uff0c\u9999\u7c89\u76d2\u4e5f\u662f\u65e2\u5b9e\u7528\u53c8\u53ef\u7231\u7684\u5c0f\u793c\u7269\u3002\\n\\n\u4e2a\u522bYOJIYA\u8fd8\u6709\u5c0f\u5496\u5561\u5e97\u53ef\u4ee5\u4f11\u61a9\uff0c\u5982\u679c\u521a\u597d\u5728\u5d50\u5c71\u3001\u94f6\u9601\u5bfa\u6216\u7947\u5712\u9644\u8fd1\uff0c\u4e0d\u5982\u8fdb\u53bb\u7a0d\u4f5c\u4f11\u606f\uff0c\u201c\u827a\u5993\u8138\u201d\u7684\u62b9\u8336\u62ff\u94c1\u662f\u5f88\u6709\u7279\u8272\u7684\u54df\u3002\\n\\n![Kyoto](./img/kyoto17.jpg)\\n\\n\u597d\u4e86\uff0c\u6700\u540e\u6446\u4e24\u5f20\u5343\u672c\u9e1f\u5c45\uff0c\u6563\u573a\u301c\\n\\n![Kyoto](./img/kyoto18.jpg)\\n\\n![Kyoto](./img/kyoto19.jpg)"},{"id":"\u9999\u6e2f\u7e41\u534e\u770b\u5c3d\u6700\u7f8e\u4eba\u4e0d\u77e5","metadata":{"permalink":"/kilimanjaro/\u9999\u6e2f\u7e41\u534e\u770b\u5c3d\u6700\u7f8e\u4eba\u4e0d\u77e5","editUrl":"https://github.com/jing-gu/kilimanjaro/blog/2018/2018-02-11-\u9999\u6e2f\u7e41\u534e\u770b\u5c3d\u6700\u7f8e\u4eba\u4e0d\u77e5.md","source":"@site/blog/2018/2018-02-11-\u9999\u6e2f\u7e41\u534e\u770b\u5c3d\u6700\u7f8e\u4eba\u4e0d\u77e5.md","title":"\u9999\u6e2f | \u7e41\u534e\u770b\u5c3d\uff0c\u6700\u7f8e\u4eba\u4e0d\u77e5","description":"Hongkong","date":"2018-02-11T00:00:00.000Z","tags":[{"inline":false,"label":"\u65c5\u884c","permalink":"/kilimanjaro/tags/\u65c5\u884c","description":"\u65c5\u884c tag description"},{"inline":true,"label":"\u9999\u6e2f","permalink":"/kilimanjaro/tags/\u9999\u6e2f"}],"readingTime":13.805,"hasTruncateMarker":false,"authors":[],"frontMatter":{"slug":"\u9999\u6e2f\u7e41\u534e\u770b\u5c3d\u6700\u7f8e\u4eba\u4e0d\u77e5","title":"\u9999\u6e2f | \u7e41\u534e\u770b\u5c3d\uff0c\u6700\u7f8e\u4eba\u4e0d\u77e5","tags":["\u65c5\u884c","\u9999\u6e2f"],"date":"2018-02-11T00:00:00.000Z"},"unlisted":false,"prevItem":{"title":"\u4eac\u90fd | \u53bb\u4eac\u90fd\u6f2b\u6b65\uff0c\u4f4f\u80f6\u56ca\u5403\u6ce1\u996d","permalink":"/kilimanjaro/\u4eac\u90fd\u53bb\u4eac\u90fd\u6f2b\u6b65\u4f4f\u80f6\u56ca\u5403\u6ce1\u996d"}},"content":"![Hongkong](./img/hongkong1.jpg)\\n\\n\u8fd9\u662f\u5e74\u524d\u7684\u6700\u540e\u4e00\u6b21\u65c5\u884c\uff0c2\u67084\u65e5\uff0c\u53bb\u9999\u6e2f\u3002\\n\\n\u636e\u8bf4\u6df1\u5733\u6e7e\u662f\u4eba\u6d41\u91cf\u6700\u5c11\u7684\u5165\u5883\u53e3\u5cb8\uff0c\u6211\u5fc3\u60f3\u53ef\u80fd\u4e0d\u7528\u7b49\u592a\u957f\u65f6\u95f4\u5427\uff0c\u4e8e\u662f\u6211\u4e2d\u5348\u4e00\u70b9\u5de6\u53f3\u5230\u8fbe\u51c6\u5907\u8fc7\u5883\u3002\u592a\u5929\u771f\u4e86\uff0c\u4e4c\u538b\u538b\u4eba\u5c71\u4eba\u6d77\uff0c\u5927\u6982\u662f\u5468\u65e5\u7684\u539f\u56e0\uff0c\u4e5f\u4e0d\u77e5\u591a\u5c11\u662f\u6e38\u5ba2\uff0c\u53c8\u6709\u591a\u5c11\u662f\u201c\u80cc\u8d27\u201d\u800c\u53bb\u3002\\n\\n\u770b\u7740\u522b\u4eba\u6210\u7fa4\u7ed3\u961f\u5730\u624b\u62ce\u5927\u53f7\u884c\u674e\u7bb1\uff0c\u591a\u7684\u4e24\u4e2a\uff0c\u987f\u65f6\u611f\u89c9\u9677\u5165\u4ee3\u8d2d\u5927\u519b\u7684\u56e2\u4f53\uff0c\u6211\u53ea\u8eab\u4e00\u4eba\u4e00\u4e2a\u5c0f\u7bb1\u5b50\uff0c\u5939\u5728\u4eba\u7fa4\u4e2d\u7565\u663e\u5355\u8584\u3002\\n\\n\u8eab\u540e\u7684\u51e0\u4e2a\u59d1\u5a18\u4e00\u76f4\u53fd\u53fd\u55b3\u55b3\u8ba8\u8bba\u63a5\u4e0b\u6765\u7684shopping\u7b49\uff0c\u6211\u6234\u4e0a\u8033\u673a\uff0c\u9ed8\u9ed8\u8ddf\u7740\u4eba\u7fa4\u5411\u524d\u632a\u6b65\u3002\u6d77\u5173\u9ebb\u6728\u5730\u67e5\u770b\u6bcf\u4e2a\u8fc7\u5ba2\u7684\u901a\u884c\u8bc1\uff0c\u4eba\u58f0\u9f0e\u6cb8\u4e2d\u6211\u7ec8\u4e8e\u8fc7\u5883...... \u8c01\u77e5\u66f4\u957f\u7684\u6392\u961f\u662f\u63a5\u4e0b\u6765\u7684\u7b49\u5927\u5df4\u3002\\n\\n![Hongkong](./img/hongkong2.jpg)\\n\\n\u65e0\u5948\u800c\u53c8\u7fd8\u9996\u671f\u5f85\uff0c\u7ec8\u4e8e\u6765\u4e86\u4e00\u8f86\u53cc\u5c42\u5df4\u58eb\uff0c\u987a\u5229\u585e\u4e0b\u4e86\u4e0d\u5c11\u4eba\u3002\u51ed\u7740\u8bb0\u5fc6\u6211\u624b\u7ed8\u4e86\u4e00\u4efd\u642d\u4e58\u5730\u56fe\uff0c\u4ece\u6df1\u5733\u6e7e\u5165\u5883\u5fc5\u987b\u5148\u5750\u63a5\u9a73\u7684\u5df4\u58eb\uff0c\u7136\u540e\u5728\u6700\u8fd1\u7684\u5143\u6717\u8f6c\u4e58\u5730\u94c1\u7ebf\u8fdb\u5165\u4e2d\u73af\u5e02\u533a\u3002\\n\\n\u5176\u5b9e\u4ece\u5929\u6c34\u56f4\u8fdb\u5165\u5143\u6717\u533a\u65f6\uff0c\u8def\u8fb9\u7684\u666f\u8272\u5c31\u5df2\u7ecf\u5f00\u59cb\u9999\u6e2f\u5473\u4e86\uff0c\u5c31\u662f\u90a3\u79cd\u9999\u6e2f\u7279\u6709\u7684\u897f\u5f0f\u4e0e\u4f20\u7edf\u7684\u6742\u5408\u611f\uff0c\u6bd4\u5982\u5723\u7ea6\u7ff0\u5929\u4e3b\u6559\u5c0f\u5b66\u4e4b\u7c7b\u7684\uff0c\u770b\u4e0a\u53bb\u662f\u4e0a\u4e16\u7eaa\u82f1\u56fd\u4eba\u6b8b\u7559\u7684\u6587\u5316\u5728\u9999\u6e2f\u672c\u571f\u5316\u540e\u7684\u4ea7\u7269\uff0c\u4e0d\u4e2d\u4e0d\u897f\u6b63\u662f\u9999\u6e2f\u3002\\n\\n\u987a\u5229\u62b5\u8fbe\u6e2f\u5927\u540e\u7acb\u523b\u653e\u4e0b\u884c\u674e\u7ee7\u7eed\u8fd4\u56de\u4e0a\u73af\u9644\u8fd1\uff0c\u548c\u73a5\u73a5\u53bb\u770b\u9999\u5948\u513f\u5728\u5143\u521b\u65b9\u7684\u5c55 Mademoiselle priv\xe9\uff0c\u8fd9\u8ba9\u6211\u4eec\u7684\u884c\u52a8\u591a\u4e86\u4e00\u4e9b\u65b9\u5411\u611f\u548c\u4f7f\u547d\u611f\u3002\u597d\u50cf\u65c5\u9014\u4e2d\u82e5\u53ea\u662f\u4e70\u73a9\u4e70\u5403\u603b\u663e\u5f97\u80a4\u6d45\u4fd7\u5957\uff0c\u82e5\u662f\u591a\u770b\u770b\u5c55\u89c8\u548c\u591a\u5143\u6587\u5316\u65b9\u9762\u7684\u4e1c\u897f\uff0c\u4eff\u4f5b\u7acb\u9a6c\u5347\u534e\u4e86\u65c5\u884c\u7684\u610f\u4e49\u3002\u8bb0\u5f97\u8c01\u544a\u8bc9\u6211\u60f3\u4e86\u89e3\u4e00\u4e2a\u57ce\u5e02\u6700\u5feb\u7684\u65b9\u6cd5\u5c31\u662f\u53bb\u5b83\u7684\u535a\u7269\u9986\uff0c\u6240\u8c13\u6587\u827a\uff0c\u4e0d\u5c31\u662f\u73a9\u4e50\u4e2d\u8fd8\u6709\u6240\u5f97\u4e48\uff1f\\n\\n\u4ece\u5143\u521b\u65b9\u51fa\u6765\u540e\u5c31\u5728\u4e0a\u73af\u9644\u8fd1\u6e9c\u8fbe\uff0c\u627e\u98df\u5403\uff0c\u6700\u5927\u7684\u611f\u89c9\u5c31\u662f\uff1a\u9999\u6e2f\u771f\u662f\u4e00\u4e2a\u63a5\u7eb3\u5e76\u878d\u5408\u5404\u7c7b\u6587\u5316\u7684\u5730\u65b9\u554a\u3002\u8857\u4e0a\u6c38\u8fdc\u90fd\u662f\u6e38\u4eba\u6bd4\u5f53\u5730\u4eba\u591a\uff0c\u897f\u65b9\u4eba\u4e0e\u4e9a\u6d32\u4eba\u6bd4\u4f8b\u6297\u8861\uff0c\u65b0\u65e7\u6587\u5316\u53cb\u597d\u76f8\u5904\uff0c\u5076\u5c14\u7565\u4e0d\u548c\u8c10\u5374\u5bf9\u6bd4\u5f3a\u70c8\uff0c\u610f\u5916\u6709\u8da3\u3002\\n\\n![Hongkong](./img/hongkong3.jpg)\\n\\n\u9999\u6e2f\u591a\u5c71\uff0c\u5730\u52bf\u5ffd\u9ad8\u5ffd\u4f4e\uff0c\u5f92\u6b65\u75b2\u52b3\u6307\u6570\u7edd\u4e0d\u4e9a\u4e8e\u65e7\u91d1\u5c71\u3002\u8001\u65e7\u7684\u8857\u9053\u4e0a\u6211\u4eec\u5ffd\u7136\u53d1\u73b0\u4e00\u5bb6\u5341\u5206\u73b0\u4ee3\u611f\u7684\u5496\u5561\u9986\uff0c\u7531\u4e8e\u5b57\u6bcd\u53d8\u5f62\u592a\u5389\u5bb3\uff0c\u6211\u7b2c\u4e00\u773c\u4ee5\u4e3a\u662fNYC\uff0c\u662fNew York City\u7684\u7f29\u5199\u4e48\uff1f\u624d\u4e0d\u662f\uff0c\u662fNOC\uff0c\u50cf\u4e0d\u50cf\u4e09\u53ea\u5496\u5561\u676f\u7684\u4e0d\u540c\u6446\u653e\u9020\u578b\uff1f\u5e97\u5185\u767d\u7070\u7684\u4e3b\u8272\u8c03\u6781\u5177\u7a7a\u95f4\u611f\uff0c\u5496\u5561\u56e0\u4e0a\u763e\u8005\u6beb\u4e0d\u72b9\u8c6b\u8981\u8fdb\u53bb\u6253\u5361\u3002\\n\\n![Hongkong](./img/hongkong4.jpg)\\n\\n\u6709\u8da3\u7684\u662f\uff0c\u5982\u6b64\u73b0\u4ee3\u611f\u7206\u68da\u7684\u5730\u65b9\uff0c\u5bf9\u9762\u6070\u662f\u4f20\u7edf\u63a5\u5730\u6c14\u8001\u5e97\u201c\u4e5d\u8bb0\u725b\u8169\u201d\uff0c\u867d\u4e0d\u5e78\u90a3\u5929\u5468\u65e5\u5e97\u5bb6\u5173\u95e8\uff0c\u82e5\u662f\u8425\u4e1a\u4e5f\u5fc5\u5b9a\u6392\u961f\u5230\u5fc3\u7126\u3002\\n\\n\u7ee7\u7eed\u4e00\u8def\u89c5\u98df\u4e00\u8def\u89c2\u5bdf\uff0c\u53d1\u73b0\u5728\u9999\u6e2f\u9664\u4e86\u82f1\u4f26\u6587\u5316\u7279\u522b\u53d7\u6b22\u8fce\u4e4b\u5916\uff0c\u53e6\u4e00\u79cd\u7279\u53d7\u5f85\u89c1\u7684\u5c31\u662f\u65e5\u672c\u996e\u98df\uff0c\u4ece\u9ad8\u7ea7\u6599\u7406\u4ead\u5230\u62c9\u9762\u5bff\u53f8\uff0c\u5404\u79cd\u65e5\u672c\u98ce\u5473\u5728\u5c0f\u5c0f\u7684\u5730\u6bb5\u4e0a\u53cd\u590d\u51fa\u73b0\uff0c\u83ab\u4e0d\u662f\u6392\u961f\u7b49\u6765\u7684\u996d\u7279\u522b\u597d\u5403\uff1f\u600e\u4e48\u6bcf\u4e00\u5bb6\u62c9\u9762\u5c4b\u90fd\u95e8\u5916\u6392\u7740\u7ad9\u5ba2\uff0c\u6211\u770b\u8fd8\u662f\u7ee7\u7eed\u5bfb\u627e\u5f53\u5730\u5473\u9053\u597d\u4e86\u3002\\n\\n\u6e2f\u5f0f\u8336\u9910\u5385\uff0c\u5728\u6211\u4e00\u4e2a\u5916\u5730\u4eba\u5fc3\u76ee\u4e2d\uff0c\u4e00\u76f4\u662f\u907f\u98ce\u5858\u90a3\u6837\u7684\u611f\u811a\u301c \u55ef\uff0c\u597d\u50cf\u753b\u98ce\u53c8\u53d8\u4e86\uff0c\u9999\u6e2f\u4eba\u7279\u522b\u7231\u7528\u8fd9\u51e0\u4e2a\u5b57\u513f\uff1a\u4e3d\uff01\u7f8e\uff01\u534e\uff01\u7fe0\uff01\u7136\u540e\u4e00\u8def\u4fbf\u662f\u8fd9\u6837\u7684\u6392\u5217\u7ec4\u5408\uff1a\u7fe0\u534e\u9910\u5385\uff0c\u7f8e\u534e\u9910\u5385\uff0c\u83b2\u9999\u697c\uff0c\u6dfb\u597d\u8fd0\uff0c\u4e0d\u5f97\u4e0d\u8bf4\u5f88\u9999\u6e2f\u3002\\n\\n\u5728\u9999\u6e2f\u5403\u996d\uff0c\u6709\u70b9\u540d\u5802\u5386\u53f2\u7684\u8001\u5e97\u90fd\u662f\u53c8\u7834\u53c8\u65e7\uff0c\u4f20\u627f\u4e09\u56db\u4ee3\u7279\u522b\u8001\u8d44\u683c\u7684\u90a3\u79cd\uff0c\u5e97\u8001\u677f\u662f\u771f\u7684\u8001\u5230\u813e\u6c14\u81ed\uff0c\u53ea\u8bf4\u7ca4\u8bed\uff0c\u4e0d\u8bf4\u4e5f\u4e0d\u61c2\u6c49\u8bed\u7684\u90a3\u6837\u3002\u6bcf\u6b21\u8fdb\u8fd9\u6837\u7684\u5e97\u6211\u90fd\u5341\u5206\u72b9\u8c6b\uff0c\u8868\u8fbe\u4e0d\u6e05\u6015\u88ab\u9a82\uff0c\u9a82\u4e86\u4e0d\u61c2\u90a3\u66f4\u60e8\uff0c\u8fd9\u662f\u82b1\u94b1\u627e\u9a82\u6765\u4e86\u5417\uff1f\\n\\n\u5927\u9646\u6e38\u5ba2\u591a\u6709\u8fd9\u79cd\u88ab\u603c\u7684\u7ecf\u5386\uff0c\u53ef\u662f\u4e00\u6ce2\u6ce2\u524d\u6765\u6253\u5361\u7684\u5355\u7eaf\u800c\u53ef\u7231\u7684\u4eba\u513f\u4eec\u4f9d\u65e7\u7edc\u7ece\u4e0d\u7edd\uff0c\u4e45\u800c\u4e45\u4e4b\u4fbf\u5f62\u6210\u8fd9\u6837\u7684\u73b0\u8c61\uff1a\u767e\u5e74\u8001\u5e97\u5c0f\u7834\u810f\u4e71\uff0c\u4e0d\u5237\u5361\u66f4\u522b\u63d0\u652f\u4ed8\u5b9d\u516b\u8fbe\u901a\uff0c\u81ea\u5907\u73b0\u91d1\u4e0d\u6536\u5927\u989d\u7eb8\u949e\uff0c\u62fc\u684c\u662f\u5e38\u6001\uff0c\u88ab\u6324\uff0c\u88ab\u6324\uff0c\u88ab\u6324\uff0c\u88ab\u649e\uff0c\u6ca1\u6709\u670d\u52a1\u53ef\u8a00\uff0c\u53cd\u6b63\u7231\u5403\u4e0d\u5403\u95e8\u5916\u8fd8\u6392\u4e00\u5927\u4e32\u3002\\n\\n\u4f46\uff0c\u6e38\u5ba2\u504f\u504f\u5f88\u597d\u8fd9\u4e00\u53e3\u554a\u301c \u5165\u4e61\u968f\u4fd7\uff0c\u6211\u4eec\u987a\u5229\u8fdb\u5165\u201c\u6cbe\u4ed4\u8bb0\u201d\uff0c\u4e00\u4e2a\u5355\u9760\u62db\u724c\u4e91\u541e\u9762\u800c\u53ca\u53d7\u8ffd\u6367\u7684\u7c73\u5176\u6797\u5e73\u6c11\u7f8e\u98df\uff01\\n\\n![Hongkong](./img/hongkong5.jpg)\\n\\n\u201c\u8001\u677f\uff0c\u4e91\u541e\u9762\u3002\u201d\\n\\n\u8001\u4eba\u5bb6\u98de\u901f\u5728\u4fbf\u7b7e\u4e0a\u4e00\u5212\uff0c\u4e00\u5f20\u5947\u602a\u7684\u5355\u5b50\u88ab\u653e\u5728\u684c\u4e0a\uff0c\u6ca1\u6709\u83dc\u540d\u6ca1\u6709\u7f16\u53f7\uff0c\u4e0a\u9762\u53ea\u6709\u4e00\u4e2a60\u3002\\n\\n\u597d\u5427\uff0c\u4e00\u7897\u976230\uff0c\u90a3\u5c31\u662f\u4f60\u7684\u4ef7\u94b1\uff0c\u5403\u5b8c\u51ed\u6b64\u7ed3\u8d26\uff0c\u597d\u50cf\u8fd9\u5c31\u662f\u5e97\u5458\u4e0e\u6536\u94f6\u4e13\u4eab\u7684\u6697\u53f7\u4e00\u6837\uff0c\u522b\u591a\u95ee\u5c31\u8fd9\u4ef7\uff0c\u5728\u7ffb\u684c\u7387\u8d85\u9ad8\u7684\u5c0f\u9910\u5385\u8fd9\u62db\u7279\u522b\u9ad8\u6548\u7387\u3002\\n\\n![Hongkong](./img/hongkong6.jpg)\\n\\n7\u53f7\u7684\u65e9\u6668\uff0c\u6211\u65e0\u610f\u95f4\u5728Youtube\u4e0a\u770b\u5230\u300a\u4e00\u57ce\u4e00\u5473\u300b\u7684\u9999\u6e2f\u90a3\u4e00\u671f\uff0c\u8282\u76ee\u91cc\u8d70\u8857\u4e32\u5df7\u4e86\u597d\u51e0\u5bb6\u4eba\u6c14\u7206\u8868\u7684\u9999\u6e2f\u8001\u5e97\uff0c\u4ec0\u4e48\u86c7\u738b\u82ac\u7684\u86c7\u7fb9\uff0c\u6dfb\u597d\u8fd0\u70b9\u5fc3\u7684\u83e0\u841d\u5305\uff0c\u8fd8\u6709\u4ec0\u4e48\u70e7\u814a\uff0c\u90fd\u6ca1\u592a\u5927\u5174\u8da3\uff0c\u7136\u540e\uff0c\u5170\u82b3\u56ed\u7684\u4e1d\u889c\u5976\u8336\uff0c\u597d\u4e86\uff0c\u679c\u65ad\u51b3\u5b9a\u8bf4\u8d70\u5c31\u8d70\u3002\\n\\n\u4e2d\u73af\u5730\u94c1D2\u51fa\u53e3\uff0c\u76f4\u89c9\u544a\u8bc9\u6211\u5c31\u5728\u9644\u8fd1\uff0c\u5374\u6123\u662f\u88ab\u9ad8\u5fb7\u5730\u56fe\u8bef\u5bfc\u4e86\u534a\u5c0f\u65f6\uff01\u4ece\u6b64\u6211\u53d1\u73b0\u9ad8\u5fb7\u51fa\u4e86\u56fd\u5c31\u5b9a\u4f4d\u4e0d\u51c6\uff0c\u706b\u901f\u6362\u6210\u8c37\u6b4c\u5730\u56fe\u624d\u53d1\u73b0\u81ea\u5df1\u771f\u7684\u662f\u515c\u4e86\u4e00\u5708\uff0c\u8def\u75f4\u5230\u770b\u4e0d\u89c1\u7284\u89d2\u65ee\u65ef\u7684\u5e97\u3002\u8fd9\u7edd\u5bf9\u662f\u6700\u63a5\u5730\u6c14\u7684\u7f51\u7ea2\u5e97\uff0c\u4e0d\u80fd\u518d\u7b80\u6734\u7684\u5e97\u9762\u5df2\u88ab\u56f4\u5f97\u6c34\u6cc4\u4e0d\u901a\uff0c\u6392\u961f\u7684\u4eba\u9a6c\u4e5f\u5df2\u7ad9\u5230\u5bf9\u8857\u3002\\n\\n![Hongkong](./img/hongkong7.jpg)\\n\\n\u65c1\u8fb9\u4e00\u4e2a\u6d41\u52a8\u677f\u623f\u4e00\u6837\u7684\u94fa\u5b50\u5c31\u662f\u4e13\u95e8\u5236\u4f5c\u5976\u8336\u7684\u5730\u65b9\uff0c\u6211\u53ea\u80fd\u770b\u89c1\u7a84\u5c0f\u7684\u7a97\u53e3\u91cc\u4e00\u4e2a\u4eba\u7684\u624b\u81c2\u5728\u4e0d\u505c\u5730\u6765\u56de\u8fc7\u6ee4\u7740\u7ea2\u8336\uff0c\u90a3\u5f62\u72b6\u8c1c\u4e00\u822c\u7684\u6ee4\u888b\u60f3\u5fc5\u5c31\u662f\u201c\u4e1d\u889c\u201d\u7684\u540d\u4e4b\u7531\u6765\u5427\u3002\\n\\n![Hongkong](./img/hongkong8.jpg)\\n\\n\u5750\u662f\u522b\u6307\u671b\u4e86\uff0c\u8fdb\u90fd\u8fdb\u4e0d\u53bb\uff0c\u4e70\u4e86\u5e26\u8d70\u5427\u3002\u5e97\u9762\u524d\u7acb\u7740\u4e00\u4e2a\u5c0f\u67dc\u53f0\uff0c\u4e00\u4f4d\u4e2d\u5e74\u8001\u5988\u5b50\u8d1f\u8d23\u62db\u5f85\u5ba2\u4eba\uff0c\u573a\u9762\u4e00\u7247\u6df7\u4e71\uff0c\u6211\u771f\u4e0d\u77e5\u8be5\u600e\u4e48\u63d2\u5634\uff0c\u4e8e\u662f\u89c2\u5bdf\u4eba\u7c7b\u7684\u7656\u597d\u53c8\u72af\u4e86\uff0c\u5148\u770b\u522b\u4eba\u7684\u64cd\u4f5c\u5427\u3002\\n\\n![Hongkong](./img/hongkong9.jpg)\\n\\n\u6e38\u5ba2\u5927\u591a\u8fdf\u7591\u4e0d\u51b3\u53c8\u4e00\u77e5\u534a\u89e3\uff0c\u770b\u7740\u83dc\u5355\u53c8\u95ee\u4e1c\u95ee\u897f\uff0c\u7ca4\u8bed\u4e0d\u901a\u4e4b\u4e0b\u6c9f\u901a\u4e5f\u4e0d\u7545\u5feb\uff0c\u91cc\u9762\u50ac\u4fc3\u8336\u597d\u4e86\u5feb\u9001\u51fa\u53bb\uff0c\u5916\u9762\u53c8\u548b\u547c\u600e\u4e48\u6ca1\u6709\u7cd6\u5305\uff0c\u8001\u5988\u5b50\u706b\u6c14\u4e0a\u6765\u4e86\uff0c\u5509\u6b64\u60c5\u6b64\u666f\u4e5f\u7b97\u610f\u6599\u4e4b\u4e2d\u3002\\n\\n\u60f3\u5230\u81ea\u5df1\u4e70\u4e32\u9c7c\u86cb\u4e5f\u88ab\u603c\uff0c\u8fd9\u6b21\u7edd\u4e0d\u518d\u5403\u7ca4\u8bed\u4e0d\u901a\u7684\u4e8f\uff0c\u6211\u8fc5\u901f\u7784\u4e86\u4e00\u773c\u83dc\u5355\uff0c\u76f4\u63a5\u51c6\u5907\u597d20\u5143\u96f6\u94b1\u514d\u627e\u96f6\uff0c\u529b\u6c42\u6700\u5927\u5316\u51cf\u5c11\u6c9f\u901a\u7684\u9ebb\u70e6\u3002\\n\\n\u201c\u5c0f\u59b9\u4f60\u8981\u4ec0\u4e48\uff1f\u201d\\n\\n\u201c\u4e1d\u889c\u5976\u8336\uff0c\u70ed\uff0c\u5e26\u8d70\u3002\u201d \u540c\u65f6\u6211\u628a20\u5143\u585e\u5230\u5979\u624b\u4e0a\uff0c\u5c31\u5728\u6211\u4e3a\u81ea\u5df1\u884c\u4e91\u6d41\u6c34\u822c\u7684\u64cd\u4f5c\u81ea\u8c6a\u65f6\u3002\\n\\n\u8001\u5988\u5b50\u6765\u4e86\u4e00\u53e5\uff1a\u201cWait outside.\u201d\\n\\n\u54c8\uff01\uff1f\u8fd9\u59d1\u5976\u5976\u4e86\u5f97\uff0c\u539f\u6765\u4f1a\u82f1\u8bed\uff01\u6211\u670d\uff0c\u4e56\u4e56\u5f97\u7ad9\u5728\u4e00\u65c1\u7b49\u7740\uff0c\u7ee7\u7eed\u770b\u5979\u53f1\u54a4\u98ce\u4e91\u822c\u7684\u73b0\u573a\u6307\u6325\uff0c \u201cYou in, you wait outside.\u201d \u8fd9\u4e2a\u7528\u6765\u603c\u5916\u56fd\u4eba\u5927\u6982\u4e5f\u7ba1\u7528\uff0c\u8fdc\u8fdc\u90a3\u4e48\u770b\u7740\uff0c\u642d\u914d\u90a3\u4e2a\u62db\u724c\u80cc\u666f\u600e\u4e48\u90a3\u4e48\u83ab\u540d\u6233\u4e2d\u7b11\u70b9\u5462\u3002\\n\\n\u5b83\u7684\u7eb8\u676f\u590d\u53e4\u5f97\u50cf\u662f\u4ece\u6e2f\u5267\u8001\u7535\u5f71\u91cc\u8d70\u51fa\u6765\u7684\uff0c\u597d\u559d\u5417\uff1f\u53ea\u6709\u81ea\u5df1\u559d\u8fc7\u624d\u77e5\u9053\u5427\uff0c\u7531\u4e8e\u5b83\u7684\u8336\u5473\u5f88\u91cd\u5012\u662f\u5f88\u7b26\u5408\u6211\u7684\u53e3\u5473\u3002\u518d\u540e\u6765\uff0c\u6211\u5c45\u7136\u5728Vingo\u770b\u89c1\u4e86\u4fbf\u5229\u88c5\uff01\u8fd9\u67b6\u52bf\u5c31\u8ddf\u661f\u5df4\u514b\u8fdb\u8d85\u5e02\u4e00\u6837\uff0c\u6ce8\u610f\uff0c\u559d\u591a\u4e86\u4f1a\u5931\u7720\u3002\\n\\n![Hongkong](./img/hongkong10.jpg)\\n\\n\u5728\u9999\u6e2f\uff0c\u600e\u80fd\u5c11\u4e86\u4e70\u4e70\u4e70\uff0c\u4e8e\u662f\u63a5\u4e0b\u6765\u7684\u4e3b\u8981\u7cbe\u529b\u90fd\u653e\u5728\u6e2f\u5c9b\u533a\u7684\u4e0a\u73af\uff0c\u4e2d\u73af\uff0c\u94dc\u9523\u6e7e\uff0c\u5c16\u6c99\u5480\u8fd9\u51e0\u4e2a\u6700\u7e41\u534e\u4e5f\u662f\u4eba\u6700\u591a\u7684\u5b9d\u5730\u3002\u8fdb\u4e86\u5c16\u6c99\u5480\u7684\u6d77\u6e2f\u57ce\u7ed3\u679c\u4e00\u5929\u4e5f\u6ca1\u901b\u51fa\u5c3d\u5934\uff0c\u4e5f\u4e0d\u8bb0\u5f97\u6211\u5230\u5e95\u4ece\u54ea\u4e2a\u5165\u53e3\u8fdb\u7684\uff0c\u51fa\u6765\u65f6\u53d1\u73b0\u5929\u90fd\u9ed1\u4e86\uff0c\u800c\u4e14\u5df2\u7ecf\u83ab\u540d\u7f6e\u8eab\u5728\u7ef4\u591a\u5229\u4e9a\u6e2f\u7684\u5cb8\u8fb9\uff0c\u597d\u50cf\u5e76\u6ca1\u610f\u8bc6\u5230\u8d70\u4e86\u4e00\u5929\u90fd\u5728\u5efa\u7b51\u7fa4\u91cc\u3002\\n\\n\u591c\u665a\u770b\u7740\u7ef4\u591a\u5229\u4e9a\u6e2f\u53e3\uff0c\u6211\u7adf\u4ea7\u751f\u4e86\u8fd9\u662f\u5916\u6ee9\u7684\u9519\u89c9\uff01\u4e00\u5b9a\u662f\u8d2d\u7269\u5bfc\u81f4\u7684\u5934\u8111\u4e0d\u6e05\u6670\uff0c\u6211\u5411\u5cb8\u8fb9\u7ee7\u7eed\u8d70\u8fd1\uff0c\u8fce\u9762\u51b7\u98ce\u4e00\u5439\uff0c\u8fd8\u5939\u6742\u7740\u6c34\u5473\uff0c\u7279\u522b\u81ed\uff0c\u6e05\u9192\u4e86\u3002\u4f46\u6211\u4f9d\u65e7\u89c9\u5f97\u9713\u8679\u706f\u4e0b\u7684\u5927\u90fd\u5e02\uff0c\u82e5\u4e0d\u51ed\u501f\u5730\u6807\u8fa8\u8ba4\uff0c\u8fd8\u771f\u662f\u597d\u50cf\u3002\u591c\u665a\u4e03\u516b\u70b9\u7684\u9999\u6e2f\uff0c\u4e0a\u6d77\uff0c\u7ebd\u7ea6\uff0c\u829d\u52a0\u54e5\u600e\u4e48\u6709\u79cd\u83ab\u540d\u795e\u4f3c\uff0c\u719f\u6089\u611f\u4e2d\u5bfb\u627e\u4e0d\u540c\uff0c\u56e0\u4e3a\u4e2d\u94f6\u5927\u53a6\uff0c\u4e1c\u65b9\u660e\u73e0\uff0c\u5e03\u9c81\u514b\u6797\u5927\u6865\uff0cTrump\u5927\u697c\uff0c\u90fd\u5e02\u7684\u5929\u9645\u7ebf\u624d\u4e0d\u540c\u3002\\n\\n![Hongkong](./img/hongkong11.jpg)\\n\\n\uff08\u81ea\u4e0a\u800c\u4e0b\u5206\u522b\u662f\u9999\u6e2f\u7ef4\u591a\u5229\u4e9a\uff0c\u4e0a\u6d77\u5916\u6ee9\uff0c\u7ebd\u7ea6\u66fc\u54c8\u987f\uff0c\u829d\u52a0\u54e5\u3002\uff09\\n\\n\u5dee\u70b9\u5fd8\u4e86\u8bf4\u6211\u4eec\u722c\u5c71\u7684\u58ee\u4e3e\uff0c\u4ece\u6e2f\u5927\u7eaf\u4f53\u529b\u722c\u5230\u592a\u5e73\u5c71\u9876\uff0c\u592a\u9178\u723d\uff01\u53c8\u5174\u51b2\u51b2\u4e0a\u4e86\u51cc\u9704\u9601\uff0c\u5c31\u5dee\u4e34\u95e8\u4e00\u811a\u62cd\u5f20\u7f8e\u7f8e\u7684\uff0c\u8c01\u77e5\u662f\u5927\u96fe\u5929\u3002\\n\\n![Hongkong](./img/hongkong12.jpg)\\n\\n\u5176\u5b9e\u9999\u6e2f\u5bf9\u4e8e\u6211\u6700\u5927\u7684\u5438\u5f15\u529b\u5e76\u4e0d\u5728\u4e8e\u7e41\u534e\u7684\u91d1\u878d\u5546\u5708\uff0c\u800c\u662f\u4e00\u4e9b\u60ac\u4e8e\u8fb9\u754c\u4e0a\u7684\u6587\u5316\u548c\u98ce\u666f\u3002\\n\\n![Hongkong](./img/hongkong13.jpg)\\n\\n\u90a3\u4e9b\u4e0d\u592a\u5bb9\u6613\u5165\u773c\u7684\u4e1c\u897f\uff0c\u6216\u50cf\u9a91\u697c\u4e4b\u7c7b\u7279\u522b\u53e4\u65e7\u7684\u4e8b\u7269\uff0c\u5c31\u90a3\u4e48\u5ba0\u8fb1\u4e0d\u60ca\u5730\u7a7f\u63d2\u4e8e\u6700\u7e41\u534e\u5fd9\u788c\u7684\u5730\u6bb5\uff0c\u5b83\u4eec\u624d\u662f\u9999\u6e2f\u6700\u672c\u571f\u6700\u672c\u771f\u7684\u5185\u6db5\u3002\\n\\n\u800c\u4e0d\u7ba1\u5916\u6765\u4eba\u53e3\u548c\u897f\u6d0b\u6587\u5316\u600e\u4e48\u6e17\u5165\uff0c\u60dc\u65f6\u5982\u91d1\u7684\u767d\u9886\u7cbe\u82f1\u600e\u4e48\u811a\u6b65\u4e0d\u505c\uff0c\u697c\u4e0b\u8f66\u6c34\u9a6c\u9f99\u600e\u4e48\u7a7f\u68ad\u4e0d\u606f\uff0c\u697c\u4e0a\u4f9d\u65e7\u5e8a\u5355\u5185\u8863\u98d8\u6447\uff0c\u201c\u8001\u9999\u6e2f\u201d \u7528\u5b83\u7279\u6709\u7684\u59ff\u6001\u4e0d\u5c51\u4e8e\u8fd9\u4e2a\u65f6\u4ee3\u7684\u6f6e\u6d41\u51b2\u51fb\u3002\\n\\n![Hongkong](./img/hongkong14.jpg)\\n\\n\u773c\u524d\u7684\u666f\u8c61\u5e38\u7a81\u53d8\u5f97\u4ee4\u6211\u63aa\u624b\u4e0d\u53ca\u3002\u8fd9\u91cc\u571f\u6d0b\u7ed3\u5408\uff0c\u73b0\u4ee3\u5316\u98de\u901f\u5411\u524d\u7684\u540c\u65f6\uff0c\u4f20\u7edf\u4e5f\u4ece\u672a\u6d88\u5931\u3002\\n\\n![Hongkong](./img/hongkong15.jpg)\\n\\n\u4f46\u4e0d\u77e5\u9053\u8fd9\u6837\u7684\u666f\u8272\uff0c\u8fd8\u80fd\u62e5\u6709\u591a\u4e45\uff0c\u4ee5\u540e\u53c8\u4f1a\u5728\u54ea\u4e00\u5929\u9500\u58f0\u533f\u8ff9\u4e86\u3002\\n\\n![Hongkong](./img/hongkong16.jpg)\\n\\n\u6700\u540e\uff0c\u603b\u542c\u5404\u79cd\u5173\u4e8e\u9999\u6e2f\u4f4f\u5bbf\u95ee\u9898\u7684\u5410\u69fd\uff0c\u5c0f\u8fd8\u8d35\u3002\u6211\u5e78\u8fd0\u5730\u8e6d\u4f4f\u5728\u6e2f\u5927\u5bbf\u820d\u91cc\uff0c\u65e9\u51fa\u665a\u5f52\u8ddf\u6e2f\u5927\u7684\u95e8\u536b\u5927\u7237\u6df7\u51fa\u4e86\u8138\u719f\uff0c\u65e2\u7136\u5982\u6b64\u5c31\u4e0d\u5410\u69fd\u9999\u6e2f\u4eba\u5747\u5c45\u4f4f\u9762\u79ef\u4e4b\u5c0f\u4e86\u3002\u603b\u4e4b\uff0c\u6298\u56de\u6df1\u5733\u5230\u5bb6\u7b2c\u4e00\u4ef6\u4e8b\u5c31\u662f\uff1a\u653e\u4e0b\u884c\u674e\uff0c\u4f38\u61d2\u8170\uff01\\n\\n![Hongkong](./img/hongkong17.jpg)"}]}}')}}]);